export default {
  "en": {
    "quran.114_1_translation": "Say, \"I seek refuge in the Lord of mankind,",
    "quran.114_2_translation": "The Sovereign of mankind.",
    "quran.114_3_translation": "The God of mankind,",
    "quran.114_4_translation": "From the evil of the retreating whisperer -",
    "quran.114_5_translation": "Who whispers [evil] into the breasts of mankind -",
    "quran.114_6_translation": "From among the jinn and mankind.\"",
    "quran.113_1_translation": "Say, \"I seek refuge in the Lord of daybreak",
    "quran.113_2_translation": "From the evil of that which He created",
    "quran.113_3_translation": "And from the evil of darkness when it settles",
    "quran.113_4_translation": "And from the evil of the blowers in knots",
    "quran.113_5_translation": "And from the evil of an envier when he envies.\"",
    "quran.112_1_translation": "Say, \"He is Allah, [who is] One,",
    "quran.112_2_translation": "Allah, the Eternal Refuge.",
    "quran.112_3_translation": "He neither begets nor is born,",
    "quran.112_4_translation": "Nor is there to Him any equivalent.\"",
    "quran.111_1_translation": "May the hands of Abu Lahab be ruined, and ruined is he.",
    "quran.111_2_translation": "His wealth will not avail him or that which he gained.",
    "quran.111_3_translation": "He will [enter to] burn in a Fire of [blazing] flame",
    "quran.111_4_translation": "And his wife [as well] - the carrier of firewood.",
    "quran.111_5_translation": "Around her neck is a rope of [twisted] fiber.",
    "quran.110_1_translation": "When the victory of Allah has come and the conquest,",
    "quran.110_2_translation": "And you see the people entering into the religion of Allah in multitudes,",
    "quran.110_3_translation": "Then exalt [Him] with praise of your Lord and ask forgiveness of Him. Indeed, He is ever Accepting of repentance.",
    "quran.109_1_translation": "Say, \"O disbelievers,",
    "quran.109_2_translation": "I do not worship what you worship.",
    "quran.109_3_translation": "Nor are you worshippers of what I worship.",
    "quran.109_4_translation": "Nor will I be a worshipper of what you worship.",
    "quran.109_5_translation": "Nor will you be worshippers of what I worship.",
    "quran.109_6_translation": "For you is your religion, and for me is my religion.\"",
    "quran.108_1_translation": "Indeed, We have granted you, [O Muhammad], al-Kawthar.",
    "quran.108_2_translation": "So pray to your Lord and sacrifice [to Him alone].",
    "quran.108_3_translation": "Indeed, your enemy is the one cut off.",
    "quran.107_1_translation": "Have you seen the one who denies the Recompense?",
    "quran.107_2_translation": "For that is the one who drives away the orphan",
    "quran.107_3_translation": "And does not encourage the feeding of the poor.",
    "quran.107_4_translation": "So woe to those who pray",
    "quran.107_5_translation": "[But] who are heedless of their prayer -",
    "quran.107_6_translation": "Those who make show [of their deeds]",
    "quran.107_7_translation": "And withhold [simple] assistance.",
    "quran.106_1_translation": "For the accustomed security of the Quraysh -",
    "quran.106_2_translation": "Their accustomed security [in] the caravan of winter and summer -",
    "quran.106_3_translation": "Let them worship the Lord of this House,",
    "quran.106_4_translation": "Who has fed them, [saving them] from hunger and made them safe, [saving them] from fear.",
    "quran.105_1_translation": "Have you not considered, [O Muhammad], how your Lord dealt with the companions of the elephant?",
    "quran.105_2_translation": "Did He not make their plan into misguidance?",
    "quran.105_3_translation": "And He sent against them birds in flocks,",
    "quran.105_4_translation": "Striking them with stones of hard clay,",
    "quran.105_5_translation": "And He made them like eaten straw.",
    "quran.104_1_translation": "Woe to every scorner and mocker",
    "quran.104_2_translation": "Who collects wealth and [continuously] counts it.",
    "quran.104_3_translation": "He thinks that his wealth will make him immortal.",
    "quran.104_4_translation": "No! He will surely be thrown into the Crusher.",
    "quran.104_5_translation": "And what can make you know what is the Crusher?",
    "quran.104_6_translation": "It is the fire of Allah, [eternally] fueled,",
    "quran.104_7_translation": "Which mounts directed at the hearts.",
    "quran.104_8_translation": "Indeed, Hellfire will be closed down upon them",
    "quran.104_9_translation": "In extended columns.",
    "quran.103_1_translation": "By time,",
    "quran.103_2_translation": "Indeed, mankind is in loss,",
    "quran.103_3_translation": "Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience.",
    "quran.102_1_translation": "Competition in [worldly] increase diverts you",
    "quran.102_2_translation": "Until you visit the graveyards.",
    "quran.102_3_translation": "No! You are going to know.",
    "quran.102_4_translation": "Then no! You are going to know.",
    "quran.102_5_translation": "No! If you only knew with knowledge of certainty...",
    "quran.102_6_translation": "You will surely see the Hellfire.",
    "quran.102_7_translation": "Then you will surely see it with the eye of certainty.",
    "quran.102_8_translation": "Then you will surely be asked that Day about pleasure.",
    "quran.101_1_translation": "The Striking Calamity -",
    "quran.101_2_translation": "What is the Striking Calamity?",
    "quran.101_3_translation": "And what can make you know what is the Striking Calamity?",
    "quran.101_4_translation": "It is the Day when people will be like moths, dispersed,",
    "quran.101_5_translation": "And the mountains will be like wool, fluffed up.",
    "quran.101_6_translation": "Then as for one whose scales are heavy [with good deeds],",
    "quran.101_7_translation": "He will be in a pleasant life.",
    "quran.101_8_translation": "But as for one whose scales are light,",
    "quran.101_9_translation": "His refuge will be an abyss.",
    "quran.101_10_translation": "And what can make you know what that is?",
    "quran.101_11_translation": "It is a Fire, intensely hot.",
    "quran.100_1_translation": "By the racers, panting,",
    "quran.100_2_translation": "And the producers of sparks [when] striking",
    "quran.100_3_translation": "And the chargers at dawn,",
    "quran.100_4_translation": "Stirring up thereby [clouds of] dust,",
    "quran.100_5_translation": "Arriving thereby in the center collectively,",
    "quran.100_6_translation": "Indeed mankind, to his Lord, is ungrateful.",
    "quran.100_7_translation": "And indeed, he is to that a witness.",
    "quran.100_8_translation": "And indeed he is, in love of wealth, intense.",
    "quran.100_9_translation": "But does he not know that when the contents of the graves are scattered",
    "quran.100_10_translation": "And that within the breasts is obtained,",
    "quran.100_11_translation": "Indeed, their Lord with them, that Day, is [fully] Acquainted.",
    "quran.99_1_translation": "When the earth is shaken with its [final] earthquake",
    "quran.99_2_translation": "And the earth discharges its burdens",
    "quran.99_3_translation": "And man says, \"What is [wrong] with it?\" -",
    "quran.99_4_translation": "That Day, it will report its news",
    "quran.99_5_translation": "Because your Lord has commanded it.",
    "quran.99_6_translation": "That Day, the people will depart separated [into categories] to be shown [the result of] their deeds.",
    "quran.99_7_translation": "So whoever does an atom's weight of good will see it,",
    "quran.99_8_translation": "And whoever does an atom's weight of evil will see it.",
    "quran.98_1_translation": "Those who disbelieved among the People of the Scripture and the polytheists were not to be parted [from misbelief] until there came to them clear evidence -",
    "quran.98_2_translation": "A Messenger from Allah, reciting purified scriptures",
    "quran.98_3_translation": "Within which are correct writings.",
    "quran.98_4_translation": "Nor did those who were given the Scripture become divided until after there had come to them clear evidence.",
    "quran.98_5_translation": "And they were not commanded except to worship Allah, [being] sincere to Him in religion, inclining to truth, and to establish prayer and to give zakah. And that is the correct religion.",
    "quran.98_6_translation": "Indeed, they who disbelieved among the People of the Scripture and the polytheists will be in the fire of Hell, abiding eternally therein. Those are the worst of creatures.",
    "quran.98_7_translation": "Indeed, they who have believed and done righteous deeds - those are the best of creatures.",
    "quran.98_8_translation": "Their reward with Allah will be gardens of perpetual residence beneath which rivers flow, wherein they will abide forever, Allah being pleased with them and they with Him. That is for whoever has feared his Lord.",
    "quran.97_1_translation": "Indeed, We sent the Qur'an down during the Night of Decree.",
    "quran.97_2_translation": "And what can make you know what is the Night of Decree?",
    "quran.97_3_translation": "The Night of Decree is better than a thousand months.",
    "quran.97_4_translation": "The angels and the Spirit descend therein by permission of their Lord for every matter.",
    "quran.97_5_translation": "Peace it is until the emergence of dawn.",
    "quran.96_1_translation": "Recite in the name of your Lord who created -",
    "quran.96_2_translation": "Created man from a clinging substance.",
    "quran.96_3_translation": "Recite, and your Lord is the most Generous -",
    "quran.96_4_translation": "Who taught by the pen -",
    "quran.96_5_translation": "Taught man that which he knew not.",
    "quran.96_6_translation": "No! [But] indeed, man transgresses",
    "quran.96_7_translation": "Because he sees himself self-sufficient.",
    "quran.96_8_translation": "Indeed, to your Lord is the return.",
    "quran.96_9_translation": "Have you seen the one who forbids",
    "quran.96_10_translation": "A servant when he prays?",
    "quran.96_11_translation": "Have you seen if he is upon guidance",
    "quran.96_12_translation": "Or enjoins righteousness?",
    "quran.96_13_translation": "Have you seen if he denies and turns away -",
    "quran.96_14_translation": "Does he not know that Allah sees?",
    "quran.96_15_translation": "No! If he does not desist, We will surely drag him by the forelock -",
    "quran.96_16_translation": "A lying, sinning forelock.",
    "quran.96_17_translation": "Then let him call his associates;",
    "quran.96_18_translation": "We will call the angels of Hell.",
    "quran.96_19_translation": "No! Do not obey him. But prostrate and draw near [to Allah].",
    "quran.95_1_translation": "By the fig and the olive",
    "quran.95_2_translation": "And [by] Mount Sinai",
    "quran.95_3_translation": "And [by] this secure city [Makkah],",
    "quran.95_4_translation": "We have certainly created man in the best of stature;",
    "quran.95_5_translation": "Then We return him to the lowest of the low,",
    "quran.95_6_translation": "Except for those who believe and do righteous deeds, for they will have a reward uninterrupted.",
    "quran.95_7_translation": "So what yet causes you to deny the Recompense?",
    "quran.95_8_translation": "Is not Allah the most just of judges?",
    "quran.93_1_translation": "By the morning brightness",
    "quran.93_2_translation": "And [by] the night when it covers with darkness,",
    "quran.93_3_translation": "Your Lord has not taken leave of you, [O Muhammad], nor has He detested [you].",
    "quran.93_4_translation": "And the Hereafter is better for you than the first [life].",
    "quran.93_5_translation": "And your Lord is going to give you, and you will be satisfied.",
    "quran.93_6_translation": "Did He not find you an orphan and give [you] refuge?",
    "quran.93_7_translation": "And He found you lost and guided [you],",
    "quran.93_8_translation": "And He found you poor and made [you] self-sufficient.",
    "quran.93_9_translation": "So as for the orphan, do not oppress [him].",
    "quran.93_10_translation": "And as for the petitioner, do not repel [him].",
    "quran.93_11_translation": "But as for the favor of your Lord, report [it].",
    "quran.92_1_translation": "By the night when it covers",
    "quran.92_2_translation": "And [by] the day when it appears",
    "quran.92_3_translation": "And [by] He who created the male and female,",
    "quran.92_4_translation": "Indeed, your efforts are diverse.",
    "quran.92_5_translation": "As for he who gives and fears Allah",
    "quran.92_6_translation": "And believes in the best [reward],",
    "quran.92_7_translation": "We will ease him toward ease.",
    "quran.92_8_translation": "But as for he who withholds and considers himself free of need",
    "quran.92_9_translation": "And denies the best [reward],",
    "quran.92_10_translation": "We will ease him toward difficulty.",
    "quran.92_11_translation": "And what will his wealth avail him when he falls?",
    "quran.92_12_translation": "Indeed, [incumbent] upon Us is guidance.",
    "quran.92_13_translation": "And indeed, to Us belongs the Hereafter and the first [life].",
    "quran.92_14_translation": "So I have warned you of a Fire which is blazing.",
    "quran.92_15_translation": "None will [enter to] burn therein except the most wretched one.",
    "quran.92_16_translation": "Who had denied and turned away.",
    "quran.92_17_translation": "But the righteous one will avoid it -",
    "quran.92_18_translation": "[He] who gives [from] his wealth to purify himself",
    "quran.92_19_translation": "And not [giving] for anyone who has [done him] a favor to be rewarded",
    "quran.92_20_translation": "But only seeking the countenance of his Lord, Most High.",
    "quran.92_21_translation": "And he is going to be satisfied.",
    "quran.91_1_translation": "By the sun and its brightness",
    "quran.91_2_translation": "And [by] the moon when it follows it",
    "quran.91_3_translation": "And [by] the day when it displays it",
    "quran.91_4_translation": "And [by] the night when it covers it",
    "quran.91_5_translation": "And [by] the sky and He who constructed it",
    "quran.91_6_translation": "And [by] the earth and He who spread it",
    "quran.91_7_translation": "And [by] the soul and He who proportioned it",
    "quran.91_8_translation": "And inspired it [with discernment of] its wickedness and its righteousness,",
    "quran.91_9_translation": "He has succeeded who purifies it,",
    "quran.91_10_translation": "And he has failed who instills it [with corruption].",
    "quran.91_11_translation": "Thamud denied [their prophet] by reason of their transgression,",
    "quran.91_12_translation": "When the most wretched of them was sent forth.",
    "quran.91_13_translation": "And the messenger of Allah [Salih] said to them, \"[Do not harm] the she-camel of Allah or [prevent her from] her drink.\"",
    "quran.91_14_translation": "But they denied him and hamstrung her. So their Lord brought down upon them destruction for their sin and made it equal [upon all of them].",
    "quran.91_15_translation": "And He does not fear the consequence thereof.",
    "quran.90_1_translation": "I swear by this city, Makkah -",
    "quran.90_2_translation": "And you, [O Muhammad], are free of restriction in this city -",
    "quran.90_3_translation": "And [by] the father and that which was born [of him],",
    "quran.90_4_translation": "We have certainly created man into hardship.",
    "quran.90_5_translation": "Does he think that never will anyone overcome him?",
    "quran.90_6_translation": "He says, \"I have spent wealth in abundance.\"",
    "quran.90_7_translation": "Does he think that no one has seen him?",
    "quran.90_8_translation": "Have We not made for him two eyes?",
    "quran.90_9_translation": "And a tongue and two lips?",
    "quran.90_10_translation": "And have shown him the two ways?",
    "quran.90_11_translation": "But he has not broken through the difficult pass.",
    "quran.90_12_translation": "And what can make you know what is [breaking through] the difficult pass?",
    "quran.90_13_translation": "It is the freeing of a slave",
    "quran.90_14_translation": "Or feeding on a day of severe hunger",
    "quran.90_15_translation": "An orphan of near relationship",
    "quran.90_16_translation": "Or a needy person in misery",
    "quran.90_17_translation": "And then being among those who believed and advised one another to patience and advised one another to compassion.",
    "quran.90_18_translation": "Those are the companions of the right.",
    "quran.90_19_translation": "But they who disbelieved in Our signs - those are the companions of the left.",
    "quran.90_20_translation": "Over them will be fire closed in.",
    "quran.89_1_translation": "By the dawn",
    "quran.89_2_translation": "And [by] ten nights",
    "quran.89_3_translation": "And [by] the even [number] and the odd",
    "quran.89_4_translation": "And [by] the night when it passes,",
    "quran.89_5_translation": "Is there [not] in [all] that an oath [sufficient] for one of perception?",
    "quran.89_6_translation": "Have you not considered how your Lord dealt with 'Aad -",
    "quran.89_7_translation": "[With] Iram - who had lofty pillars,",
    "quran.89_8_translation": "The likes of whom had never been created in the land?",
    "quran.89_9_translation": "And [with] Thamud, who carved out the rocks in the valley?",
    "quran.89_10_translation": "And [with] Pharaoh, owner of the stakes? -",
    "quran.89_11_translation": "[All of] whom oppressed within the lands",
    "quran.89_12_translation": "And increased therein the corruption.",
    "quran.89_13_translation": "So your Lord poured upon them a scourge of punishment.",
    "quran.89_14_translation": "Indeed, your Lord is in observation.",
    "quran.89_15_translation": "And as for man, when his Lord tries him and [thus] is generous to him and favors him, he says, \"My Lord has honored me.\"",
    "quran.89_16_translation": "But when He tries him and restricts his provision, he says, \"My Lord has humiliated me.\"",
    "quran.89_17_translation": "No! But you do not honor the orphan",
    "quran.89_18_translation": "And you do not encourage one another to feed the poor.",
    "quran.89_19_translation": "And you consume inheritance, devouring [it] altogether,",
    "quran.89_20_translation": "And you love wealth with immense love.",
    "quran.89_21_translation": "No! When the earth has been leveled - pounded and crushed -",
    "quran.89_22_translation": "And your Lord has come and the angels, rank upon rank,",
    "quran.89_23_translation": "And brought [within view], that Day, is Hell - that Day, man will remember, but what good to him will be the remembrance?",
    "quran.89_24_translation": "He will say, \"Oh, I wish I had sent ahead [some good] for my life.\"",
    "quran.89_25_translation": "So on that Day, none will punish [as severely] as His punishment,",
    "quran.89_26_translation": "And none will bind [as severely] as His binding [of the evildoers].",
    "quran.89_27_translation": "[To the righteous it will be said], \"O reassured soul,",
    "quran.89_28_translation": "Return to your Lord, well-pleased and pleasing [to Him],",
    "quran.89_29_translation": "And enter among My [righteous] servants",
    "quran.89_30_translation": "And enter My Paradise.\"",
    "quran.88_1_translation": "Has there reached you the report of the Overwhelming [event]?",
    "quran.88_2_translation": "[Some] faces, that Day, will be humbled,",
    "quran.88_3_translation": "Working [hard] and exhausted.",
    "quran.88_4_translation": "They will [enter to] burn in an intensely hot Fire.",
    "quran.88_5_translation": "They will be given drink from a boiling spring.",
    "quran.88_6_translation": "For them there will be no food except from a poisonous, thorny plant",
    "quran.88_7_translation": "Which neither nourishes nor avails against hunger.",
    "quran.88_8_translation": "[Other] faces, that Day, will show pleasure.",
    "quran.88_9_translation": "With their effort [they are] satisfied",
    "quran.88_10_translation": "In an elevated garden,",
    "quran.88_11_translation": "Wherein they will hear no unsuitable speech.",
    "quran.88_12_translation": "Within it is a flowing spring.",
    "quran.88_13_translation": "Within it are couches raised high",
    "quran.88_14_translation": "And cups put in place",
    "quran.88_15_translation": "And cushions lined up",
    "quran.88_16_translation": "And carpets spread around.",
    "quran.88_17_translation": "Then do they not look at the camels - how they are created?",
    "quran.88_18_translation": "And at the sky - how it is raised?",
    "quran.88_19_translation": "And at the mountains - how they are erected?",
    "quran.88_20_translation": "And at the earth - how it is spread out?",
    "quran.88_21_translation": "So remind, [O Muhammad]; you are only a reminder.",
    "quran.88_22_translation": "You are not over them a controller.",
    "quran.88_23_translation": "However, he who turns away and disbelieves -",
    "quran.88_24_translation": "Then Allah will punish him with the greatest punishment.",
    "quran.88_25_translation": "Indeed, to Us is their return.",
    "quran.88_26_translation": "Then indeed, upon Us is their account.",
    "quran.87_1_translation": "Exalt the name of your Lord, the Most High,",
    "quran.87_2_translation": "Who created and proportioned",
    "quran.87_3_translation": "And who destined and [then] guided",
    "quran.87_4_translation": "And who brings out the pasture",
    "quran.87_5_translation": "And [then] makes it black stubble.",
    "quran.87_6_translation": "We will make you recite, [O Muhammad], and you will not forget,",
    "quran.87_7_translation": "Except what Allah should will. Indeed, He knows what is declared and what is hidden.",
    "quran.87_8_translation": "And We will ease you toward ease.",
    "quran.87_9_translation": "So remind, if the reminder should benefit;",
    "quran.87_10_translation": "He who fears [Allah] will be reminded.",
    "quran.87_11_translation": "But the wretched one will avoid it -",
    "quran.87_12_translation": "[He] who will [enter and] burn in the greatest Fire,",
    "quran.87_13_translation": "Neither dying therein nor living.",
    "quran.87_14_translation": "He has certainly succeeded who purifies himself",
    "quran.87_15_translation": "And mentions the name of his Lord and prays.",
    "quran.87_16_translation": "But you prefer the worldly life,",
    "quran.87_17_translation": "While the Hereafter is better and more enduring.",
    "quran.87_18_translation": "Indeed, this is in the former scriptures,",
    "quran.87_19_translation": "The scriptures of Abraham and Moses.",
    "quran.86_1_translation": "By the sky and the night comer -",
    "quran.86_2_translation": "And what can make you know what is the night comer?",
    "quran.86_3_translation": "It is the piercing star -",
    "quran.86_4_translation": "There is no soul but that it has over it a protector.",
    "quran.86_5_translation": "So let man observe from what he was created.",
    "quran.86_6_translation": "He was created from a fluid, ejected,",
    "quran.86_7_translation": "Emerging from between the backbone and the ribs.",
    "quran.86_8_translation": "Indeed, Allah, to return him [to life], is Able.",
    "quran.86_9_translation": "The Day when secrets will be put on trial,",
    "quran.86_10_translation": "Then man will have no power or any helper.",
    "quran.86_11_translation": "By the sky which returns [rain]",
    "quran.86_12_translation": "And [by] the earth which cracks open,",
    "quran.86_13_translation": "Indeed, the Qur'an is a decisive statement,",
    "quran.86_14_translation": "And it is not amusement.",
    "quran.86_15_translation": "Indeed, they are planning a plan,",
    "quran.86_16_translation": "But I am planning a plan.",
    "quran.86_17_translation": "So allow time for the disbelievers. Leave them awhile.",
    "quran.85_1_translation": "By the sky containing great stars",
    "quran.85_2_translation": "And [by] the promised Day",
    "quran.85_3_translation": "And [by] the witness and what is witnessed,",
    "quran.85_4_translation": "Cursed were the companions of the trench",
    "quran.85_5_translation": "[Containing] the fire full of fuel,",
    "quran.85_6_translation": "When they were sitting near it",
    "quran.85_7_translation": "And they, to what they were doing against the believers, were witnesses.",
    "quran.85_8_translation": "And they resented them not except because they believed in Allah, the Exalted in Might, the Praiseworthy,",
    "quran.85_9_translation": "To whom belongs the dominion of the heavens and the earth. And Allah, over all things, is Witness.",
    "quran.85_10_translation": "Indeed, those who have tortured the believing men and believing women and then have not repented will have the punishment of Hell, and they will have the punishment of the Burning Fire.",
    "quran.85_11_translation": "Indeed, those who have believed and done righteous deeds will have gardens beneath which rivers flow. That is the great attainment.",
    "quran.85_12_translation": "Indeed, the vengeance of your Lord is severe.",
    "quran.85_13_translation": "Indeed, it is He who originates [creation] and repeats.",
    "quran.85_14_translation": "And He is the Forgiving, the Affectionate,",
    "quran.85_15_translation": "Honorable Owner of the Throne,",
    "quran.85_16_translation": "Effecter of what He intends.",
    "quran.85_17_translation": "Has there reached you the story of the soldiers -",
    "quran.85_18_translation": "[Those of] Pharaoh and Thamud?",
    "quran.85_19_translation": "But they who disbelieve are in [persistent] denial,",
    "quran.85_20_translation": "While Allah encompasses them from behind.",
    "quran.85_21_translation": "But this is an honored Qur'an",
    "quran.85_22_translation": "[Inscribed] in a Preserved Slate.",
    "quran.84_1_translation": "When the sky has split [open]",
    "quran.84_2_translation": "And has responded to its Lord and was obligated [to do so]",
    "quran.84_3_translation": "And when the earth has been extended",
    "quran.84_4_translation": "And has cast out that within it and relinquished [it]",
    "quran.84_5_translation": "And has responded to its Lord and was obligated [to do so] -",
    "quran.84_6_translation": "O mankind, indeed you are laboring toward your Lord with [great] exertion and will meet it.",
    "quran.84_7_translation": "Then as for he who is given his record in his right hand,",
    "quran.84_8_translation": "He will be judged with an easy account",
    "quran.84_9_translation": "And return to his people in happiness.",
    "quran.84_10_translation": "But as for he who is given his record behind his back,",
    "quran.84_11_translation": "He will cry out for destruction",
    "quran.84_12_translation": "And [enter to] burn in a Blaze.",
    "quran.84_13_translation": "Indeed, he had [once] been among his people in happiness;",
    "quran.84_14_translation": "Indeed, he had thought he would never return [to Allah].",
    "quran.84_15_translation": "But yes! Indeed, his Lord was ever of him, Seeing.",
    "quran.84_16_translation": "So I swear by the twilight glow",
    "quran.84_17_translation": "And [by] the night and what it envelops",
    "quran.84_18_translation": "And [by] the moon when it becomes full",
    "quran.84_19_translation": "[That] you will surely experience state after state.",
    "quran.84_20_translation": "So what is [the matter] with them [that] they do not believe,",
    "quran.84_21_translation": "And when the Qur'an is recited to them, they do not prostrate [to Allah]?",
    "quran.84_22_translation": "But those who have disbelieved deny,",
    "quran.84_23_translation": "And Allah is most knowing of what they keep within themselves.",
    "quran.84_24_translation": "So give them tidings of a painful punishment,",
    "quran.84_25_translation": "Except for those who believe and do righteous deeds. For them is a reward uninterrupted.",
    "quran.83_1_translation": "Woe to those who give less [than due],",
    "quran.83_2_translation": "Who, when they take a measure from people, take in full.",
    "quran.83_3_translation": "But if they give by measure or by weight to them, they cause loss.",
    "quran.83_4_translation": "Do they not think that they will be resurrected",
    "quran.83_5_translation": "For a tremendous Day -",
    "quran.83_6_translation": "The Day when mankind will stand before the Lord of the worlds?",
    "quran.83_7_translation": "No! Indeed, the record of the wicked is in sijjeen.",
    "quran.83_8_translation": "And what can make you know what is sijjeen?",
    "quran.83_9_translation": "It is [their destination recorded in] a register inscribed.",
    "quran.83_10_translation": "Woe, that Day, to the deniers,",
    "quran.83_11_translation": "Who deny the Day of Recompense.",
    "quran.83_12_translation": "And none deny it except every sinful transgressor.",
    "quran.83_13_translation": "When Our verses are recited to him, he says, \"Legends of the former peoples.\"",
    "quran.83_14_translation": "No! Rather, the stain has covered their hearts of that which they were earning.",
    "quran.83_15_translation": "No! Indeed, from their Lord, that Day, they will be partitioned.",
    "quran.83_16_translation": "Then indeed, they will [enter and] burn in Hellfire.",
    "quran.83_17_translation": "Then it will be said [to them], \"This is what you used to deny.\"",
    "quran.83_18_translation": "No! Indeed, the record of the righteous is in 'illiyyun.",
    "quran.83_19_translation": "And what can make you know what is 'illiyyun?",
    "quran.83_20_translation": "It is [their destination recorded in] a register inscribed",
    "quran.83_21_translation": "Which is witnessed by those brought near [to Allah].",
    "quran.83_22_translation": "Indeed, the righteous will be in pleasure",
    "quran.83_23_translation": "On adorned couches, observing.",
    "quran.83_24_translation": "You will recognize in their faces the radiance of pleasure.",
    "quran.83_25_translation": "They will be given to drink [pure] wine [which was] sealed.",
    "quran.83_26_translation": "The last of it is musk. So for this let the competitors compete.",
    "quran.83_27_translation": "And its mixture is of Tasneem,",
    "quran.83_28_translation": "A spring from which those near [to Allah] drink.",
    "quran.83_29_translation": "Indeed, those who committed crimes used to laugh at those who believed.",
    "quran.83_30_translation": "And when they passed by them, they would exchange derisive glances.",
    "quran.83_31_translation": "And when they returned to their people, they would return jesting.",
    "quran.83_32_translation": "And when they saw them, they would say, \"Indeed, those are truly lost.\"",
    "quran.83_33_translation": "But they had not been sent as guardians over them.",
    "quran.83_34_translation": "So Today those who believed are laughing at the disbelievers,",
    "quran.83_35_translation": "On adorned couches, observing.",
    "quran.83_36_translation": "Have the disbelievers [not] been rewarded [this Day] for what they used to do?",
    "quran.82_1_translation": "When the sky breaks apart",
    "quran.82_2_translation": "And when the stars fall, scattering,",
    "quran.82_3_translation": "And when the seas are erupted",
    "quran.82_4_translation": "And when the [contents of] graves are scattered,",
    "quran.82_5_translation": "A soul will [then] know what it has put forth and kept back.",
    "quran.82_6_translation": "O mankind, what has deceived you concerning your Lord, the Generous,",
    "quran.82_7_translation": "Who created you, proportioned you, and balanced you?",
    "quran.82_8_translation": "In whatever form He willed has He assembled you.",
    "quran.82_9_translation": "No! But you deny the Recompense.",
    "quran.82_10_translation": "And indeed, [appointed] over you are keepers,",
    "quran.82_11_translation": "Noble and recording;",
    "quran.82_12_translation": "They know whatever you do.",
    "quran.82_13_translation": "Indeed, the righteous will be in pleasure,",
    "quran.82_14_translation": "And indeed, the wicked will be in Hellfire.",
    "quran.82_15_translation": "They will [enter to] burn therein on the Day of Recompense,",
    "quran.82_16_translation": "And never therefrom will they be absent.",
    "quran.82_17_translation": "And what can make you know what is the Day of Recompense?",
    "quran.82_18_translation": "Then, what can make you know what is the Day of Recompense?",
    "quran.82_19_translation": "It is the Day when a soul will not possess for another soul [power to do] a thing; and the command, that Day, is [entirely] with Allah.",
    "quran.81_1_translation": "When the sun is wrapped up [in darkness]",
    "quran.81_2_translation": "And when the stars fall, dispersing,",
    "quran.81_3_translation": "And when the mountains are removed",
    "quran.81_4_translation": "And when full-term she-camels are neglected",
    "quran.81_5_translation": "And when the wild beasts are gathered",
    "quran.81_6_translation": "And when the seas are filled with flame",
    "quran.81_7_translation": "And when the souls are paired",
    "quran.81_8_translation": "And when the girl [who was] buried alive is asked",
    "quran.81_9_translation": "For what sin she was killed",
    "quran.81_10_translation": "And when the pages are made public",
    "quran.81_11_translation": "And when the sky is stripped away",
    "quran.81_12_translation": "And when Hellfire is set ablaze",
    "quran.81_13_translation": "And when Paradise is brought near,",
    "quran.81_14_translation": "A soul will [then] know what it has brought [with it].",
    "quran.81_15_translation": "So I swear by the retreating stars -",
    "quran.81_16_translation": "Those that run [their courses] and disappear -",
    "quran.81_17_translation": "And by the night as it closes in",
    "quran.81_18_translation": "And by the dawn when it breathes",
    "quran.81_19_translation": "[That] indeed, the Qur'an is a word [conveyed by] a noble messenger",
    "quran.81_20_translation": "[Who is] possessed of power and with the Owner of the Throne, secure [in position],",
    "quran.81_21_translation": "Obeyed there [in the heavens] and trustworthy.",
    "quran.81_22_translation": "And your companion is not [at all] mad.",
    "quran.81_23_translation": "And he has already seen Gabriel in the clear horizon.",
    "quran.81_24_translation": "And Muhammad is not a withholder of [knowledge of] the unseen.",
    "quran.81_25_translation": "And the Qur'an is not the word of a devil, expelled [from the heavens].",
    "quran.81_26_translation": "So where are you going?",
    "quran.81_27_translation": "It is not except a reminder to the worlds",
    "quran.81_28_translation": "For whoever wills among you to take a right course.",
    "quran.81_29_translation": "And you do not will except that Allah wills - Lord of the worlds.",
    "quran.79_1_translation": "By those [angels] who extract with violence",
    "quran.79_2_translation": "And [by] those who remove with ease",
    "quran.79_3_translation": "And [by] those who glide [as if] swimming",
    "quran.79_4_translation": "And those who race each other in a race",
    "quran.79_5_translation": "And those who arrange [each] matter,",
    "quran.79_6_translation": "On the Day the blast [of the Horn] will convulse [creation],",
    "quran.79_7_translation": "There will follow it the subsequent [one].",
    "quran.79_8_translation": "Hearts, that Day, will tremble,",
    "quran.79_9_translation": "Their eyes humbled.",
    "quran.79_10_translation": "They are [presently] saying, \"Will we indeed be returned to [our] former state [of life]?",
    "quran.79_11_translation": "Even if we should be decayed bones?",
    "quran.79_12_translation": "They say, \"That, then, would be a losing return.\"",
    "quran.79_13_translation": "Indeed, it will be but one shout,",
    "quran.79_14_translation": "And suddenly they will be [alert] upon the earth's surface.",
    "quran.79_15_translation": "Has there reached you the story of Moses? -",
    "quran.79_16_translation": "When his Lord called to him in the sacred valley of Tuwa,",
    "quran.79_17_translation": "\"Go to Pharaoh. Indeed, he has transgressed.",
    "quran.79_18_translation": "And say to him, 'Would you [be willing to] purify yourself",
    "quran.79_19_translation": "And let me guide you to your Lord so you would fear [Him]?'\"",
    "quran.79_20_translation": "And he showed him the greatest sign,",
    "quran.79_21_translation": "But Pharaoh denied and disobeyed.",
    "quran.79_22_translation": "Then he turned his back, striving.",
    "quran.79_23_translation": "And he gathered [his people] and called out",
    "quran.79_24_translation": "And said, \"I am your most exalted lord.\"",
    "quran.79_25_translation": "So Allah seized him in exemplary punishment for the last and the first [transgression].",
    "quran.79_26_translation": "Indeed in that is a warning for whoever would fear [Allah].",
    "quran.79_27_translation": "Are you a more difficult creation or is the heaven? Allah constructed it.",
    "quran.79_28_translation": "He raised its ceiling and proportioned it.",
    "quran.79_29_translation": "And He darkened its night and extracted its brightness.",
    "quran.79_30_translation": "And after that He spread the earth.",
    "quran.79_31_translation": "He extracted from it its water and its pasture,",
    "quran.79_32_translation": "And the mountains He set firmly",
    "quran.79_33_translation": "As provision for you and your grazing livestock.",
    "quran.79_34_translation": "But when there comes the greatest Overwhelming Calamity -",
    "quran.79_35_translation": "The Day when man will remember that for which he strove,",
    "quran.79_36_translation": "And Hellfire will be exposed for [all] those who see -",
    "quran.79_37_translation": "So as for he who transgressed",
    "quran.79_38_translation": "And preferred the life of the world,",
    "quran.79_39_translation": "Then indeed, Hellfire will be [his] refuge.",
    "quran.79_40_translation": "But as for he who feared the position of his Lord and prevented the soul from [unlawful] inclination,",
    "quran.79_41_translation": "Then indeed, Paradise will be [his] refuge.",
    "quran.79_42_translation": "They ask you, [O Muhammad], about the Hour: when is its arrival?",
    "quran.79_43_translation": "In what [position] are you that you should mention it?",
    "quran.79_44_translation": "To your Lord is its finality.",
    "quran.79_45_translation": "You are only a warner for those who fear it.",
    "quran.79_46_translation": "It will be, on the Day they see it, as though they had not remained [in the world] except for an afternoon or a morning thereof.",
    "quran.78_1_translation": "About what are they asking one another?",
    "quran.78_2_translation": "About the great news -",
    "quran.78_3_translation": "That over which they are in disagreement.",
    "quran.78_4_translation": "No! They are going to know.",
    "quran.78_5_translation": "Then, no! They are going to know.",
    "quran.78_6_translation": "Have We not made the earth a resting place?",
    "quran.78_7_translation": "And the mountains as stakes?",
    "quran.78_8_translation": "And We created you in pairs",
    "quran.78_9_translation": "And made your sleep [a means for] rest",
    "quran.78_10_translation": "And made the night as clothing",
    "quran.78_11_translation": "And made the day for livelihood",
    "quran.78_12_translation": "And constructed above you seven strong [heavens]",
    "quran.78_13_translation": "And made [therein] a burning lamp",
    "quran.78_14_translation": "And sent down, from the rain clouds, pouring water",
    "quran.78_15_translation": "That We may bring forth thereby grain and vegetation",
    "quran.78_16_translation": "And gardens of entwined growth.",
    "quran.78_17_translation": "Indeed, the Day of Judgement is an appointed time -",
    "quran.78_18_translation": "The Day the Horn is blown and you will come forth in multitudes",
    "quran.78_19_translation": "And the heaven is opened and will become gateways",
    "quran.78_20_translation": "And the mountains are removed and will be [but] a mirage.",
    "quran.78_21_translation": "Indeed, Hell has been lying in wait",
    "quran.78_22_translation": "For the transgressors, a place of return,",
    "quran.78_23_translation": "In which they will remain for ages [unending].",
    "quran.78_24_translation": "They will not taste therein [any] coolness or drink",
    "quran.78_25_translation": "Except scalding water and [foul] purulence -",
    "quran.78_26_translation": "An appropriate recompense.",
    "quran.78_27_translation": "Indeed, they were not expecting an account",
    "quran.78_28_translation": "And denied Our verses with [emphatic] denial.",
    "quran.78_29_translation": "But all things We have enumerated in writing.",
    "quran.78_30_translation": "\"So taste [the penalty], and never will We increase you except in torment.\"",
    "quran.78_31_translation": "Indeed, for the righteous is attainment -",
    "quran.78_32_translation": "Gardens and grapevines",
    "quran.78_33_translation": "And full-breasted [companions] of equal age",
    "quran.78_34_translation": "And a full cup.",
    "quran.78_35_translation": "No ill speech will they hear therein or any falsehood -",
    "quran.78_36_translation": "[As] reward from your Lord, [a generous] gift [made due by] account,",
    "quran.78_37_translation": "[From] the Lord of the heavens and the earth and whatever is between them, the Most Merciful. They possess not from Him [authority for] speech.",
    "quran.78_38_translation": "The Day that the Spirit and the angels will stand in rows, they will not speak except for one whom the Most Merciful permits, and he will say what is correct.",
    "quran.78_39_translation": "That is the True Day; so he who wills may take to his Lord a [way of] return.",
    "quran.78_40_translation": "Indeed, We have warned you of a near punishment on the Day when a man will observe what his hands have put forth and the disbeliever will say, \"Oh, I wish that I were dust!\""
  },
  "id": {
    "quran.114_1_translation": "Katakanlah: \"Aku berlindung kepada Tuhan (yang memelihara dan menguasai) manusia.",
    "quran.114_2_translation": "Raja manusia.",
    "quran.114_3_translation": "Sembahan manusia.",
    "quran.114_4_translation": "Dari kejahatan (bisikan) syaitan yang biasa bersembunyi,",
    "quran.114_5_translation": "yang membisikkan (kejahatan) ke dalam dada manusia,",
    "quran.114_6_translation": "dari (golongan) jin dan manusia.",
    "quran.113_1_translation": "Katakanlah: \"Aku berlindung kepada Tuhan Yang Menguasai subuh,",
    "quran.113_2_translation": "dari kejahatan makhluk-Nya,",
    "quran.113_3_translation": "dan dari kejahatan malam apabila telah gelap gulita,",
    "quran.113_4_translation": "dan dari kejahatan wanita-wanita tukang sihir yang menghembus pada buhul-buhul,",
    "quran.113_5_translation": "dan dari kejahatan pendengki bila ia dengki\".",
    "quran.112_1_translation": "Katakanlah: \"Dialah Allah, Yang Maha Esa.",
    "quran.112_2_translation": "Allah adalah Tuhan yang bergantung kepada-Nya segala sesuatu.",
    "quran.112_3_translation": "Dia tiada beranak dan tidak pula diperanakkan,",
    "quran.112_4_translation": "dan tidak ada seorangpun yang setara dengan Dia\".",
    "quran.111_1_translation": "Binasalah kedua tangan Abu Lahab dan sesungguhnya dia akan binasa.",
    "quran.111_2_translation": "Tidaklah berfaedah kepadanya harta bendanya dan apa yang ia usahakan.",
    "quran.111_3_translation": "Kelak dia akan masuk ke dalam api yang bergejolak.",
    "quran.111_4_translation": "Dan (begitu pula) istrinya, pembawa kayu bakar.",
    "quran.111_5_translation": "Yang di lehernya ada tali dari sabut.",
    "quran.110_1_translation": "Apabila telah datang pertolongan Allah dan kemenangan,",
    "quran.110_2_translation": "dan kamu lihat manusia masuk agama Allah dengan berbondong-bondong,",
    "quran.110_3_translation": "maka bertasbihlah dengan memuji Tuhanmu dan mohonlah ampun kepada-Nya. Sesungguhnya Dia adalah Maha Penerima taubat.",
    "quran.109_1_translation": "Katakanlah: \"Hai orang-orang kafir,",
    "quran.109_2_translation": "Aku tidak akan menyembah apa yang kamu sembah.",
    "quran.109_3_translation": "Dan kamu bukan penyembah Tuhan yang aku sembah.",
    "quran.109_4_translation": "Dan aku tidak pernah menjadi penyembah apa yang kamu sembah,",
    "quran.109_5_translation": "dan kamu tidak pernah (pula) menjadi penyembah Tuhan yang aku sembah.",
    "quran.109_6_translation": "Untukmu agamamu, dan untukkulah, agamaku\".",
    "quran.108_1_translation": "Sesungguhnya Kami telah memberikan kepadamu nikmat yang banyak.",
    "quran.108_2_translation": "Maka dirikanlah shalat karena Tuhanmu; dan berkorbanlah.",
    "quran.108_3_translation": "Sesungguhnya orang-orang yang membenci kamu dialah yang terputus.",
    "quran.107_1_translation": "Tahukah kamu (orang) yang mendustakan agama?",
    "quran.107_2_translation": "Itulah orang yang menghardik anak yatim,",
    "quran.107_3_translation": "dan tidak menganjurkan memberi makan orang miskin.",
    "quran.107_4_translation": "Maka kecelakaanlah bagi orang-orang yang shalat,",
    "quran.107_5_translation": "(yaitu) orang-orang yang lalai dari shalatnya,",
    "quran.107_6_translation": "orang-orang yang berbuat riya,",
    "quran.107_7_translation": "dan enggan (menolong dengan) barang berguna.",
    "quran.106_1_translation": "Karena kebiasaan orang-orang Quraisy,",
    "quran.106_2_translation": "(yaitu) kebiasaan mereka bepergian pada musim dingin dan musim panas.",
    "quran.106_3_translation": "Maka hendaklah mereka menyembah Tuhan Pemilik rumah ini (Ka'bah).",
    "quran.106_4_translation": "Yang telah memberi makanan kepada mereka untuk menghilangkan lapar dan mengamankan mereka dari ketakutan.",
    "quran.105_1_translation": "Apakah kamu tidak memperhatikan bagaimana Tuhanmu telah bertindak terhadap tentara bergajah?",
    "quran.105_2_translation": "Bukankah Dia telah menjadikan tipu daya mereka (untuk menghancurkan Ka'bah) itu sia-sia?",
    "quran.105_3_translation": "dan Dia mengirimkan kapada mereka burung yang berbondong-bondong,",
    "quran.105_4_translation": "yang melempari mereka dengan batu (berasal) dari tanah yang terbakar,",
    "quran.105_5_translation": "lalu Dia menjadikan mereka seperti daun-daun yang dimakan (ulat).",
    "quran.104_1_translation": "Kecelakaanlah bagi setiap pengumpat lagi pencela,",
    "quran.104_2_translation": "yang mengumpulkan harta dan menghitung-hitung,",
    "quran.104_3_translation": "dia mengira bahwa hartanya itu dapat mengkekalkannya,",
    "quran.104_4_translation": "sekali-kali tidak! Sesungguhnya dia benar-benar akan dilemparkan ke dalam Huthamah.",
    "quran.104_5_translation": "Dan tahukah kamu apa Huthamah itu?",
    "quran.104_6_translation": "(yaitu) api (yang disediakan) Allah yang dinyalakan,",
    "quran.104_7_translation": "yang (membakar) sampai ke hati.",
    "quran.104_8_translation": "Sesungguhnya api itu ditutup rapat atas mereka,",
    "quran.104_9_translation": "(sedang mereka itu) diikat pada tiang-tiang yang panjang.",
    "quran.103_1_translation": "Demi masa.",
    "quran.103_2_translation": "Sesungguhnya manusia itu benar-benar dalam kerugian,",
    "quran.103_3_translation": "kecuali orang-orang yang beriman dan mengerjakan amal saleh dan nasehat menasehati supaya mentaati kebenaran dan nasehat menasehati supaya menetapi kesabaran.",
    "quran.102_1_translation": "Bermegah-megahan telah melalaikan kamu,",
    "quran.102_2_translation": "sampai kamu masuk ke dalam kubur.",
    "quran.102_3_translation": "Janganlah begitu, kelak kamu akan mengetahui (akibat perbuatanmu itu),",
    "quran.102_4_translation": "dan janganlah begitu, kelak kamu akan mengetahui.",
    "quran.102_5_translation": "Janganlah begitu, jika kamu mengetahui dengan pengetahuan yang yakin,",
    "quran.102_6_translation": "niscaya kamu benar-benar akan melihat neraka Jahiim,",
    "quran.102_7_translation": "dan sesungguhnya kamu benar-benar akan melihatnya dengan 'ainul yaqin.",
    "quran.102_8_translation": "kemudian kamu pasti akan ditanyai pada hari itu tentang kenikmatan (yang kamu megah-megahkan di dunia itu).",
    "quran.101_1_translation": "Hari Kiamat,",
    "quran.101_2_translation": "apakah hari Kiamat itu?",
    "quran.101_3_translation": "Tahukah kamu apakah hari Kiamat itu?",
    "quran.101_4_translation": "Pada hari itu manusia adalah seperti anai-anai yang bertebaran,",
    "quran.101_5_translation": "dan gunung-gunung adalah seperti bulu yang dihambur-hamburkan.",
    "quran.101_6_translation": "Dan adapun orang-orang yang berat timbangan (kebaikan)nya,",
    "quran.101_7_translation": "maka dia berada dalam kehidupan yang memuaskan.",
    "quran.101_8_translation": "Dan adapun orang-orang yang ringan timbangan (kebaikan)nya,",
    "quran.101_9_translation": "maka tempat kembalinya adalah neraka Hawiyah.",
    "quran.101_10_translation": "Tahukah kamu apakah neraka Hawiyah itu?",
    "quran.101_11_translation": "(Yaitu) api yang sangat panas.",
    "quran.100_1_translation": "Demi kuda perang yang berlari kencang dengan terengah-engah,",
    "quran.100_2_translation": "dan kuda yang mencetuskan api dengan pukulan (kuku kakinya),",
    "quran.100_3_translation": "dan kuda yang menyerang dengan tiba-tiba di waktu pagi,",
    "quran.100_4_translation": "maka ia menerbangkan debu,",
    "quran.100_5_translation": "dan menyerbu ke tengah-tengah kumpulan musuh,",
    "quran.100_6_translation": "sesungguhnya manusia itu sangat ingkar, tidak berterima kasih kepada Tuhannya,",
    "quran.100_7_translation": "dan sesungguhnya manusia itu menyaksikan (sendiri) keingkarannya,",
    "quran.100_8_translation": "dan sesungguhnya dia sangat bakhil karena cintanya kepada harta.",
    "quran.100_9_translation": "Maka apakah dia tidak mengetahui apabila dibangkitkan apa yang ada di dalam kubur,",
    "quran.100_10_translation": "dan dilahirkan apa yang ada di dalam dada,",
    "quran.100_11_translation": "sesungguhnya Tuhan mereka pada hari itu Maha Mengetahui keadaan mereka.",
    "quran.99_1_translation": "Apabila bumi digoncangkan dengan goncangan (yang dahsyat),",
    "quran.99_2_translation": "dan bumi telah mengeluarkan beban-beban berat (yang dikandung)nya,",
    "quran.99_3_translation": "dan manusia bertanya: \"Mengapa bumi (menjadi begini)?\",",
    "quran.99_4_translation": "pada hari itu bumi menceritakan beritanya,",
    "quran.99_5_translation": "karena sesungguhnya Tuhanmu telah memerintahkan (yang sedemikian itu) kepadanya.",
    "quran.99_6_translation": "Pada hari itu manusia ke luar dari kuburnya dalam keadaan bermacam-macam, supaya diperlihatkan kepada mereka (balasan) pekerjaan mereka,",
    "quran.99_7_translation": "Barangsiapa yang mengerjakan kebaikan seberat dzarrahpun, niscaya dia akan melihat (balasan)nya.",
    "quran.99_8_translation": "Dan barangsiapa yang mengerjakan kejahatan sebesar dzarrahpun, niscaya dia akan melihat (balasan)nya pula.",
    "quran.98_1_translation": "Orang-orang kafir yakni ahli Kitab dan orang-orang musyrik (mengatakan bahwa mereka) tidak akan meninggalkan (agamanya) sebelum datang kepada mereka bukti yang nyata,",
    "quran.98_2_translation": "(yaitu) seorang Rasul dari Allah (Muhammad) yang membacakan lembaran-lembaran yang disucikan (Al Quran),",
    "quran.98_3_translation": "di dalamnya terdapat (isi) Kitab-kitab yang lurus.",
    "quran.98_4_translation": "Dan tidaklah berpecah belah orang-orang yang didatangkan Al Kitab (kepada mereka) melainkan sesudah datang kepada mereka bukti yang nyata.",
    "quran.98_5_translation": "Padahal mereka tidak disuruh kecuali supaya menyembah Allah dengan memurnikan ketaatan kepada-Nya dalam (menjalankan) agama yang lurus, dan supaya mereka mendirikan shalat dan menunaikan zakat; dan yang demikian itulah agama yang lurus.",
    "quran.98_6_translation": "Sesungguhnya orang-orang yang kafir yakni ahli Kitab dan orang-orang yang musyrik (akan masuk) ke neraka Jahannam; mereka kekal di dalamnya. Mereka itu adalah seburuk-buruk makhluk.",
    "quran.98_7_translation": "Sesungguhnya orang-orang yang beriman dan mengerjakan amal saleh, mereka itu adalah sebaik-baik makhluk.",
    "quran.98_8_translation": "Balasan mereka di sisi Tuhan mereka ialah surga 'Adn yang mengalir di bawahnya sungai-sungai; mereka kekal di dalamnya selama-lamanya. Allah ridha terhadap mereka dan merekapun ridha kepada-Nya. Yang demikian itu adalah (balasan) bagi orang yang takut kepada Tuhannya.",
    "quran.97_1_translation": "Sesungguhnya Kami telah menurunkannya (Al Quran) pada malam kemuliaan.",
    "quran.97_2_translation": "Dan tahukah kamu apakah malam kemuliaan itu?",
    "quran.97_3_translation": "Malam kemuliaan itu lebih baik dari seribu bulan.",
    "quran.97_4_translation": "Pada malam itu turun malaikat-malaikat dan malaikat Jibril dengan izin Tuhannya untuk mengatur segala urusan.",
    "quran.97_5_translation": "Malam itu (penuh) kesejahteraan sampai terbit fajar.",
    "quran.96_1_translation": "Bacalah dengan (menyebut) nama Tuhanmu Yang menciptakan,",
    "quran.96_2_translation": "Dia telah menciptakan manusia dari segumpal darah.",
    "quran.96_3_translation": "Bacalah, dan Tuhanmulah Yang Maha Pemurah,",
    "quran.96_4_translation": "Yang mengajar (manusia) dengan perantaran kalam,",
    "quran.96_5_translation": "Dia mengajar kepada manusia apa yang tidak diketahuinya.",
    "quran.96_6_translation": "Ketahuilah! Sesungguhnya manusia benar-benar melampaui batas,",
    "quran.96_7_translation": "karena dia melihat dirinya serba cukup.",
    "quran.96_8_translation": "Sesungguhnya hanya kepada Tuhanmulah kembali(mu).",
    "quran.96_9_translation": "Bagaimana pendapatmu tentang orang yang melarang,",
    "quran.96_10_translation": "seorang hamba ketika mengerjakan shalat,",
    "quran.96_11_translation": "bagaimana pendapatmu jika orang yang melarang itu berada di atas kebenaran,",
    "quran.96_12_translation": "atau dia menyuruh bertakwa (kepada Allah)?",
    "quran.96_13_translation": "Bagaimana pendapatmu jika orang yang melarang itu mendustakan dan berpaling?",
    "quran.96_14_translation": "Tidaklah dia mengetahui bahwa sesungguhnya Allah melihat segala perbuatannya?",
    "quran.96_15_translation": "Ketahuilah, sungguh jika dia tidak berhenti (berbuat demikian) niscaya Kami tarik ubun-ubunnya,",
    "quran.96_16_translation": "(yaitu) ubun-ubun orang yang mendustakan lagi durhaka.",
    "quran.96_17_translation": "Maka biarlah dia memanggil golongannya (untuk menolongnya),",
    "quran.96_18_translation": "kelak Kami akan memanggil malaikat Zabaniyah,",
    "quran.96_19_translation": "sekali-kali jangan, janganlah kamu patuh kepadanya; dan sujudlah dan dekatkanlah (dirimu kepada Tuhan).",
    "quran.95_1_translation": "Demi (buah) Tin dan (buah) Zaitun,",
    "quran.95_2_translation": "dan demi bukit Sinai,",
    "quran.95_3_translation": "dan demi kota (Mekah) ini yang aman,",
    "quran.95_4_translation": "sesungguhnya Kami telah menciptakan manusia dalam bentuk yang sebaik-baiknya.",
    "quran.95_5_translation": "Kemudian Kami kembalikan dia ke tempat yang serendah-rendahnya (neraka),",
    "quran.95_6_translation": "kecuali orang-orang yang beriman dan mengerjakan amal saleh; maka bagi mereka pahala yang tiada putus-putusnya.",
    "quran.95_7_translation": "Maka apakah yang menyebabkan kamu mendustakan (hari) pembalasan sesudah (adanya keterangan-keterangan) itu?",
    "quran.95_8_translation": "Bukankah Allah Hakim yang seadil-adilnya?",
    "quran.93_1_translation": "Demi waktu matahari sepenggalahan naik,",
    "quran.93_2_translation": "dan demi malam apabila telah sunyi (gelap),",
    "quran.93_3_translation": "Tuhanmu tiada meninggalkan kamu dan tiada (pula) benci kepadamu.",
    "quran.93_4_translation": "Dan sesungguhnya hari kemudian itu lebih baik bagimu daripada yang sekarang (permulaan).",
    "quran.93_5_translation": "Dan kelak Tuhanmu pasti memberikan karunia-Nya kepadamu, lalu (hati) kamu menjadi puas.",
    "quran.93_6_translation": "Bukankah Dia mendapatimu sebagai seorang yatim, lalu Dia melindungimu?",
    "quran.93_7_translation": "Dan Dia mendapatimu sebagai seorang yang bingung, lalu Dia memberikan petunjuk.",
    "quran.93_8_translation": "Dan Dia mendapatimu sebagai seorang yang kekurangan, lalu Dia memberikan kecukupan.",
    "quran.93_9_translation": "Sebab itu, terhadap anak yatim janganlah kamu berlaku sewenang-wenang.",
    "quran.93_10_translation": "Dan terhadap orang yang minta-minta, janganlah kamu menghardiknya.",
    "quran.93_11_translation": "Dan terhadap nikmat Tuhanmu, maka hendaklah kamu siarkan.",
    "quran.92_1_translation": "Demi malam apabila menutupi (cahaya siang),",
    "quran.92_2_translation": "dan siang apabila terang benderang,",
    "quran.92_3_translation": "dan penciptaan laki-laki dan perempuan,",
    "quran.92_4_translation": "sesungguhnya usaha kamu memang berbeda-beda.",
    "quran.92_5_translation": "Adapun orang yang memberikan (hartanya di jalan Allah) dan bertakwa,",
    "quran.92_6_translation": "dan membenarkan adanya pahala yang terbaik (surga),",
    "quran.92_7_translation": "maka Kami kelak akan menyiapkan baginya jalan yang mudah.",
    "quran.92_8_translation": "Dan adapun orang-orang yang bakhil dan merasa dirinya cukup,",
    "quran.92_9_translation": "serta mendustakan pahala terbaik,",
    "quran.92_10_translation": "maka kelak Kami akan menyiapkan baginya (jalan) yang sukar.",
    "quran.92_11_translation": "Dan hartanya tidak bermanfaat baginya apabila ia telah binasa.",
    "quran.92_12_translation": "Sesungguhnya kewajiban Kamilah memberi petunjuk,",
    "quran.92_13_translation": "dan sesungguhnya kepunyaan Kamilah akhirat dan dunia.",
    "quran.92_14_translation": "Maka, kami memperingatkan kamu dengan neraka yang menyala-nyala.",
    "quran.92_15_translation": "Tidak ada yang masuk ke dalamnya kecuali orang yang paling celaka,",
    "quran.92_16_translation": "yang mendustakan (kebenaran) dan berpaling (dari iman).",
    "quran.92_17_translation": "Dan kelak akan dijauhkan orang yang paling takwa dari neraka itu,",
    "quran.92_18_translation": "yang menafkahkan hartanya (di jalan Allah) untuk membersihkannya,",
    "quran.92_19_translation": "padahal tidak ada seseorangpun memberikan suatu nikmat kepadanya yang harus dibalasnya,",
    "quran.92_20_translation": "tetapi (dia memberikan itu semata-mata) karena mencari keridhaan Tuhannya yang Maha Tinggi.",
    "quran.92_21_translation": "Dan kelak dia benar-benar mendapat kepuasan.",
    "quran.91_1_translation": "Demi matahari dan cahayanya di pagi hari,",
    "quran.91_2_translation": "dan bulan apabila mengiringinya,",
    "quran.91_3_translation": "dan siang apabila menampakkannya,",
    "quran.91_4_translation": "dan malam apabila menutupinya,",
    "quran.91_5_translation": "dan langit serta pembinaannya,",
    "quran.91_6_translation": "dan bumi serta penghamparannya,",
    "quran.91_7_translation": "dan jiwa serta penyempurnaannya (ciptaannya),",
    "quran.91_8_translation": "maka Allah mengilhamkan kepada jiwa itu (jalan) kefasikan dan ketakwaannya.",
    "quran.91_9_translation": "sesungguhnya beruntunglah orang yang mensucikan jiwa itu,",
    "quran.91_10_translation": "dan sesungguhnya merugilah orang yang mengotorinya.",
    "quran.91_11_translation": "(Kaum) Tsamud telah mendustakan (rasulnya) karena mereka melampaui batas,",
    "quran.91_12_translation": "ketika bangkit orang yang paling celaka di antara mereka,",
    "quran.91_13_translation": "lalu Rasul Allah (Saleh) berkata kepada mereka: (\"Biarkanlah) unta betina Allah dan minumannya\".",
    "quran.91_14_translation": "Lalu mereka mendustakannya dan menyembelih unta itu, maka Tuhan mereka membinasakan mereka disebabkan dosa mereka, lalu Allah menyama-ratakan mereka (dengan tanah),",
    "quran.91_15_translation": "dan Allah tidak takut terhadap akibat tindakan-Nya itu.",
    "quran.90_1_translation": "Aku benar-benar bersumpah dengan kota ini (Mekah),",
    "quran.90_2_translation": "dan kamu (Muhammad) bertempat di kota Mekah ini,",
    "quran.90_3_translation": "dan demi bapak dan anaknya.",
    "quran.90_4_translation": "Sesungguhnya Kami telah menciptakan manusia berada dalam susah payah.",
    "quran.90_5_translation": "Apakah manusia itu menyangka bahwa sekali-kali tiada seorangpun yang berkuasa atasnya?",
    "quran.90_6_translation": "Dan mengatakan: \"Aku telah menghabiskan harta yang banyak\".",
    "quran.90_7_translation": "Apakah dia menyangka bahwa tiada seorangpun yang melihatnya?",
    "quran.90_8_translation": "Bukankah Kami telah memberikan kepadanya dua buah mata,",
    "quran.90_9_translation": "lidah dan dua buah bibir.",
    "quran.90_10_translation": "Dan Kami telah menunjukkan kepadanya dua jalan,",
    "quran.90_11_translation": "Tetapi dia tiada menempuh jalan yang mendaki lagi sukar.",
    "quran.90_12_translation": "Tahukah kamu apakah jalan yang mendaki lagi sukar itu?",
    "quran.90_13_translation": "(yaitu) melepaskan budak dari perbudakan,",
    "quran.90_14_translation": "atau memberi makan pada hari kelaparan,",
    "quran.90_15_translation": "(kepada) anak yatim yang ada hubungan kerabat,",
    "quran.90_16_translation": "atau kepada orang miskin yang sangat fakir.",
    "quran.90_17_translation": "Dan dia (tidak pula) termasuk orang-orang yang beriman dan saling berpesan untuk bersabar dan saling berpesan untuk berkasih sayang.",
    "quran.90_18_translation": "Mereka (orang-orang yang beriman dan saling berpesan itu) adalah golongan kanan.",
    "quran.90_19_translation": "Dan orang-orang yang kafir kepada ayat-ayat Kami, mereka itu adalah golongan kiri.",
    "quran.90_20_translation": "Mereka berada dalam neraka yang ditutup rapat.",
    "quran.89_1_translation": "Demi fajar,",
    "quran.89_2_translation": "dan malam yang sepuluh,",
    "quran.89_3_translation": "dan yang genap dan yang ganjil,",
    "quran.89_4_translation": "dan malam bila berlalu.",
    "quran.89_5_translation": "Pada yang demikian itu terdapat sumpah (yang dapat diterima) oleh orang-orang yang berakal.",
    "quran.89_6_translation": "Apakah kamu tidak memperhatikan bagaimana Tuhanmu berbuat terhadap kaum 'Aad?",
    "quran.89_7_translation": "(yaitu) penduduk Iram yang mempunyai bangunan-bangunan yang tinggi,",
    "quran.89_8_translation": "yang belum pernah dibangun (suatu kota) seperti itu, di negeri-negeri lain,",
    "quran.89_9_translation": "dan kaum Tsamud yang memotong batu-batu besar di lembah,",
    "quran.89_10_translation": "dan kaum Fir'aun yang mempunyai pasak-pasak (tentara yang banyak),",
    "quran.89_11_translation": "yang berbuat sewenang-wenang dalam negeri,",
    "quran.89_12_translation": "lalu mereka berbuat banyak kerusakan dalam negeri itu,",
    "quran.89_13_translation": "karena itu Tuhanmu menimpakan kepada mereka cemeti azab,",
    "quran.89_14_translation": "sesungguhnya Tuhanmu benar-benar mengawasi.",
    "quran.89_15_translation": "Adapun manusia apabila Tuhannya mengujinya lalu dia dimuliakan-Nya dan diberi-Nya kesenangan, maka dia akan berkata: \"Tuhanku telah memuliakanku\".",
    "quran.89_16_translation": "Adapun bila Tuhannya mengujinya lalu membatasi rezekinya maka dia berkata: \"Tuhanku menghinakanku\".",
    "quran.89_17_translation": "Sekali-kali tidak (demikian), sebenarnya kamu tidak memuliakan anak yatim,",
    "quran.89_18_translation": "dan kamu tidak saling mengajak memberi makan orang miskin,",
    "quran.89_19_translation": "dan kamu memakan harta pusaka dengan cara mencampur baurkan (yang halal dan yang bathil),",
    "quran.89_20_translation": "dan kamu mencintai harta benda dengan kecintaan yang berlebihan.",
    "quran.89_21_translation": "Jangan (berbuat demikian). Apabila bumi digoncangkan berturut-turut,",
    "quran.89_22_translation": "dan datanglah Tuhanmu; sedang malaikat berbaris-baris.",
    "quran.89_23_translation": "Dan pada hari itu diperlihatkan neraka Jahannam; dan pada hari itu ingatlah manusia, akan tetapi tidak berguna lagi mengingat itu baginya.",
    "quran.89_24_translation": "Dia mengatakan: \"Alangkah baiknya kiranya aku dahulu mengerjakan (amal saleh) untuk hidupku ini\".",
    "quran.89_25_translation": "Maka pada hari itu tiada seorangpun yang menyiksa seperti siksa-Nya.",
    "quran.89_26_translation": "dan tiada seorangpun yang mengikat seperti ikatan-Nya.",
    "quran.89_27_translation": "Hai jiwa yang tenang.",
    "quran.89_28_translation": "Kembalilah kepada Tuhanmu dengan hati yang puas lagi diridhai-Nya.",
    "quran.89_29_translation": "Maka masuklah ke dalam jama'ah hamba-hamba-Ku,",
    "quran.89_30_translation": "masuklah ke dalam surga-Ku.",
    "quran.88_1_translation": "Sudah datangkah kepadamu berita (tentang) hari pembalasan?",
    "quran.88_2_translation": "Banyak muka pada hari itu tunduk terhina,",
    "quran.88_3_translation": "bekerja keras lagi kepayahan,",
    "quran.88_4_translation": "memasuki api yang sangat panas (neraka),",
    "quran.88_5_translation": "diberi minum (dengan air) dari sumber yang sangat panas.",
    "quran.88_6_translation": "Mereka tiada memperoleh makanan selain dari pohon yang berduri,",
    "quran.88_7_translation": "yang tidak menggemukkan dan tidak pula menghilangkan lapar.",
    "quran.88_8_translation": "Banyak muka pada hari itu berseri-seri,",
    "quran.88_9_translation": "merasa senang karena usahanya,",
    "quran.88_10_translation": "dalam surga yang tinggi,",
    "quran.88_11_translation": "tidak kamu dengar di dalamnya perkataan yang tidak berguna.",
    "quran.88_12_translation": "Di dalamnya ada mata air yang mengalir.",
    "quran.88_13_translation": "Di dalamnya ada takhta-takhta yang ditinggikan,",
    "quran.88_14_translation": "dan gelas-gelas yang terletak (di dekatnya),",
    "quran.88_15_translation": "dan bantal-bantal sandaran yang tersusun,",
    "quran.88_16_translation": "dan permadani-permadani yang terhampar.",
    "quran.88_17_translation": "Maka apakah mereka tidak memperhatikan unta bagaimana dia diciptakan,",
    "quran.88_18_translation": "Dan langit, bagaimana ia ditinggikan?",
    "quran.88_19_translation": "Dan gunung-gunung bagaimana ia ditegakkan?",
    "quran.88_20_translation": "Dan bumi bagaimana ia dihamparkan?",
    "quran.88_21_translation": "Maka berilah peringatan, karena sesungguhnya kamu hanyalah orang yang memberi peringatan.",
    "quran.88_22_translation": "Kamu bukanlah orang yang berkuasa atas mereka,",
    "quran.88_23_translation": "tetapi orang yang berpaling dan kafir,",
    "quran.88_24_translation": "maka Allah akan mengazabnya dengan azab yang besar.",
    "quran.88_25_translation": "Sesungguhnya kepada Kami-lah kembali mereka,",
    "quran.88_26_translation": "kemudian sesungguhnya kewajiban Kami-lah menghisab mereka.",
    "quran.87_1_translation": "Sucikanlah nama Tuhanmu Yang Maha Tingi,",
    "quran.87_2_translation": "yang menciptakan, dan menyempurnakan (penciptaan-Nya),",
    "quran.87_3_translation": "dan yang menentukan kadar (masing-masing) dan memberi petunjuk,",
    "quran.87_4_translation": "dan yang menumbuhkan rumput-rumputan,",
    "quran.87_5_translation": "lalu dijadikan-Nya rumput-rumput itu kering kehitam-hitaman.",
    "quran.87_6_translation": "Kami akan membacakan (Al Quran) kepadamu (Muhammad) maka kamu tidak akan lupa,",
    "quran.87_7_translation": "kecuali kalau Allah menghendaki. Sesungguhnya Dia mengetahui yang terang dan yang tersembunyi.",
    "quran.87_8_translation": "dan Kami akan memberi kamu taufik ke jalan yang mudah,",
    "quran.87_9_translation": "oleh sebab itu berikanlah peringatan karena peringatan itu bermanfaat,",
    "quran.87_10_translation": "orang yang takut (kepada Allah) akan mendapat pelajaran,",
    "quran.87_11_translation": "dan orang-orang yang celaka (kafir) akan menjauhinya.",
    "quran.87_12_translation": "(Yaitu) orang yang akan memasuki api yang besar (neraka).",
    "quran.87_13_translation": "Kemudian dia tidak akan mati di dalamnya dan tidak (pula) hidup.",
    "quran.87_14_translation": "Sesungguhnya beruntunglah orang yang membersihkan diri (dengan beriman),",
    "quran.87_15_translation": "dan dia ingat nama Tuhannya, lalu dia sembahyang.",
    "quran.87_16_translation": "Tetapi kamu (orang-orang kafir) memilih kehidupan duniawi.",
    "quran.87_17_translation": "Sedang kehidupan akhirat adalah lebih baik dan lebih kekal.",
    "quran.87_18_translation": "Sesungguhnya ini benar-benar terdapat dalam kitab-kitab yang dahulu,",
    "quran.87_19_translation": "(yaitu) Kitab-kitab Ibrahim dan Musa",
    "quran.86_1_translation": "Demi langit dan yang datang pada malam hari,",
    "quran.86_2_translation": "tahukah kamu apakah yang datang pada malam hari itu?",
    "quran.86_3_translation": "(yaitu) bintang yang cahayanya menembus,",
    "quran.86_4_translation": "tidak ada suatu jiwapun (diri) melainkan ada penjaganya.",
    "quran.86_5_translation": "Maka hendaklah manusia memperhatikan dari apakah dia diciptakan?",
    "quran.86_6_translation": "Dia diciptakan dari air yang dipancarkan,",
    "quran.86_7_translation": "yang keluar dari antara tulang sulbi laki-laki dan tulang dada perempuan.",
    "quran.86_8_translation": "Sesungguhnya Allah benar-benar kuasa untuk mengembalikannya (hidup sesudah mati).",
    "quran.86_9_translation": "Pada hari dinampakkan segala rahasia,",
    "quran.86_10_translation": "maka sekali-kali tidak ada bagi manusia itu suatu kekuatanpun dan tidak (pula) seorang penolong.",
    "quran.86_11_translation": "Demi langit yang mengandung hujan",
    "quran.86_12_translation": "dan bumi yang mempunyai tumbuh-tumbuhan,",
    "quran.86_13_translation": "sesungguhnya Al Quran itu benar-benar firman yang memisahkan antara yang hak dan yang bathil.",
    "quran.86_14_translation": "dan sekali-kali bukanlah dia senda gurau.",
    "quran.86_15_translation": "Sesungguhnya orang kafir itu merencanakan tipu daya yang jahat dengan sebenar-benarnya.",
    "quran.86_16_translation": "Dan Akupun membuat rencana (pula) dengan sebenar-benarnya.",
    "quran.86_17_translation": "Karena itu beri tangguhlah orang-orang kafir itu yaitu beri tangguhlah mereka itu barang sebentar.",
    "quran.85_1_translation": "Demi langit yang mempunyai gugusan bintang,",
    "quran.85_2_translation": "dan hari yang dijanjikan,",
    "quran.85_3_translation": "dan yang menyaksikan dan yang disaksikan.",
    "quran.85_4_translation": "Binasa dan terlaknatlah orang-orang yang membuat parit,",
    "quran.85_5_translation": "yang berapi (dinyalakan dengan) kayu bakar,",
    "quran.85_6_translation": "ketika mereka duduk di sekitarnya,",
    "quran.85_7_translation": "sedang mereka menyaksikan apa yang mereka perbuat terhadap orang-orang yang beriman.",
    "quran.85_8_translation": "Dan mereka tidak menyiksa orang-orang mukmin itu melainkan karena orang-orang mukmin itu beriman kepada Allah Yang Maha Perkasa lagi Maha Terpuji,",
    "quran.85_9_translation": "Yang mempunyai kerajaan langit dan bumi; dan Allah Maha Menyaksikan segala sesuatu.",
    "quran.85_10_translation": "Sesungguhnya orang-orang yang mendatangkan cobaan kepada orang-orang yang mukmin laki-laki dan perempuan kemudian mereka tidak bertaubat, maka bagi mereka azab Jahannam dan bagi mereka azab (neraka) yang membakar.",
    "quran.85_11_translation": "Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal yang saleh bagi mereka surga yang mengalir di bawahnya sungai-sungai; itulah keberuntungan yang besar.",
    "quran.85_12_translation": "Sesungguhnya azab Tuhanmu benar-benar keras.",
    "quran.85_13_translation": "Sesungguhnya Dialah Yang menciptakan (makhluk) dari permulaan dan menghidupkannya (kembali).",
    "quran.85_14_translation": "Dialah Yang Maha Pengampun lagi Maha Pengasih,",
    "quran.85_15_translation": "yang mempunyai 'Arsy, lagi Maha Mulia,",
    "quran.85_16_translation": "Maha Kuasa berbuat apa yang dikehendaki-Nya.",
    "quran.85_17_translation": "Sudahkah datang kepadamu berita kaum-kaum penentang,",
    "quran.85_18_translation": "(yaitu kaum) Fir'aun dan (kaum) Tsamud?",
    "quran.85_19_translation": "Sesungguhnya orang-orang kafir selalu mendustakan,",
    "quran.85_20_translation": "padahal Allah mengepung mereka dari belakang mereka.",
    "quran.85_21_translation": "Bahkan yang didustakan mereka itu ialah Al Quran yang mulia,",
    "quran.85_22_translation": "yang (tersimpan) dalam Lauh Mahfuzh.",
    "quran.84_1_translation": "Apabila langit terbelah,",
    "quran.84_2_translation": "dan patuh kepada Tuhannya, dan sudah semestinya langit itu patuh,",
    "quran.84_3_translation": "dan apabila bumi diratakan,",
    "quran.84_4_translation": "dan dilemparkan apa yang ada di dalamnya dan menjadi kosong,",
    "quran.84_5_translation": "dan patuh kepada Tuhannya, dan sudah semestinya bumi itu patuh, (pada waktu itu manusia akan mengetahui akibat perbuatannya).",
    "quran.84_6_translation": "Hai manusia, sesungguhnya kamu telah bekerja dengan sungguh-sungguh menuju Tuhanmu, maka pasti kamu akan menemui-Nya.",
    "quran.84_7_translation": "Adapun orang yang diberikan kitabnya dari sebelah kanannya,",
    "quran.84_8_translation": "maka dia akan diperiksa dengan pemeriksaan yang mudah,",
    "quran.84_9_translation": "dan dia akan kembali kepada kaumnya (yang sama-sama beriman) dengan gembira.",
    "quran.84_10_translation": "Adapun orang-orang yang diberikan kitabnya dari belakang,",
    "quran.84_11_translation": "maka dia akan berteriak: \"Celakalah aku\".",
    "quran.84_12_translation": "Dan dia akan masuk ke dalam api yang menyala-nyala (neraka).",
    "quran.84_13_translation": "Sesungguhnya dia dahulu (di dunia) bergembira di kalangan kaumnya (yang sama-sama kafir).",
    "quran.84_14_translation": "Sesungguhnya dia menyangka bahwa dia sekali-kali tidak akan kembali (kepada Tuhannya).",
    "quran.84_15_translation": "(Bukan demikian), yang benar, sesungguhnya Tuhannya selalu melihatnya.",
    "quran.84_16_translation": "Maka sesungguhnya Aku bersumpah dengan cahaya merah di waktu senja,",
    "quran.84_17_translation": "dan dengan malam dan apa yang diselubunginya,",
    "quran.84_18_translation": "dan dengan bulan apabila jadi purnama,",
    "quran.84_19_translation": "sesungguhnya kamu melalui tingkat demi tingkat (dalam kehidupan),",
    "quran.84_20_translation": "Mengapa mereka tidak mau beriman?",
    "quran.84_21_translation": "dan apabila Al Quran dibacakan kepada mereka, mereka tidak bersujud,",
    "quran.84_22_translation": "bahkan orang-orang kafir itu mendustakan(nya).",
    "quran.84_23_translation": "Padahal Allah mengetahui apa yang mereka sembunyikan (dalam hati mereka).",
    "quran.84_24_translation": "Maka beri kabar gembiralah mereka dengan azab yang pedih,",
    "quran.84_25_translation": "tetapi orang-orang yang beriman dan beramal saleh, bagi mereka pahala yang tidak putus-putusnya.",
    "quran.83_1_translation": "Kecelakaan besarlah bagi orang-orang yang curang",
    "quran.83_2_translation": "(yaitu) orang-orang yang apabila menerima takaran dari orang lain mereka minta dipenuhi,",
    "quran.83_3_translation": "dan apabila mereka menakar atau menimbang untuk orang lain, mereka mengurangi.",
    "quran.83_4_translation": "Tidaklah orang-orang itu menyangka, bahwa sesungguhnya mereka akan dibangkitkan,",
    "quran.83_5_translation": "pada suatu hari yang besar,",
    "quran.83_6_translation": "(yaitu) hari (ketika) manusia berdiri menghadap Tuhan semesta alam?",
    "quran.83_7_translation": "Sekali-kali jangan curang, karena sesungguhnya kitab orang yang durhaka tersimpan dalam sijjin.",
    "quran.83_8_translation": "Tahukah kamu apakah sijjin itu?",
    "quran.83_9_translation": "(Ialah) kitab yang bertulis.",
    "quran.83_10_translation": "Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan,",
    "quran.83_11_translation": "(yaitu) orang-orang yang mendustakan hari pembalasan.",
    "quran.83_12_translation": "Dan tidak ada yang mendustakan hari pembalasan itu melainkan setiap orang yang melampaui batas lagi berdosa,",
    "quran.83_13_translation": "yang apabila dibacakan kepadanya ayat-ayat Kami, ia berkata: \"Itu adalah dongengan orang-orang yang dahulu\"",
    "quran.83_14_translation": "Sekali-kali tidak (demikian), sebenarnya apa yang selalu mereka usahakan itu menutupi hati mereka.",
    "quran.83_15_translation": "Sekali-kali tidak, sesungguhnya mereka pada hari itu benar-benar tertutup dari (rahmat) Tuhan mereka.",
    "quran.83_16_translation": "Kemudian, sesungguhnya mereka benar-benar masuk neraka.",
    "quran.83_17_translation": "Kemudian, dikatakan (kepada mereka): \"Inilah azab yang dahulu selalu kamu dustakan\".",
    "quran.83_18_translation": "Sekali-kali tidak, sesungguhnya kitab orang-orang yang berbakti itu (tersimpan) dalam 'Illiyyin.",
    "quran.83_19_translation": "Tahukah kamu apakah 'Illiyyin itu?",
    "quran.83_20_translation": "(Yaitu) kitab yang bertulis,",
    "quran.83_21_translation": "yang disaksikan oleh malaikat-malaikat yang didekatkan (kepada Allah).",
    "quran.83_22_translation": "Sesungguhnya orang yang berbakti itu benar-benar berada dalam kenikmatan yang besar (surga),",
    "quran.83_23_translation": "mereka (duduk) di atas dipan-dipan sambil memandang.",
    "quran.83_24_translation": "Kamu dapat mengetahui dari wajah mereka kesenangan mereka yang penuh kenikmatan.",
    "quran.83_25_translation": "Mereka diberi minum dari khamar murni yang dilak (tempatnya),",
    "quran.83_26_translation": "laknya adalah kesturi; dan untuk yang demikian itu hendaknya orang berlomba-lomba.",
    "quran.83_27_translation": "Dan campuran khamar murni itu adalah dari tasnim,",
    "quran.83_28_translation": "(yaitu) mata air yang minum daripadanya orang-orang yang didekatkan kepada Allah.",
    "quran.83_29_translation": "Sesungguhnya orang-orang yang berdosa, adalah mereka yang menertawakan orang-orang yang beriman.",
    "quran.83_30_translation": "Dan apabila orang-orang yang beriman lalu di hadapan mereka, mereka saling mengedip-ngedipkan matanya.",
    "quran.83_31_translation": "Dan apabila orang-orang yang berdosa itu kembali kepada kaumnya, mereka kembali dengan gembira.",
    "quran.83_32_translation": "Dan apabila mereka melihat orang-orang mukmin, mereka mengatakan: \"Sesungguhnya mereka itu benar-benar orang-orang yang sesat\",",
    "quran.83_33_translation": "padahal orang-orang yang berdosa itu tidak dikirim untuk penjaga bagi orang-orang mukmin.",
    "quran.83_34_translation": "Maka pada hari ini, orang-orang yang beriman menertawakan orang-orang kafir,",
    "quran.83_35_translation": "mereka (duduk) di atas dipan-dipan sambil memandang.",
    "quran.83_36_translation": "Sesungguhnya orang-orang kafir telah diberi ganjaran terhadap apa yang dahulu mereka kerjakan.",
    "quran.82_1_translation": "Apabila langit terbelah,",
    "quran.82_2_translation": "dan apabila bintang-bintang jatuh berserakan,",
    "quran.82_3_translation": "dan apabila lautan menjadikan meluap,",
    "quran.82_4_translation": "dan apabila kuburan-kuburan dibongkar,",
    "quran.82_5_translation": "maka tiap-tiap jiwa akan mengetahui apa yang telah dikerjakan dan yang dilalaikannya.",
    "quran.82_6_translation": "Hai manusia, apakah yang telah memperdayakan kamu (berbuat durhaka) terhadap Tuhanmu Yang Maha Pemurah.",
    "quran.82_7_translation": "Yang telah menciptakan kamu lalu menyempurnakan kejadianmu dan menjadikan (susunan tubuh)mu seimbang,",
    "quran.82_8_translation": "dalam bentuk apa saja yang Dia kehendaki, Dia menyusun tubuhmu.",
    "quran.82_9_translation": "Bukan hanya durhaka saja, bahkan kamu mendustakan hari pembalasan.",
    "quran.82_10_translation": "Padahal sesungguhnya bagi kamu ada (malaikat-malaikat) yang mengawasi (pekerjaanmu),",
    "quran.82_11_translation": "yang mulia (di sisi Allah) dan mencatat (pekerjaan-pekerjaanmu itu),",
    "quran.82_12_translation": "mereka mengetahui apa yang kamu kerjakan.",
    "quran.82_13_translation": "Sesungguhnya orang-orang yang banyak berbakti benar-benar berada dalam surga yang penuh kenikmatan,",
    "quran.82_14_translation": "dan sesungguhnya orang-orang yang durhaka benar-benar berada dalam neraka.",
    "quran.82_15_translation": "Mereka masuk ke dalamnya pada hari pembalasan.",
    "quran.82_16_translation": "Dan mereka sekali-kali tidak dapat keluar dari neraka itu.",
    "quran.82_17_translation": "Tahukah kamu apakah hari pembalasan itu?",
    "quran.82_18_translation": "Sekali lagi, tahukah kamu apakah hari pembalasan itu?",
    "quran.82_19_translation": "(Yaitu) hari (ketika) seseorang tidak berdaya sedikitpun untuk menolong orang lain. Dan segala urusan pada hari itu dalam kekuasaan Allah.",
    "quran.81_1_translation": "Apabila matahari digulung,",
    "quran.81_2_translation": "dan apabila bintang-bintang berjatuhan,",
    "quran.81_3_translation": "dan apabila gunung-gunung dihancurkan,",
    "quran.81_4_translation": "dan apabila unta-unta yang bunting ditinggalkan (tidak diperdulikan)",
    "quran.81_5_translation": "dan apabila binatang-binatang liar dikumpulkan,",
    "quran.81_6_translation": "dan apabila lautan dijadikan meluap",
    "quran.81_7_translation": "dan apabila ruh-ruh dipertemukan (dengan tubuh)",
    "quran.81_8_translation": "dan apabila bayi-bayi perempuan yang dikubur hidup-hidup ditanya,",
    "quran.81_9_translation": "karena dosa apakah dia dibunuh,",
    "quran.81_10_translation": "dan apabila catatan-catatan (amal perbuatan manusia) dibuka,",
    "quran.81_11_translation": "dan apabila langit dilenyapkan,",
    "quran.81_12_translation": "dan apabila neraka Jahim dinyalakan,",
    "quran.81_13_translation": "dan apabila surga didekatkan,",
    "quran.81_14_translation": "maka tiap-tiap jiwa akan mengetahui apa yang telah dikerjakannya.",
    "quran.81_15_translation": "Sungguh, Aku bersumpah dengan bintang-bintang,",
    "quran.81_16_translation": "yang beredar dan terbenam,",
    "quran.81_17_translation": "demi malam apabila telah hampir meninggalkan gelapnya,",
    "quran.81_18_translation": "dan demi subuh apabila fajarnya mulai menyingsing,",
    "quran.81_19_translation": "sesungguhnya Al Quran itu benar-benar firman (Allah yang dibawa oleh) utusan yang mulia (Jibril),",
    "quran.81_20_translation": "yang mempunyai kekuatan, yang mempunyai kedudukan tinggi di sisi Allah yang mempunyai 'Arsy,",
    "quran.81_21_translation": "yang ditaati di sana (di alam malaikat) lagi dipercaya.",
    "quran.81_22_translation": "Dan temanmu (Muhammad) itu bukanlah sekali-kali orang yang gila.",
    "quran.81_23_translation": "Dan sesungguhnya Muhammad itu melihat Jibril di ufuk yang terang.",
    "quran.81_24_translation": "Dan dia (Muhammad) bukanlah orang yang bakhil untuk menerangkan yang ghaib.",
    "quran.81_25_translation": "Dan Al Quran itu bukanlah perkataan syaitan yang terkutuk,",
    "quran.81_26_translation": "maka ke manakah kamu akan pergi?",
    "quran.81_27_translation": "Al Quran itu tiada lain hanyalah peringatan bagi semesta alam,",
    "quran.81_28_translation": "(yaitu) bagi siapa di antara kamu yang mau menempuh jalan yang lurus.",
    "quran.81_29_translation": "Dan kamu tidak dapat menghendaki (menempuh jalan itu) kecuali apabila dikehendaki Allah, Tuhan semesta alam.",
    "quran.79_1_translation": "Demi (malaikat-malaikat) yang mencabut (nyawa) dengan keras,",
    "quran.79_2_translation": "dan (malaikat-malaikat) yang mencabut (nyawa) dengan lemah-lembut,",
    "quran.79_3_translation": "dan (malaikat-malaikat) yang turun dari langit dengan cepat,",
    "quran.79_4_translation": "dan (malaikat-malaikat) yang mendahului dengan kencang,",
    "quran.79_5_translation": "dan (malaikat-malaikat) yang mengatur urusan (dunia).",
    "quran.79_6_translation": "(Sesungguhnya kamu akan dibangkitkan) pada hari ketika tiupan pertama menggoncang alam,",
    "quran.79_7_translation": "tiupan pertama itu diiringi oleh tiupan kedua.",
    "quran.79_8_translation": "Hati manusia pada waktu itu sangat takut,",
    "quran.79_9_translation": "Pandangannya tunduk.",
    "quran.79_10_translation": "(Orang-orang kafir) berkata: \"Apakah sesungguhnya kami benar-benar dikembalikan kepada kehidupan semula?",
    "quran.79_11_translation": "Apakah (akan dibangkitkan juga) apabila kami telah menjadi tulang belulang yang hancur lumat?\"",
    "quran.79_12_translation": "Mereka berkata: \"Kalau demikian, itu adalah suatu pengembalian yang merugikan\".",
    "quran.79_13_translation": "Sesungguhnya pengembalian itu hanyalah satu kali tiupan saja,",
    "quran.79_14_translation": "maka dengan serta merta mereka hidup kembali di permukaan bumi.",
    "quran.79_15_translation": "Sudah sampaikah kepadamu (ya Muhammad) kisah Musa.",
    "quran.79_16_translation": "Tatkala Tuhannya memanggilnya di lembah suci ialah Lembah Thuwa;",
    "quran.79_17_translation": "\"Pergilah kamu kepada Fir'aun, sesungguhnya dia telah melampaui batas,",
    "quran.79_18_translation": "dan katakanlah (kepada Fir'aun): \"Adakah keinginan bagimu untuk membersihkan diri (dari kesesatan)\".",
    "quran.79_19_translation": "Dan kamu akan kupimpin ke jalan Tuhanmu agar supaya kamu takut kepada-Nya?\"",
    "quran.79_20_translation": "Lalu Musa memperlihatkan kepadanya mukjizat yang besar.",
    "quran.79_21_translation": "Tetapi Fir'aun mendustakan dan mendurhakai.",
    "quran.79_22_translation": "Kemudian dia berpaling seraya berusaha menantang (Musa).",
    "quran.79_23_translation": "Maka dia mengumpulkan (pembesar-pembesarnya) lalu berseru memanggil kaumnya.",
    "quran.79_24_translation": "(Seraya) berkata: \"Akulah tuhanmu yang paling tinggi\".",
    "quran.79_25_translation": "Maka Allah mengazabnya dengan azab di akhirat dan azab di dunia.",
    "quran.79_26_translation": "Sesungguhnya pada yang demikian itu terdapat pelajaran bagi orang yang takut (kepada Tuhannya).",
    "quran.79_27_translation": "Apakah kamu lebih sulit penciptaanya ataukah langit? Allah telah membinanya,",
    "quran.79_28_translation": "Dia meninggikan bangunannya lalu menyempurnakannya,",
    "quran.79_29_translation": "dan Dia menjadikan malamnya gelap gulita, dan menjadikan siangnya terang benderang.",
    "quran.79_30_translation": "Dan bumi sesudah itu dihamparkan-Nya.",
    "quran.79_31_translation": "Ia memancarkan daripadanya mata airnya, dan (menumbuhkan) tumbuh-tumbuhannya.",
    "quran.79_32_translation": "Dan gunung-gunung dipancangkan-Nya dengan teguh,",
    "quran.79_33_translation": "(semua itu) untuk kesenanganmu dan untuk binatang-binatang ternakmu.",
    "quran.79_34_translation": "Maka apabila malapetaka yang sangat besar (hari kiamat) telah datang.",
    "quran.79_35_translation": "Pada hari (ketika) manusia teringat akan apa yang telah dikerjakannya,",
    "quran.79_36_translation": "dan diperlihatkan neraka dengan jelas kepada setiap orang yang melihat.",
    "quran.79_37_translation": "Adapun orang yang melampaui batas,",
    "quran.79_38_translation": "dan lebih mengutamakan kehidupan dunia,",
    "quran.79_39_translation": "maka sesungguhnya nerakalah tempat tinggal(nya).",
    "quran.79_40_translation": "Dan adapun orang-orang yang takut kepada kebesaran Tuhannya dan menahan diri dari keinginan hawa nafsunya,",
    "quran.79_41_translation": "maka sesungguhnya surgalah tempat tinggal(nya).",
    "quran.79_42_translation": "(Orang-orang kafir) bertanya kepadamu (Muhammad) tentang hari kebangkitan, kapankah terjadinya?",
    "quran.79_43_translation": "Siapakah kamu (maka) dapat menyebutkan (waktunya)?",
    "quran.79_44_translation": "Kepada Tuhanmulah dikembalikan kesudahannya (ketentuan waktunya).",
    "quran.79_45_translation": "Kamu hanyalah pemberi peringatan bagi siapa yang takut kepadanya (hari berbangkit)",
    "quran.79_46_translation": "Pada hari mereka melihat hari berbangkit itu, mereka merasa seakan-akan tidak tinggal (di dunia) melainkan (sebentar saja) di waktu sore atau pagi hari.",
    "quran.78_1_translation": "Tentang apakah mereka saling bertanya-tanya?",
    "quran.78_2_translation": "Tentang berita yang besar,",
    "quran.78_3_translation": "yang mereka perselisihkan tentang ini.",
    "quran.78_4_translation": "Sekali-kali tidak; kelak mereka akan mengetahui,",
    "quran.78_5_translation": "kemudian sekali-kali tidak; kelak mereka mengetahui.",
    "quran.78_6_translation": "Bukankah Kami telah menjadikan bumi itu sebagai hamparan?,",
    "quran.78_7_translation": "dan gunung-gunung sebagai pasak?,",
    "quran.78_8_translation": "dan Kami jadikan kamu berpasang-pasangan,",
    "quran.78_9_translation": "dan Kami jadikan tidurmu untuk istirahat,",
    "quran.78_10_translation": "dan Kami jadikan malam sebagai pakaian,",
    "quran.78_11_translation": "dan Kami jadikan siang untuk mencari penghidupan,",
    "quran.78_12_translation": "dan Kami bina di atas kamu tujuh buah (langit) yang kokoh,",
    "quran.78_13_translation": "dan Kami jadikan pelita yang amat terang (matahari),",
    "quran.78_14_translation": "dan Kami turunkan dari awan air yang banyak tercurah,",
    "quran.78_15_translation": "supaya Kami tumbuhkan dengan air itu biji-bijian dan tumbuh-tumbuhan,",
    "quran.78_16_translation": "dan kebun-kebun yang lebat?",
    "quran.78_17_translation": "Sesungguhnya Hari Keputusan adalah suatu waktu yang ditetapkan,",
    "quran.78_18_translation": "yaitu hari (yang pada waktu itu) ditiup sangkakala lalu kamu datang berkelompok-kelompok,",
    "quran.78_19_translation": "dan dibukalah langit, maka terdapatlah beberapa pintu,",
    "quran.78_20_translation": "dan dijalankanlah gunung-gunung maka menjadi fatamorganalah ia.",
    "quran.78_21_translation": "Sesungguhnya neraka Jahannam itu (padanya) ada tempat pengintai,",
    "quran.78_22_translation": "lagi menjadi tempat kembali bagi orang-orang yang melampaui batas,",
    "quran.78_23_translation": "mereka tinggal di dalamnya berabad-abad lamanya,",
    "quran.78_24_translation": "mereka tidak merasakan kesejukan di dalamnya dan tidak (pula mendapat) minuman,",
    "quran.78_25_translation": "selain air yang mendidih dan nanah,",
    "quran.78_26_translation": "sebagai pambalasan yang setimpal.",
    "quran.78_27_translation": "Sesungguhnya mereka tidak berharap (takut) kepada hisab,",
    "quran.78_28_translation": "dan mereka mendustakan ayat-ayat Kami dengan sesungguh-sungguhnya.",
    "quran.78_29_translation": "Dan segala sesuatu telah Kami catat dalam suatu kitab.",
    "quran.78_30_translation": "Karena itu rasakanlah. Dan Kami sekali-kali tidak akan menambah kepada kamu selain daripada azab.",
    "quran.78_31_translation": "Sesungguhnya orang-orang yang bertakwa mendapat kemenangan,",
    "quran.78_32_translation": "(yaitu) kebun-kebun dan buah anggur,",
    "quran.78_33_translation": "dan gadis-gadis remaja yang sebaya,",
    "quran.78_34_translation": "dan gelas-gelas yang penuh (berisi minuman).",
    "quran.78_35_translation": "Di dalamnya mereka tidak mendengar perkataan yang sia-sia dan tidak (pula) perkataan dusta.",
    "quran.78_36_translation": "Sebagai pembalasan dari Tuhanmu dan pemberian yang cukup banyak,",
    "quran.78_37_translation": "Tuhan Yang memelihara langit dan bumi dan apa yang ada di antara keduanya; Yang Maha Pemurah. Mereka tidak dapat berbicara dengan Dia.",
    "quran.78_38_translation": "Pada hari, ketika ruh dan para malaikat berdiri bershaf-shaf, mereka tidak berkata-kata, kecuali siapa yang telah diberi izin kepadanya oleh Tuhan Yang Maha Pemurah; dan ia mengucapkan kata yang benar.",
    "quran.78_39_translation": "Itulah hari yang pasti terjadi. Maka barangsiapa yang menghendaki, niscaya ia menempuh jalan kembali kepada Tuhannya.",
    "quran.78_40_translation": "Sesungguhnya Kami telah memperingatkan kepadamu (hai orang kafir) siksa yang dekat, pada hari manusia melihat apa yang telah diperbuat oleh kedua tangannya; dan orang kafir berkata: \"Alangkah baiknya sekiranya aku dahulu adalah tanah\"."
  },
  "ms": {
    "quran.114_1_translation": "Katakanlah (wahai Muhammad): \"Aku berlindung kepada (Allah) Pemulihara sekalian manusia.",
    "quran.114_2_translation": "\"Yang Menguasai sekalian manusia,",
    "quran.114_3_translation": "\"Tuhan yang berhak disembah oleh sekalian manusia,",
    "quran.114_4_translation": "\"Dari kejahatan pembisik penghasut yang timbul tenggelam, -",
    "quran.114_5_translation": "\"Yang melemparkan bisikan dan hasutannya ke dalam hati manusia, -",
    "quran.114_6_translation": "\"(Iaitu pembisik dan penghasut) dari kalangan jin dan manusia\".",
    "quran.113_1_translation": "Katakanlah (wahai Muhammad); \"Aku berlindung kepada (Allah) Tuhan yang menciptakan sekalian makhluk,",
    "quran.113_2_translation": "\"Dari bencana makhluk-makhluk yang Ia ciptakan;",
    "quran.113_3_translation": "\"Dan dari bahaya gelap apabila ia masuk;",
    "quran.113_4_translation": "\"Dan dari kejahatan makhluk-makhluk yang menghembus-hembus pada simpulan-simpulan (dan ikatan-ikatan);",
    "quran.113_5_translation": "\"Dan dari kejahatan orang yang dengki apabila ia melakukan dengkinya\".",
    "quran.112_1_translation": "Katakanlah (wahai Muhammad): \"(Tuhanku) ialah Allah Yang Maha Esa;",
    "quran.112_2_translation": "\"Allah Yang menjadi tumpuan sekalian makhluk untuk memohon sebarang hajat;",
    "quran.112_3_translation": "\"Ia tiada beranak, dan Ia pula tidak diperanakkan;",
    "quran.112_4_translation": "\"Dan tidak ada sesiapapun yang serupa denganNya\".",
    "quran.111_1_translation": "Binasalah kedua-dua tangan Abu lahab, dan binasalah ia bersama!",
    "quran.111_2_translation": "Hartanya dan segala yang diusahakannya, tidak dapat menolongnya.",
    "quran.111_3_translation": "Ia akan menderita bakaran api neraka yang marak menjulang.",
    "quran.111_4_translation": "Dan juga isterinya, seorang perempuan pemunggah kayu api. -",
    "quran.111_5_translation": "Di lehernya sejenis tali, dari tali-tali yang dipintal.",
    "quran.110_1_translation": "Apabila datang pertolongan Allah dan kemenangan (semasa engkau wahai Muhammad berjaya menguasai negeri Makkah), -",
    "quran.110_2_translation": "Dan engkau melihat manusia masuk dalam ugama Allah beramai-ramai, -",
    "quran.110_3_translation": "Maka ucapkanlah tasbih dengan memuji Tuhanmu dan mintalah ampun kepadaNya, sesungguhnya Dia amat menerima taubat.",
    "quran.109_1_translation": "Katakanlah (wahai Muhammad): \"Hai orang-orang kafir!",
    "quran.109_2_translation": "\"Aku tidak akan menyembah apa yang kamu sembah.",
    "quran.109_3_translation": "\"Dan kamu tidak mahu menyembah (Allah) yang aku sembah.",
    "quran.109_4_translation": "\"Dan aku tidak akan beribadat secara kamu beribadat.",
    "quran.109_5_translation": "\"Dan kamu pula tidak mahu beribadat secara aku beribadat.",
    "quran.109_6_translation": "\"Bagi kamu ugama kamu, dan bagiku ugamaku\".",
    "quran.108_1_translation": "Sesungguhnya Kami telah mengurniakan kepadamu (wahai Muhammad) kebaikan yang banyak (di dunia dan di akhirat).",
    "quran.108_2_translation": "Oleh itu, kerjakanlah sembahyang kerana Tuhanmu semata-mata, dan sembelihlah korban (sebagai bersyukur).",
    "quran.108_3_translation": "Sesungguhnya orang yang bencikan engkau, Dia lah yang terputus (dari mendapat sebarang perkara yang diingininya).",
    "quran.107_1_translation": "Tahukah engkau akan orang yang mendustakan ugama (meliputi hari pembalasan)?",
    "quran.107_2_translation": "Orang itu ialah yang menindas serta berlaku zalim kepada anak yatim,",
    "quran.107_3_translation": "Dan ia tidak menggalakkan untuk memberi makanan yang berhak diterima oleh orang miskin.",
    "quran.107_4_translation": "(Kalau orang yang demikian dikira dari bilangan orang-orang yang mendustakan ugama), maka kecelakaan besar bagi orang-orang Ahli Sembahyang -",
    "quran.107_5_translation": "(laitu) mereka yang berkeadaan lalai daripada menyempurnakan sembahyangnya;",
    "quran.107_6_translation": "(Juga bagi) orang-orang yang berkeadaan riak (bangga diri dalam ibadat dan bawaannya),",
    "quran.107_7_translation": "Dan orang-orang yang tidak memberi sedikit pertolongan (kepada orang yang berhak mendapatnya).",
    "quran.106_1_translation": "Kerana kebiasaan aman tenteram kaum Quraisy (penduduk Makkah)",
    "quran.106_2_translation": "(laitu) kebiasaan aman tenteram perjalanan mereka (menjalankan perniagaan) pada musim sejuk (ke negeri Yaman), dan pada musim panas (ke negeri Syam),",
    "quran.106_3_translation": "Maka hendaklah mereka menyembah Tuhan yang menguasai rumah (Kaabah) ini,",
    "quran.106_4_translation": "Tuhan yang memberi mereka penghidupan: menyelamatkan mereka dari kelaparan, dan mengamankan mereka dari ketakutan.",
    "quran.105_1_translation": "Tidakkah engkau mengetahui bagaimana Tuhanmu telah melakukan kepada angkatan tentera (yang dipimpin oleh pembawa) Gajah, (yang hendak meruntuhkan Kaabah)?",
    "quran.105_2_translation": "Bukankah Tuhanmu telah menjadikan rancangan jahat mereka dalam keadaan yang rugi dan memusnahkan mereka?",
    "quran.105_3_translation": "Dan Ia telah menghantarkan kepada mereka (rombongan) burung berpasuk-pasukan, -",
    "quran.105_4_translation": "Yang melontar mereka dengan batu-batu dari sejenis tanah yang dibakar keras, -",
    "quran.105_5_translation": "Lalu Ia menjadikan mereka hancur berkecai seperti daun-daun kayu yang dimakan ulat.",
    "quran.104_1_translation": "Kecelakaan besar bagi tiap-tiap pencaci, pengeji,",
    "quran.104_2_translation": "Yang mengumpulkan harta dan berulang-ulang menghitung kekayaannya;",
    "quran.104_3_translation": "Ia menyangka bahawa hartanya itu dapat mengekalkannya (dalam dunia ini)!",
    "quran.104_4_translation": "Tidak! Sesungguhnya dia akan dicampakkan ke dalam \"Al-Hutamah\".",
    "quran.104_5_translation": "Dan apa jalannya engkau dapat mengetahui, apa dia \"Al-Hutamah\" itu?",
    "quran.104_6_translation": "(Al-Hutamah) ialah api Allah yang dinyalakan (dengan perintahNya), -",
    "quran.104_7_translation": "Yang naik menjulang ke hati;",
    "quran.104_8_translation": "Sesungguhnnya api neraka itu ditutup rapat atas mereka.",
    "quran.104_9_translation": "(Mereka terikat di situ) pada batang-batang palang yang melintang panjang.",
    "quran.103_1_translation": "Demi Masa!",
    "quran.103_2_translation": "Sesungguhnya manusia itu dalam kerugian -",
    "quran.103_3_translation": "Kecuali orang-orang yang beriman dan beramal soleh, dan mereka pula berpesan-pesan dengan kebenaran serta berpesan-pesan dengan sabar.",
    "quran.102_1_translation": "Kamu telah dilalaikan (daripada mengerjakan amal bakti) oleh perbuatan berlumba-lumba untuk mendapat dengan sebanyak-banyaknya (harta benda, anak-pinak pangkat dan pengaruh), -",
    "quran.102_2_translation": "Sehingga kamu masuk kubur.",
    "quran.102_3_translation": "Jangan sekali-kali (bersikap demikian)! Kamu akan mengetahui kelak (akibatnya yang buruk semasa hendak mati)!",
    "quran.102_4_translation": "Sekali lagi (diingatkan): jangan sekali-kali (kamu bersikap demikian)! Kamu akan mengetahui kelak akibatnya yang buruk pada hari kiamat)!",
    "quran.102_5_translation": "Demi sesungguhnya! Kalaulah kamu mengetahui - (apa yang kamu akan hadapi) - dengan pengetahuan yang yakin, (tentulah kamu akan mengerjakan perkara-perkara yang menjadi bekalan kamu untuk hari akhirat).",
    "quran.102_6_translation": "(Ingatlah) demi sesungguhnya! - Kamu akan melihat neraka yang marak menjulang.",
    "quran.102_7_translation": "Selepas itu - demi sesungguhnya! - kamu (wahai orang-orang yang derhaka) akan melihatnya dengan penglihatan yang yakin (semasa kamu dilemparkan ke dalamnya)!",
    "quran.102_8_translation": "Selain dari itu, sesungguhnya kamu akan ditanya pada hari itu, tentang segala nikmat (yang kamu telah menikmatinya)!",
    "quran.101_1_translation": "Hari yang menggemparkan,",
    "quran.101_2_translation": "Apa dia hari yang menggemparkan itu?",
    "quran.101_3_translation": "Dan apa jalannya engkau dapat mengetahui kedahsyatan hari yang menggemparkan itu? -",
    "quran.101_4_translation": "(Hari itu ialah: hari kiamat), hari manusia menjadi seperti kelkatu yang terbang berkeliaran,",
    "quran.101_5_translation": "Dan gunung-ganang menjadi seperti bulu yang dibusar berterbangan.",
    "quran.101_6_translation": "Setelah berlaku demikian, maka (manusia akan diberikan tempatnya menurut amal masing-masing); adapun orang yang berat timbangan amal baiknya, -",
    "quran.101_7_translation": "Maka ia berada dalam kehidupan yang senang lenang.",
    "quran.101_8_translation": "Sebaliknya orang yang ringan timbangan amal baiknya, -",
    "quran.101_9_translation": "Maka tempat kembalinya ialah \"Haawiyah\"",
    "quran.101_10_translation": "Dan apa jalannya engkau dapat mengetahui, apa dia \"Haawiyah\" itu?",
    "quran.101_11_translation": "(Haawiyah itu ialah): api yang panas membakar.",
    "quran.100_1_translation": "Demi Kuda Perang yang tangkas berlari dengan kedengaran kencang nafasnya,",
    "quran.100_2_translation": "Serta mencetuskan api dari telapak kakinya,",
    "quran.100_3_translation": "Dan meluru menyerbu musuh pada waktu subuh,",
    "quran.100_4_translation": "Sehingga menghamburkan debu pada waktu itu,",
    "quran.100_5_translation": "Lalu menggempur ketika itu di tengah-tengah kumpulan musuh;",
    "quran.100_6_translation": "Sesungguhnya manusia sangat tidak bersyukur akan nikmat Tuhannya.",
    "quran.100_7_translation": "Dan sesungguhnya ia (dengan bawaannya) menerangkan dengan jelas keadaan yang demikian;",
    "quran.100_8_translation": "Dan sesungguhnya ia melampau sangat sayangkan harta (secara tamak haloba).",
    "quran.100_9_translation": "(Patutkah ia bersikap demikian?) Tidakkah ia mengetahui (bagaimana keadaan) ketika dibongkarkan segala yang ada dalam kubur?",
    "quran.100_10_translation": "Dan dikumpul serta didedahkan segala yang terpendam dalam dada?",
    "quran.100_11_translation": "Sesungguhnya Tuhan mereka Maha Mengetahui dengan mendalam tentang (balasan yang diberikanNya kepada) mereka - pada hari itu.",
    "quran.99_1_translation": "Apabila bumi digegarkan dengan gegaran yang sedahsyat-dahsyatnya,",
    "quran.99_2_translation": "Serta bumi itu mengeluarkan segala isinya,",
    "quran.99_3_translation": "Dan berkatalah manusia (dengan perasaan gerun); \"Apa yang sudah terjadi kepada bumi?\"",
    "quran.99_4_translation": "Pada hari itu bumipun menceritakan khabar beritanya:",
    "quran.99_5_translation": "Bahawa Tuhanmu telah memerintahnya (berlaku demikian).",
    "quran.99_6_translation": "Pada hari itu manusia akan keluar berselerak (dari kubur masing-masing) - untuk diperlihatkan kepada mereka (balasan) amal-amal mereka.",
    "quran.99_7_translation": "Maka sesiapa berbuat kebajikan seberat zarah, nescaya akan dilihatnya (dalam surat amalnya)!",
    "quran.99_8_translation": "Dan sesiapa berbuat kejahatan seberat zarah, nescaya akan dilihatnya (dalam surat amalnya)!",
    "quran.98_1_translation": "Orang-orang yang kafir dari Ahli Kitab (Yahudi dan Nasrani) serta orang-orang musyrik, tidak akan terlepas (dari kepercayaan dan amalan masing-masing) sehingga datang kepada mereka bukti yang jelas nyata, -",
    "quran.98_2_translation": "Iaitu seorang Rasul dari Allah yang membacakan (kepada mereka) Lembaran-lembaran Suci,",
    "quran.98_3_translation": "Terkandung di dalamnya pelajaran-pelajaran dan hukum-hukum yang benar.",
    "quran.98_4_translation": "Dan orang-orang (Yahudi dan Nasrani) yang diberi Kitab (Taurat dan Injil) itu, tidak berpecah-belah melainkan setelah datang kepada mereka bukti yang jelas nyata.",
    "quran.98_5_translation": "Pada hal mereka tidak diperintahkan melainkan supaya menyembah Allah dengan mengikhlaskan ibadat kepadaNya, lagi tetap teguh di atas tauhid; dan supaya mereka mendirikan sembahyang serta memberi zakat. Dan yang demikian itulah Ugama yang benar.",
    "quran.98_6_translation": "Sesungguhnya orang-orang yang kafir dari Ahli Kitab dan orang-orang musyrik itu akan ditempatkan di dalam neraka Jahannam, kekalah mereka di dalamnya. Mereka itulah sejahat-jahat makhluk.",
    "quran.98_7_translation": "Seungguhnya orang-orang yang beriman dan beramal soleh, mereka itulah sebaik-baik makhluk.",
    "quran.98_8_translation": "Balasan mereka di sisi Tuhannya ialah syurga Adn (tempat tinggal yang tetap), yang mengalir di bawahnya beberapa sungai; kekalah mereka di dalamnya selama-lamanya; Allah reda akan mereka dan merekapun reda (serta bersyukur) akan nikmat pemberianNya. Balasan yang demikian itu untuk orang-orang yang takut (melanggar perintah) Tuhannya.",
    "quran.97_1_translation": "Sesungguhnya Kami telah menurunkan (Al-Quran) ini pada Malam Lailatul-Qadar,",
    "quran.97_2_translation": "Dan apa jalannya engkau dapat mengetahui apa dia kebesaran Malam Lailatul-Qadar itu?",
    "quran.97_3_translation": "Malam Lailatul-Qadar lebih baik daripada seribu bulan.",
    "quran.97_4_translation": "Pada Malam itu, turun malaikat dan Jibril dengan izin Tuhan mereka, kerana membawa segala perkara (yang ditakdirkan berlakunya pada tahun yang berikut);",
    "quran.97_5_translation": "Sejahteralah Malam (yang berkat) itu hingga terbit fajar!",
    "quran.96_1_translation": "Bacalah (wahai Muhammad) dengan nama Tuhanmu yang menciptakan (sekalian makhluk),",
    "quran.96_2_translation": "Ia menciptakan manusia dari sebuku darah beku;",
    "quran.96_3_translation": "Bacalah, dan Tuhanmu Yang Maha Pemurah, -",
    "quran.96_4_translation": "Yang mengajar manusia melalui pena dan tulisan, -",
    "quran.96_5_translation": "Ia mengajarkan manusia apa yang tidak diketahuinya.",
    "quran.96_6_translation": "Ingatlah! Sesungguhnya jenis manusia tetap melampaui batas (yang sepatutnya atau yang sewajibnya),",
    "quran.96_7_translation": "Dengan sebab ia melihat dirinya sudah cukup apa yang dihajatinya.",
    "quran.96_8_translation": "(Ingatlah) sesungguhnya kepada Tuhanmu lah tempat kembali (untuk menerima balasan).",
    "quran.96_9_translation": "Adakah engkau nampak (baiknya) orang yang melarang (dan menghalang) -",
    "quran.96_10_translation": "Seorang hamba Allah apabila ia mengerjakan sembahyang?",
    "quran.96_11_translation": "Adakah engkau nampak (buruknya) jika ia berada di atas jalan yang betul? -",
    "quran.96_12_translation": "Atau ia menyuruh orang bertaqwa (jangan melakukan syirik)?",
    "quran.96_13_translation": "Adakah engkau nampak (terlepasnya dari azab) jika ia mendustakan (apa yang disampaikan oleh Nabi Muhammad kepadanya) serta ia berpaling ingkar?",
    "quran.96_14_translation": "Tidakkah ia mengetahui bahawa sesungguhnya Allah melihat (segala amal perbuatannya dan membalasnya)?",
    "quran.96_15_translation": "Jangan sekali-kali berlaku derhaka! Demi sesungguhnya jika ia tidak berhenti (dari perbuatannya yang buruk itu), nescaya Kami akan menyentap ubun-ubunnya (dan menyeretnya ke dalam neraka), -",
    "quran.96_16_translation": "Ubun-ubun (orang) yang berdusta, yang bersalah.",
    "quran.96_17_translation": "Kemudian biarlah ia memanggil kumpulannya (untuk menyelamatkannya),",
    "quran.96_18_translation": "Kami pula akan memanggil malaikat Zabaniyah (untuk menyeksanya)!",
    "quran.96_19_translation": "Ingatlah! Janganlah engkau (wahai Muhammad) menurut kehendaknya, dan (sebaliknya) sujudlah dan dampingkanlah dirimu kepada Allah (dengan taat dan beramal soleh)!",
    "quran.95_1_translation": "Demi buah Tiin dan Zaitun,",
    "quran.95_2_translation": "Dan Gunung Tursina,",
    "quran.95_3_translation": "Serta negeri (Makkah) yang aman ini, -",
    "quran.95_4_translation": "Sesungguhnya Kami telah menciptakan manusia dalam bentuk yang sebaik-baiknya (dan berkelengkapan sesuai dengan keadaannya).",
    "quran.95_5_translation": "Kemudian (jika ia panjang umur sehingga tua atau menyalahgunakan kelengkapan itu), Kami kembalikan dia ke serendah-rendah peringkat orang-orang yang rendah,",
    "quran.95_6_translation": "Kecuali orang-orang yang beriman dan beramal soleh, maka mereka beroleh pahala yang tidak putus-putus.",
    "quran.95_7_translation": "(Jika demikian kekuasaanKu), maka apa pula yang menjadikan engkau seorang pendusta, (berkata tidak benar) mengenai hari pembalasan, sesudah (ternyata dalil-dalil yang membuktikan kekuasaanKu mengadakan hari pembalasan) itu?",
    "quran.95_8_translation": "Bukankah Allah (yang demikian kekuasaanNya) seadil-adil Hakim?",
    "quran.93_1_translation": "Demi waktu dhuha,",
    "quran.93_2_translation": "Dan malam apabila ia sunyi-sepi -",
    "quran.93_3_translation": "(Bahawa) Tuhanmu (wahai Muhammad) tidak meninggalkanmu, dan Ia tidak benci (kepadamu, sebagaimana yang dituduh oleh kaum musyrik).",
    "quran.93_4_translation": "Dan sesungguhnya kesudahan keaadaanmu adalah lebih baik bagimu daripada permulaannya.",
    "quran.93_5_translation": "Dan sesungguhnya Tuhanmu akan memberikanmu (kejayaan dan kebahagiaan di dunia dan di akhirat) sehingga engkau reda - berpuas hati.",
    "quran.93_6_translation": "Bukankah dia mendapati engkau yatim piatu, lalu la memberikan perlindungan?",
    "quran.93_7_translation": "Dan didapatiNya engkau mencari-cari (jalan yang benar), lalu Ia memberikan hidayah petunjuk (dengan wahyu - Al-Quran)?",
    "quran.93_8_translation": "Dan didapatiNya engkau miskin, lalu Ia memberikan kekayaan?",
    "quran.93_9_translation": "Oleh itu, adapun anak yatim maka janganlah engkau berlaku kasar terhadapnya,",
    "quran.93_10_translation": "Adapun orang yang meminta (bantuan pimpinan) maka janganlah engkau tengking herdik;",
    "quran.93_11_translation": "Adapun nikmat Tuhanmu, maka hendaklah engkau sebut-sebutkan (dan zahirkan) sebagai bersyukur kepadaNya.",
    "quran.92_1_translation": "Demi malam apabila ia menyelubungi segala-galanya (dengan gelap-gelitanya),",
    "quran.92_2_translation": "Dan siang apabila ia lahir terang-benderang;",
    "quran.92_3_translation": "Demi Yang menciptakan (makhluk-makhlukNya) lelaki dan perempuan, (jantan dan betina); -",
    "quran.92_4_translation": "Sesungguhnya amal usaha kamu adalah berbagai-bagai keadaannya.",
    "quran.92_5_translation": "Jelasnya: adapun orang yang memberikan apa yang ada padanya ke jalan kebaikan dan bertaqwa (mengerjakan suruhan Allah dan meninggalkan segala laranganNya), -",
    "quran.92_6_translation": "Serta ia mengakui dengan yakin akan perkara yang baik,",
    "quran.92_7_translation": "Maka sesungguhnya Kami akan memberikannya kemudahan untuk mendapat kesenangan (Syurga).",
    "quran.92_8_translation": "Sebaliknya: orang yang bakhil (daripada berbuat kebajikan) dan merasa cukup dengan kekayaan dan kemewahannya, -",
    "quran.92_9_translation": "Serta ia mendustakan perkara yang baik,",
    "quran.92_10_translation": "Maka sesungguhnya Kami akan memberikannya kemudahan untuk mendapat kesusahan dan kesengsaraan;",
    "quran.92_11_translation": "Dan apakah pertolongan yang dapat diberi kepadanya oleh hartanya apabiha ia telah terjerumus (ke dalam azab seksa hari akhirat)?",
    "quran.92_12_translation": "Sesungguhnya tanggungan Kamilah memberi hidayah petunjuk (tentang yang benar dan yang salah).",
    "quran.92_13_translation": "Dan sesungguhnya Kamilah yang menguasai hari akhirat dan alam dunia.",
    "quran.92_14_translation": "Maka (serentak dengan memberi hidayah petunjuk) Aku juga telah memberi amaran mengingatkan kamu akan api neraka yang marak menjulang,",
    "quran.92_15_translation": "Yang tidak akan menderita bakarannya melainkan orang yang sungguh celaka, -",
    "quran.92_16_translation": "Yang telah mendustakan (kebenaran) dan berpaling ingkar.",
    "quran.92_17_translation": "Dan (sebaliknya) akan dijauhkan (azab neraka) itu daripada orang yang sungguh bertaqwa, -",
    "quran.92_18_translation": "Yang mendermakan hartanya dengan tujuan membersihkan dirinya dan hartabendanya,",
    "quran.92_19_translation": "Sedang ia tidak menanggung budi sesiapapun, yang patut di balas,",
    "quran.92_20_translation": "Hanyalah mengharapkan keredaan Tuhannya Yang Maha Tinggi;",
    "quran.92_21_translation": "Dan demi sesungguhnya, ia tetap akan berpuas hati (pada hari akhirat, dengan mendapat segala yang diharapkannya).",
    "quran.91_1_translation": "Demi matahari dan cahayanya yang terang-benderang;",
    "quran.91_2_translation": "Dan bulan apabila ia mengiringinya;",
    "quran.91_3_translation": "Dan siang apabila ia memperlihatkannya dengan jelas nyata;",
    "quran.91_4_translation": "Dan malam apabila ia menyelubunginya (dengan gelap- gelita),",
    "quran.91_5_translation": "Demi langit dan Yang membinanya (dalam bentuk yang kuat kukuh - yang melambangkan kekuasaanNya);",
    "quran.91_6_translation": "Serta bumi dan Yang menghamparkannya (untuk kemudahan makhluk-makhlukNya);",
    "quran.91_7_translation": "Demi diri manusia dan Yang menyempurnakan kejadiannya (dengan kelengkapan yang sesuai dengan keadaannya);",
    "quran.91_8_translation": "Serta mengilhamkannya (untuk mengenal) jalan yang membawanya kepada kejahatan, dan yang membawanya kepada bertaqwa; -",
    "quran.91_9_translation": "Sesungguhnya berjayalah orang yang menjadikan dirinya - yang sedia bersih - bertambah-tambah bersih (dengan iman dan amal kebajikan),",
    "quran.91_10_translation": "Dan sesungguhnya hampalah orang yang menjadikan dirinya - yang sedia bersih - itu susut dan terbenam kebersihannya (dengan sebab kekotoran maksiat).",
    "quran.91_11_translation": "(Ingatlah), kaum Thamud telah mendustakan (Rasulnya) dengan sebab perbuatan derhaka mereka yang melampaui batas;",
    "quran.91_12_translation": "Ketika orang yang paling jahat di antara mereka menerima perintah dari mereka (supaya membunuh unta yang menjadi mukjizat),",
    "quran.91_13_translation": "Maka berkatalah Rasul Allah (Nabi Soleh) kepada mereka: \" (Janganlah kamu ganggu) unta betina dari Allah itu, dan (janganlah kamu menyekatnya daripada mendapat) air minumnya (supaya kamu tidak ditimpa azab)!\"",
    "quran.91_14_translation": "(Setelah Nabi Soleh memberi amaran) lalu mereka mendustakannya serta menyembelih unta itu. Dengan sebab dosa mereka, maka Tuhan menimpakan mereka dengan azab yang membinasakan serta Ia meratakan azab itu meliputi mereka (sehingga punah-ranah semuanya).",
    "quran.91_15_translation": "Dan Allah tidak hiraukan kesudahan (mereka) yang demikian, (kerana itu adalah balasan yang adil).",
    "quran.90_1_translation": "Aku bersumpah dengan negeri (Makkah) ini;",
    "quran.90_2_translation": "Sedang engkau (wahai Muhammad) tinggal di negeri ini (sentiasa ditindas),",
    "quran.90_3_translation": "Demi manusia yang melahirkan zuriat, dan zuriat yang dilahirkannya;",
    "quran.90_4_translation": "Sesungguhnya Kami telah jadikan manusia sentiasa dalam keadaan menghadapi kesulitan dan kesukaran (jasmani dan rohaninya);",
    "quran.90_5_translation": "Patutkah manusia yang demikian keadaannya (terpedaya dengan kekuasaan yang ada padanya dan) menyangka bahawa tidak ada sesiapapun yang dapat mengatasi kekuasaannya (dan menyeksakannya)?",
    "quran.90_6_translation": "Manusia yang demikian keadaannya (tidaklah patut ia bermegah-megah dengan kekayaannya dan) berkata: \"Aku telah habiskan harta benda yang banyak (dalam usaha menegakkan nama dan bangsa).",
    "quran.90_7_translation": "Adakah ia menyangka bahawa tidak ada sesiapapun yang melihatnya (dan mengetahui tujuannya menghabiskan harta bendanya itu?",
    "quran.90_8_translation": "(Mengapa manusia terpedaya dan bermegah-megah?) Tidakkah Kami telah menjadikan baginya: dua mata (untuk ia memerhatikan kekuasaan dan kekayaan Kami?) -",
    "quran.90_9_translation": "Dan lidah serta dua bibir (untuk ia menyempurnakan sebahagian besar dari hajat-hajatnya)?",
    "quran.90_10_translation": "Dan Kami telah menunjukkan kepadanya dua jalan, (jalan kebaikan untuk dijalaninya, dan jalan kejahatan untuk dijauhi)?",
    "quran.90_11_translation": "Dalam pada itu manusia tidak (memilih jalan kebaikan) merempuh masuk mengerjakan amal-amal yang tinggi darjatnya di sisi Tuhan;",
    "quran.90_12_translation": "Dan apa jalannya engkau dapat mengetahui: apa dia amal-amal yang tinggi darjatnya di sisi Tuhan itu?",
    "quran.90_13_translation": "(Di antara amal-amal itu - bagi orang yang mampu) ialah: memerdekakan hamba abdi;",
    "quran.90_14_translation": "Atau memberi makan pada hari kelaparan -",
    "quran.90_15_translation": "Kepada anak yatim dari kaum kerabat,",
    "quran.90_16_translation": "Atau kepada orang miskin yang terlantar di atas tanah.",
    "quran.90_17_translation": "Selain dari (tidak mengerjakan amal-amal) itu, ia (tidak pula) menjadi dari orang-orang yang beriman dan berpesan-pesan dengan sabar serta berpesan-pesan dengan kasih sayang.",
    "quran.90_18_translation": "(Ketahuilah! Bahawa orang-orang yang beriman serta berusaha mengerjakan amal-amal yang tinggi darjatnya di sisi Tuhan), merekalah golongan pihak kanan (yang akan beroleh Syurga).",
    "quran.90_19_translation": "Dan (sebaliknya) orang-orang yang kufur ingkar akan ayat-ayat keterangan Kami, merekalah golongan pihak kiri. -",
    "quran.90_20_translation": "Mereka ditimpakan (azab seksa) neraka yang ditutup rapat (supaya kuat bakarannya).",
    "quran.89_1_translation": "Demi waktu fajar;",
    "quran.89_2_translation": "Dan malam yang sepuluh (yang mempunyai kelebihan di sisi Allah);",
    "quran.89_3_translation": "Dan bilangan yang genap serta yang ganjil;",
    "quran.89_4_translation": "Dan malam, apabila ia berlalu; -",
    "quran.89_5_translation": "Bukankah yang demikian itu mengandungi sumpah (yang diakui kebenarannya) oleh orang yang berakal sempurna?",
    "quran.89_6_translation": "(Kami tetap akan membinasakan orang-orang yang menentangmu wahai Muhammad), tidakkah engkau perhatikan, bagaimana Tuhanmu telah melakukan terhadap kaum Aad (yang kufur derhaka)",
    "quran.89_7_translation": "Iaitu penduduk \"Iram\" yang mempunyai bangunan-bangunan yang tinggi tiangnya, (sesuai dengan penduduknya)",
    "quran.89_8_translation": "Yang belum pernah diciptakan sepertinya (tentang besar dan kukuhnya) di segala negeri (pada zamannya)?",
    "quran.89_9_translation": "Dan (terhadap) kaum Thamud yang memahat batu-batu besar di lembah (Wadil-Qura iaitu tempat tinggalnya)?",
    "quran.89_10_translation": "Dan (terhadap) Firaun yang menguasai bangunan-bangunan yang handal kukuh?",
    "quran.89_11_translation": "(Semuanya itu ialah) orang-orang yang telah bermaharajalela di negeri (masing-masing).",
    "quran.89_12_translation": "Lalu mereka melakukan dengan banyaknya kerosakan dan bencana di negeri-negeri itu.",
    "quran.89_13_translation": "Dengan yang demikian, Tuhanmu mencurahkan ke atas mereka berbagai paluan azab;",
    "quran.89_14_translation": "Sesungguhnya Tuhanmu tetap mengawas dan membalas, (terutama balasan akhirat)",
    "quran.89_15_translation": "(Dalam pada itu manusia tidak menghiraukan balasan akhirat), oleh yang demikian, maka kebanyakan manusia apabila diuji oleh Tuhannya dengan dimuliakan dan dimewahkan hidupnya, (ia tidak mahu bersyukur tetapi terus bersikap takbur) serta berkata dengan sombongnya: \"Tuhanku telah memuliakan daku!\"",
    "quran.89_16_translation": "Dan sebaliknya apabila ia diuji oleh Tuhannya, dengan disempitkan rezekinya, (ia tidak bersabar bahkan ia resah gelisah) serta merepek dengan katanya: \"Tuhanku telah menghinakan daku!\"",
    "quran.89_17_translation": "Jangan demikian, (sebenarnya kata-kata kamu itu salah). Bahkan (perbuatan kamu wahai orang-orang yang hidup mewah, lebih salah lagi kerana) kamu tidak memuliakan anak yatim, (malah kamu menahan apa yang Ia berhak menerimanya);",
    "quran.89_18_translation": "Dan kamu tidak menggalakkan untuk memberi makanan (yang berhak diterima oleh) orang miskin;",
    "quran.89_19_translation": "Dan kamu sentiasa makan harta pusaka secara rakus (dengan tidak membezakan halal haramnya),",
    "quran.89_20_translation": "Serta kamu pula sayangkan harta secara tamak haloba!",
    "quran.89_21_translation": "Jangan sekali-kali bersikap demikian! (Sebenarnya) apabila bumi (dihancurkan segala yang ada di atasnya dan) diratakan serata-ratanya,",
    "quran.89_22_translation": "Dan (perintah) Tuhanmu pun datang, sedang malaikat berbaris-baris (siap sedia menjalankan perintah),",
    "quran.89_23_translation": "Serta diperlihatkan neraka Jahannam pada hari itu, (maka) pada saat itu manusia akan ingat (hendak berlaku baik), dan bagaimana ingatan itu akan berguna lagi kepadanya?",
    "quran.89_24_translation": "Ia akan berkata: \"Alangkah baiknya kalau aku dahulu sediakan amal-amal baik untuk hidupku (di sini)!\"",
    "quran.89_25_translation": "Maka pada hari itu tiada sesiapapun yang dapat menyeksa seperti azab (yang ditimpakan oleh) Allah.",
    "quran.89_26_translation": "Dan tiada sesiapapun yang dapat mengikat serta membelenggu seperti ikatan dan belengguNya.",
    "quran.89_27_translation": "(Setelah menerangkan akibat orang-orang yang tidak menghiraukan akhirat, Tuhan menyatakan bahawa orang-orang yang beriman dan beramal soleh akan disambut dengan kata-kata): \"Wahai orang yang mempunyai jiwa yang sentiasa tenang tetap dengan kepercayaan dan bawaan baiknya! -",
    "quran.89_28_translation": "\"Kembalilah kepada Tuhanmu dengan keadaan engkau berpuas hati (dengan segala nikmat yang diberikan) lagi diredhai (di sisi Tuhanmu) ! -",
    "quran.89_29_translation": "\"Serta masuklah engkau dalam kumpulan hamba-hambaku yang berbahagia -",
    "quran.89_30_translation": "\"Dan masuklah ke dalam SyurgaKu! \"",
    "quran.88_1_translation": "Sudahkah sampai kepadamu (wahai Muhammad) perihal hari kiamat yang huru-haranya meliputi?",
    "quran.88_2_translation": "Muka (orang-orang yang kafir) pada hari itu tunduk kerana merasa hina,",
    "quran.88_3_translation": "Mereka menjalankan kerja yang berat lagi berpenat lelah,",
    "quran.88_4_translation": "Mereka tetap menderita bakaran neraka yang amat panas (membakar), -",
    "quran.88_5_translation": "Mereka diberi minum dari matair yang menggelegak panasnya.",
    "quran.88_6_translation": "Tiada makanan bagi mereka (di situ) selain dari pokok-pokok yang berduri,",
    "quran.88_7_translation": "Yang tidak menggemokkan, dan tidak pula dapat menghilangkan sedikit kelaparan pun.",
    "quran.88_8_translation": "(Sebaliknya) muka (orang-orang yang beriman) pada hari itu berseri-seri,",
    "quran.88_9_translation": "Berpuas hati dengan balasan amal usahanya (yang baik yang telah dikerjakannya di dunia), -",
    "quran.88_10_translation": "(Mereka tinggal menetap) di dalam Syurga tinggi (tempat kedudukannya darjatnya),",
    "quran.88_11_translation": "Mereka tidak mendengar di situ sebarang perkataan yang sia-sia,",
    "quran.88_12_translation": "Di dalam Syurga itu ada matair yang mengalir,",
    "quran.88_13_translation": "Di situ juga ada pelamin-pelamin (berhias) yang tinggi (tempatnya),",
    "quran.88_14_translation": "Dan piala-piala minuman yang disediakan (untuk mereka),",
    "quran.88_15_translation": "Dan bantal-bantal yang teratur (untuk mereka berbaring atau bersandar),",
    "quran.88_16_translation": "Serta hamparan-hamparan yang terbentang.",
    "quran.88_17_translation": "(Mengapa mereka yang kafir masih mengingkari akhirat) tidakkah mereka memperhatikan keadaan unta bagaimana ia diciptakan?",
    "quran.88_18_translation": "Dan keadaan langit bagaimana ia ditinggikan binaannya.?",
    "quran.88_19_translation": "Dan keadaan gunung-ganang bagaimana ia ditegakkan?",
    "quran.88_20_translation": "Dan keadaan bumi bagaimana ia dihamparkan?",
    "quran.88_21_translation": "Oleh itu berikanlah sahaja peringatan (wahai Muhammad, kepada manusia, dan janganlah berdukacita kiranya ada yang menolaknya), kerana sesungguhnya engkau hanyalah seorang Rasul pemberi ingatan;",
    "quran.88_22_translation": "Bukanlah engkau seorang yang berkuasa memaksa mereka (menerima ajaran Islam yang engkau sampaikan itu).",
    "quran.88_23_translation": "Akan tetapi sesiapa yang berpaling (dari kebenaran) serta ia kufur ingkar, -",
    "quran.88_24_translation": "Maka Allah akan menyeksanya dengan azab seksa yang sebesar-besarnya.",
    "quran.88_25_translation": "Sesungguhnya kepada Kamilah kembalinya mereka,",
    "quran.88_26_translation": "Selain dari itu, sesungguhnya tanggungan Kamilah soal menghitung amal mereka.",
    "quran.87_1_translation": "Bertasbihlah mensucikan nama Tuhanmu Yang Maha Tinggi (dari segala sifat-sifat kekurangan), -",
    "quran.87_2_translation": "Yang telah menciptakan (sekalian makhlukNya) serta menyempurnakan kejadiannya dengan kelengkapan yang sesuai dengan keadaannya;",
    "quran.87_3_translation": "Dan Yang telah mengatur (keadaan makhluk-makhlukNya) serta memberikan hidayah petunjuk (ke jalan keselamatannya dan kesempurnaannya);",
    "quran.87_4_translation": "Dan Yang telah mengeluarkan tumbuh-tumbuhan untuk binatang-binatang ternak,",
    "quran.87_5_translation": "Kemudian Ia menjadikan (tumbuh-tumbuhan yang menghijau) itu kering - (berubah warnanya) kehitam-hitaman.",
    "quran.87_6_translation": "Kami sentiasa menjadikan engkau (wahai Muhammad) dapat membaca (Al-Quran yang diturunkan kepadamu - dengan perantaraan jibril), sehingga engkau (menghafaznya dan) tidak lupa,",
    "quran.87_7_translation": "Kecuali apa yang dikehendaki Allah engkau lupakan; sesungguhnya Ia mengetahui (segala keadaan yang patut berlaku), dan yang tersembunyi.",
    "quran.87_8_translation": "Dan Kami tetap memberi kemudahan kepadamu untuk (melaksanakan segala perkara) Ugama yang mudah diterima oleh akal yang sihat.",
    "quran.87_9_translation": "Oleh itu berilah peringatan (kepada umat manusia dengan ajaran Al-Quran), kalau-kalau peringatan itu berguna (dan sudah tentu berguna);",
    "quran.87_10_translation": "Kerana orang yang takut (melanggar perintah Allah) akan menerima peringatan itu;",
    "quran.87_11_translation": "Dan (sebaliknya) orang yang sangat celaka akan menjauhinya,",
    "quran.87_12_translation": "Dia lah orang yang akan menderita bakaran neraka yang amat besar (azab seksanya),",
    "quran.87_13_translation": "Selain dari itu, ia tidak mati di dalamnya dan tidak pula hidup senang.",
    "quran.87_14_translation": "Sesungguhnya berjayalah orang yang - setelah menerima peringatan itu - berusaha membersihkan dirinya (dengan taat dan amal yang soleh),",
    "quran.87_15_translation": "Dan menyebut-nyebut dengan lidah dan hatinya akan nama Tuhannya serta mangerjakan sembahyang (dengan khusyuk).",
    "quran.87_16_translation": "(Tetapi kebanyakkan kamu tidak melakukan yang demikian), bahkan kamu utamakan kehidupan dunia;",
    "quran.87_17_translation": "Padahal kehidupan akhirat lebih baik dan lebih kekal.",
    "quran.87_18_translation": "Sesungguhnya (keterangan-keterangan yang dinyatakan) ini ada (disebutkan) di dalam Kitab-kitab yang terdahulu, -",
    "quran.87_19_translation": "Iaitu Kitab-kitab Nabi Ibrahim dan Nabi Musa.",
    "quran.86_1_translation": "Demi langit dan \"At-Taariq\"; -",
    "quran.86_2_translation": "Dan apa jalannya engkau dapat mengetahui apa dia \"At-Taariq\" itu? -",
    "quran.86_3_translation": "(At-Taariq) ialah bintang yang menembusi (sinaran cahayanya);",
    "quran.86_4_translation": "Tiada sesuatu diri juapun melainkan ada malaikat yang menjaga (keadaannya serta menyimpan catitan mengenai segala bawaannya).",
    "quran.86_5_translation": "(Setelah mengetahui yang demikian), maka hendaklah manusia memikirkan: dari apa ia diciptakan.",
    "quran.86_6_translation": "Ia diciptakan dari air (mani) yang memancut (ke dalam rahim) -",
    "quran.86_7_translation": "Yang keluar dari \"tulang sulbi\" lelaki dan \"tulang dada\" perempuan.",
    "quran.86_8_translation": "Sesungguhnya Allah Maha Kuasa untuk mengembalikannya (hidup semula sesudah mati),",
    "quran.86_9_translation": "Pada hari didedahkan segala yang terpendam di hati (dari iktiqad, niat, dan lain-lainnya),",
    "quran.86_10_translation": "Maka (pada saat itu) tidak ada bagi manusia sebarang kekuatan (untuk membela diri), dan tidak ada penolong (yang dapat memberikan pertolongan).",
    "quran.86_11_translation": "Demi langit yang berulang-ulang mencurahkan hujan,",
    "quran.86_12_translation": "Dan bumi yang merekah mengeluarkan tumbuh-tumbuhan,",
    "quran.86_13_translation": "Sesungguhnya keterangan Al-Quran adalah kata-kata pemutus (yang sebenar),",
    "quran.86_14_translation": "Dan bukanlah ia kata-kata yang olok-olok.",
    "quran.86_15_translation": "Sesungguhnya mereka (yang menentangmu, wahai Muhammad) bermati-mati menjalankan rancangan jahat,",
    "quran.86_16_translation": "Dan Aku pula tetap bertindak membalas rancangan jahat (mereka, dan menggagalkannya).",
    "quran.86_17_translation": "Oleh itu janganlah engkau hendakkan segera kebinasaan orang-orang kafir itu, berilah tempoh kepada mereka sedikit masa.",
    "quran.85_1_translation": "Demi langit yang mempunyai tempat-tempat peredaran bintang-bintang;",
    "quran.85_2_translation": "Dan hari (pembalasan) yang dijanjikan;",
    "quran.85_3_translation": "Dan makhluk-makhluk yang hadir menyaksikan hari itu, serta segala keadaan yang disaksikan; -",
    "quran.85_4_translation": "Celakalah kaum yang menggali parit,",
    "quran.85_5_translation": "(Parit) api yang penuh dengan bahan bakaran,",
    "quran.85_6_translation": "(Mereka dilaknat) ketika mereka duduk di kelilingnya,",
    "quran.85_7_translation": "Sambil mereka melihat apa yang mereka lakukan kepada orang-orang yang beriman.",
    "quran.85_8_translation": "Dan mereka tidak marah dan menyeksakan orang-orang yang beriman itu melainkan kerana orang-orang itu beriman kepada Allah Yang Maha Kuasa, lagi Maha Terpuji!",
    "quran.85_9_translation": "Tuhan yang menguasai segala alam langit dan bumi. Dan (ingatlah), Allah sentiasa menyaksikan tiap-tiap sesuatu.",
    "quran.85_10_translation": "Sesungguhnya orang-orang yang menimpakan bencana untuk memesongkan orang-orang lelaki yang beriman dan orang-orang perempuan yang beriman, kemudian mereka tidak bertaubat, maka mereka akan beroleh azab neraka Jahannam (kerana perbuatan buruk itu), dan mereka akan beroleh lagi azab api yang kuat membakar (kerana mereka tidak bertaubat).",
    "quran.85_11_translation": "Sesungguhnya orang-orang yang beriman dan beramal soleh, mereka akan beroleh Syurga yang mengalir di bawahnya beberapa sungai; yang demikian itu ialah kemenangan yang besar.",
    "quran.85_12_translation": "Sesungguhnya azab Tuhanmu (terhadap orang-orang yang kufur ingkar) amatlah berat.",
    "quran.85_13_translation": "Sesungguhnya Dia lah yang menciptakan (sekalian makhluk) pada mulanya, dan yang mengembalikannya (hidup semula sesudah mati).",
    "quran.85_14_translation": "Dan Dia lah yang Maha Pengampun, lagi Maha Pengasih.",
    "quran.85_15_translation": "Tuhan yang mempunyai Arasy yang tinggi kemuliaannya,",
    "quran.85_16_translation": "Yang berkuasa melakukan segala yang dikehendakinya.",
    "quran.85_17_translation": "Sudahkah sampai kepadamu (wahai Muhammad) perihal (kebinasaan yang telah menimpa) kaum-kaum yang menentang (Rasul-rasul yang diutuskan kepada mereka)?",
    "quran.85_18_translation": "(Mereka itu ialah kaum) Firaun, dan Thamud (kaum Nabi Soleh).",
    "quran.85_19_translation": "(Kaummu wahai Muhammad, bukan sahaja menolak ajaranmu), bahkan orang-orang yang kafir itu terus tenggelam dalam keadaan mendustakan kebenaran;",
    "quran.85_20_translation": "Sedang Allah, dari belakang mereka, melingkungi mereka (dengan kekuasaanNya)!",
    "quran.85_21_translation": "(Sebenarnya apa yang engkau sampaikan kepada mereka bukanlah syair atau sihir), bahkan ialah Al-Quran yang tertinggi kemuliaannya;",
    "quran.85_22_translation": "(Lagi yang terpelihara dengan sebaik-baiknya) pada Lauh Mahfuz.",
    "quran.84_1_translation": "Apabila langit terbelah,",
    "quran.84_2_translation": "Serta mematuhi perintah Tuhannya, dan sudah semestinya ia patuh;",
    "quran.84_3_translation": "Dan apabila bumi diratakan,",
    "quran.84_4_translation": "Serta mengeluarkan apa yang di dalamnya, dan menjadi kosong,",
    "quran.84_5_translation": "Serta mematuhi perintah Tuhannya, dan sudah semestinya ia patuh; - (Maka pada saat itu tiap-tiap seorang akan mengetahui apa yang telah dilakukannya).",
    "quran.84_6_translation": "Wahai manusia! Sesungguhnya engkau sentiasa berpenat-lelah (menjalankan keadaan hidupmu) dengan sedaya upayamu hinggalah (semasa engkau) kembali kepada Tuhanmu, kemudian engkau tetap menemui balasan apa yang engkau telah usahakan itu (tercatit semuanya).",
    "quran.84_7_translation": "Kemudian sesiapa yang diberi menerima surat amalnya dengan tangan kanannya, -",
    "quran.84_8_translation": "Maka ia akan dihisab dengan cara yang mudah dan ringan,",
    "quran.84_9_translation": "Dan ia akan pergi kepada keluarganya (yang beriman) dengan sukacita.",
    "quran.84_10_translation": "Dan sesiapa yang diberi menerima surat amalnya (dengan tangan kiri), dari sebelah belakangnya,",
    "quran.84_11_translation": "Maka ia akan meraung menyebut-nyebut kebinasaannya,",
    "quran.84_12_translation": "Dan ia akan menderita bakaran neraka yang marak menjulang.",
    "quran.84_13_translation": "Sebenarnya ia semasa di dunia dahulu bersukaria dalam kalangan keluarganya (yang juga kufur ingkar)!",
    "quran.84_14_translation": "Sesungguhnya ia menyangka bahawa ia tidak sekali-kali akan kembali (kepada Kami untuk menerima balasan) !",
    "quran.84_15_translation": "(Sangkaannya itu tidak betul) bahkan ia tetap kembali! Sesungguhnya Tuhannya sentiasa Melihat dan Mengetahui keadaannya!",
    "quran.84_16_translation": "Maka Aku bersumpah, demi mega;",
    "quran.84_17_translation": "Dan malam serta segala yang dihimpunkannya;",
    "quran.84_18_translation": "Dan bulan apabila (penuh cahayanya) menjadi purnama:",
    "quran.84_19_translation": "Sesungguhnya kamu tetap melalui beberapa keadaan yang bertingkat-tingkat baik buruknya, (sebelum kamu menemui Tuhan - menerima kesenangan dan kebahagiaan atau sebaliknya)",
    "quran.84_20_translation": "Maka apakah alasan bagi mereka bersikap tidak mahu beriman?",
    "quran.84_21_translation": "Dan (apakah pula alasannya) apabila dibacakan Al-Quran kepada mereka, mereka tidak mahu taat dan sujud?",
    "quran.84_22_translation": "(Tidak ada satu alasan pun) bahkan orang-orang yang kafir, semata-mata mendustakannya;",
    "quran.84_23_translation": "Sedang Allah mengetahui apa yang mereka rahsiakan dalam hati.",
    "quran.84_24_translation": "Maka khabarkanlah kepada mereka dengan azab yang tidak terperi sakitnya;",
    "quran.84_25_translation": "Tetapi orang-orang yang beriman dan beramal soleh mereka beroleh pahala balasan yang tidak putus-putus.",
    "quran.83_1_translation": "Kecelakaan besar bagi orang-orang yang curang (dalam timbangan dan sukatan),",
    "quran.83_2_translation": "Iaitu mereka yang apabila menerima sukatan (gantang cupak) dari orang lain mereka mengambilnya dengan cukup,",
    "quran.83_3_translation": "Dan (sebaliknya) apabila mereka menyukat atau menimbang untuk orang lain, mereka kurangi.",
    "quran.83_4_translation": "Tidakkah mereka menyangka bahawa mereka akan dibangkitkan (hidup semula sesudah mati)?",
    "quran.83_5_translation": "Pada hari (kiamat) yang amat besar (huru-haranya),",
    "quran.83_6_translation": "Hari berdiri manusia untuk mengadap Tuhan sekalian alam?",
    "quran.83_7_translation": "Tidak sepatutnya (mereka melakukan perbuatan yang salah itu dan melalaikan hari akhirat)! Sesungguhnya \"kitab suratan amal\" orang-orang yang berdosa itu (didaftarkan) dalam \"Sijjiin\".",
    "quran.83_8_translation": "Dan apa jalannya engkau dapat mengetahui: apa dia \"Sijjiin\" itu,",
    "quran.83_9_translation": "Ialah (tempat simpanan) kitab catitan yang jelas nyata, (yang menghimpunkan amalan orang-orang yang berdosa).",
    "quran.83_10_translation": "Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan -",
    "quran.83_11_translation": "Iaitu mereka yang mendustakan hari pembalasan.",
    "quran.83_12_translation": "Dan tiada yang mendustakannya melainkan tiap-tiap orang yang melampaui batas (kebenaran), lagi amat derhaka!",
    "quran.83_13_translation": "(Sehingga) apabila ia dibacakan kepadanya ayat-ayat Kami, ia berkata:\" Ini ialah dongeng orang-orang dahulu kala!\"",
    "quran.83_14_translation": "Sebenarnya! (Ayat-ayat Kami itu tidak ada cacatnya) bahkan mata hati mereka telah diselaputi kekotoran (dosa), dengan sebab (perbuatan kufur dan maksiat) yang mereka kerjakan.",
    "quran.83_15_translation": "Jangan lagi mereka berlaku demikian! (kalau tidak), mereka pada hari itu, tetap terdinding dari (rahmat) Tuhannya.",
    "quran.83_16_translation": "Kemudian, sesungguhnya mereka akan menderita bakaran neraka.",
    "quran.83_17_translation": "Akhirnya dikatakan (kepada mereka): \"Inilah dia (azab seksa) yang kamu dustakan dahulu.\"",
    "quran.83_18_translation": "Ingatlah wahai manusia! Sesungguhnya \"kitab suratan amal\" orang-orang yang berbakti (dengan taat dan amal kebajikan), adalah (didaftarkan) dalam\" Illiyiin\".",
    "quran.83_19_translation": "Dan apa jalannya engkau dapat mengetahui, apa dia \"Illiyiin\" itu?",
    "quran.83_20_translation": "Ialah (tempat simpanan) kitab catitan yang jelas nyata,",
    "quran.83_21_translation": "Yang disaksikan oleh sekumpulan malaikat, yang didampingkan Tuhan di sisinya.",
    "quran.83_22_translation": "Sesungguhnya orang-orang yang berbakti (dengan taat dan amal kebajikan), tetap berada di dalam Syurga yang penuh nikmat:",
    "quran.83_23_translation": "Mereka berehat di atas pelamin-pelamin (yang berhias), sambil melihat (segala keindahan dan kemuliaan yang disediakan untuk mereka di situ).",
    "quran.83_24_translation": "Engkau dapat melihat pada muka mereka: cahaya nikmat yang mereka perolehi.",
    "quran.83_25_translation": "Mereka diberi minum dari satu minuman yang termeterai bekasnya,",
    "quran.83_26_translation": "Meterainya kasturi; - dan untuk (memperolehi nikmat kesenangan) itu hendaknya berlumba-lumba mereka yang ingin merebut kelebihan dan kesenangan;",
    "quran.83_27_translation": "Dan campuran minuman itu adalah dari \"Tasnim\":",
    "quran.83_28_translation": "laitu matair yang diminum daripadanya oleh orang-orang yang di dampingkan (Tuhan di sisiNya).",
    "quran.83_29_translation": "Sesungguhnya orang-orang yang derhaka, mereka selalu tertawakan orang-orang yang beriman.",
    "quran.83_30_translation": "Dan apabila orang-orang yang beriman lalu dekat mereka, mereka mengerling dan memejam celikkan mata sesama sendiri (mencemuhnya).",
    "quran.83_31_translation": "Dan apabila mereka kembali kepada kaum keluarganya, mereka kembali dengan riang gembira;",
    "quran.83_32_translation": "Dan apabila mereka melihat orang-orang yang beriman, mereka berkata: \"Sesungguhnya orang-orang itu adalah golongan yang sesat!\"",
    "quran.83_33_translation": "Pada hal mereka tidak diutus untuk menjaga sesat atau tidaknya orang-orang yang beriman itu!",
    "quran.83_34_translation": "Maka pada hari ini, orang-orang yang beriman pula tertawakan orang yang kafir itu.",
    "quran.83_35_translation": "Sambil mereka berehat di atas pelamin-pelamin (yang berhias), serta melihat (hal yang berlaku kepada musuhnya).",
    "quran.83_36_translation": "(Untuk menambahkan kegembiraan mereka, mereka ditanya): \"Bukankah orang-orang yang kafir itu telah dibalas akan apa yang mereka telah kerjakan dahulu?\"",
    "quran.82_1_translation": "Apabila langit terbelah;",
    "quran.82_2_translation": "Dan apabila bintang-bintang gugur bertaburan;",
    "quran.82_3_translation": "Dan apabila lautan pecah bercampur-baur;",
    "quran.82_4_translation": "Dan apabila kubur-kubur dibongkarkan, -",
    "quran.82_5_translation": "(Setelah semuanya itu berlaku), tiap-tiap orang akan mengetahui apa yang telah dikerjakan dan ditinggalkannya.",
    "quran.82_6_translation": "Wahai manusia! Apakah yang memperdayakanmu - (berlaku derhaka) kepada Tuhanmu yang Maha Pemurah? -",
    "quran.82_7_translation": "Tuhan yang telah mencipta dan mengatur kejadianmu, lalu menjadikan anggotamu sesuai (dengan tujuan yang kerananya anggota itu diadakan), serta menjadikan (binaan tubuh badanmu) sama padan dengan kekuatannya;",
    "quran.82_8_translation": "Dalam bentuk dan rupa apa sahaja yang dikehendakiNya, Ia menyusun kejadianmu.",
    "quran.82_9_translation": "Sebenarnya tidak ada yang memperdayakan kamu (hai golongan yang ingkar)! Bahkan kamu sendiri tidak percayakan adanya hari pembalasan.",
    "quran.82_10_translation": "Padahal sesungguhnya, ada malaikat-malaikat yang menjaga dan mengawas segala bawaan kamu,",
    "quran.82_11_translation": "(Mereka adalah makhluk) yang mulia (di sisi Allah), lagi ditugaskan menulis (amal-amal kamu);",
    "quran.82_12_translation": "Mereka mengetahui apa yang kamu lakukan.",
    "quran.82_13_translation": "(Gunanya catitan malaikat-malaikat itu ialah: untuk menyatakan siapa yang berbakti dan siapa yang bersalah) - kerana sesungguhnya: orang-orang yang berbakti (dengan taat dan amal kebajikan), tetap berada dalam Syurga yang penuh nikmat;",
    "quran.82_14_translation": "Dan sesungguhnya orang-orang yang bersalah, bertempat dalam neraka yang menjulang-julang.",
    "quran.82_15_translation": "Mereka menderita bakaran neraka itu pada hari pembalasan,",
    "quran.82_16_translation": "Dan mereka (sentiasa berada dalam azab seksanya), tidak ghaib daripadanya.",
    "quran.82_17_translation": "Dan apa jalannya engkau dapat mengetahui kedahsyatan hari pembalasan itu?",
    "quran.82_18_translation": "Sekali lagi, apa jalannya engkau dapat mengetahui kedahsyatan hari pembalasan itu?",
    "quran.82_19_translation": "(Hari itu ialah) hari seseorang tidak dapat memberikan pertolongan sedikitpun kepada orang lain, dan segala urusan pada hari itu tertentu bagi Allah.",
    "quran.81_1_translation": "Apabila matahari dilingkari cahayanya (dan hilang lenyap);",
    "quran.81_2_translation": "Dan apabila bintang-bintang gugur berselerak;",
    "quran.81_3_translation": "Dan apabila gunung-ganang di terbangkan ke angkasa (setelah dihancurkan menjadi debu);",
    "quran.81_4_translation": "Dan apabila unta-unta yang bunting terbiar;",
    "quran.81_5_translation": "Dan apabila binatang-binatang liar dihimpunkan;",
    "quran.81_6_translation": "Dan apabila lautan meluap-luap bercampur-baur;",
    "quran.81_7_translation": "Dan apabila tiap-tiap diri disatukan dengan pasangannya;",
    "quran.81_8_translation": "Dan apabila anak perempuan yang ditanam hidup-hidup: ditanya, -",
    "quran.81_9_translation": "Dengan dosa apakah ia dibunuh?",
    "quran.81_10_translation": "Dan apabila surat-surat amal dibentangkan;",
    "quran.81_11_translation": "Dan apabila langit ditanggalkan dari tempatnya;",
    "quran.81_12_translation": "Dan apabila neraka dinyalakan menjulang;",
    "quran.81_13_translation": "Dan apabila Syurga didekatkan;",
    "quran.81_14_translation": "(Setelah semuanya itu berlaku), tiap-tiap orang akan mengetahui tentang amal yang telah dibawanya.",
    "quran.81_15_translation": "Oleh itu, Aku bersumpah dengan bintang-bintang yang tenggelam timbul;",
    "quran.81_16_translation": "Yang beredar, juga yang tetap pada tempatnya;",
    "quran.81_17_translation": "Dan malam, apabila ia hampir habis,",
    "quran.81_18_translation": "Dan siang, apabila ia mulai terang;",
    "quran.81_19_translation": "Sebenarnya Al-Quran itu, sungguh-sungguh Kalamullah (yang disampaikan oleh Jibril) Utusan yang mulia,",
    "quran.81_20_translation": "Yang kuat gagah, lagi berkedudukan tinggi di sisi Allah yang mempunyai Arasy,",
    "quran.81_21_translation": "Yang ditaati di sana (dalam kalangan malaikat), lagi dipercayai.",
    "quran.81_22_translation": "Dan sebenarnya sahabat kamu (Nabi Muhammad) itu (wahai golongan yang menentang Islam), bukanlah ia seorang gila (seperti yang kamu tuduh);",
    "quran.81_23_translation": "Dan (Nabi Muhammad yakin bahawa yang disampaikan kepadanya ialah wahyu dari Tuhan, kerana) demi sesungguhnya! Nabi Muhammad telah mengenal dan melihat Jibril di kaki langit yang nyata.",
    "quran.81_24_translation": "Dan bukanlah Nabi Muhammad seorang yang boleh dituduh dan disangka buruk, terhadap penyampaiannya mengenai perkara-perkara yang ghaib.",
    "quran.81_25_translation": "Dan sebenarnya Al-Quran itu bukanlah perkataan Syaitan yang kena rejam.",
    "quran.81_26_translation": "(Dengan yang demikian) maka ke manakah kamu hendak pergi (kiranya kamu masih menyeleweng dari jalan Al-Quran)?",
    "quran.81_27_translation": "Al-Quran itu tidak lain hanyalah peringatan bagi seluruh penduduk alam:",
    "quran.81_28_translation": "Iaitu bagi sesiapa dari kamu yang mahu tetap teguh di atas jalan (Islam) yang betul.",
    "quran.81_29_translation": "Dan kamu tidak dapat menentukan kemahuan kamu (mengenai sesuatupun), kecuali dengan cara yang diatur oleh Allah, Tuhan yang memelihara dan mentadbirkan seluruh alam.",
    "quran.79_1_translation": "Demi (makhluk-makhluk) yang mencabut (apa yang ditugaskan mencabutnya) dengan cara yang sekasar-kasarnya;",
    "quran.79_2_translation": "Dan yang menarik (apa yang ditugaskan menariknya) dengan cara yang selembut-lembutnya;",
    "quran.79_3_translation": "Dan demi (makhluk-makhluk) yang cergas bergerak (menerima perintah) dengan gerak yang secergas-cergasnya;",
    "quran.79_4_translation": "Lalu masing-masing berlumba-lumba dahulu-mendahului (menjalankan tugasnya) dengan cara yang sesungguh-sungguhnya;",
    "quran.79_5_translation": "Serta menyempurnakan tadbir urusan alam yang diperintahkan kepadanya; (sumpah demi sumpah, sesungguhnya kamu akan dibangkitkan hidup semula pada hari kiamat)! -",
    "quran.79_6_translation": "Pada masa berlakunya \"tiupan sangkakala yang pertama\" yang menggoncangkan alam, (sehingga mati segala yang bernyawa dan punah-ranah sekalian makhluk selain dari yang dikecualikan),",
    "quran.79_7_translation": "Tiupan yang pertama itu diikuti oleh tiupan yang kedua, (yang menyebabkan orang-orang yang mati semuanya hidup semula serta keluar dari kubur masing-masing);",
    "quran.79_8_translation": "Hati (manusia) pada hari itu berdebar-debar takut,",
    "quran.79_9_translation": "Pemandangannya tunduk gerun.",
    "quran.79_10_translation": "Mereka (yang ingkar) berkata: \"Sungguhkah kita akan dikembalikan hidup seperti keadaan di dunia dahulu?",
    "quran.79_11_translation": "\"Bolehkah (dihidupkan semula) sesudah kita menjadi tulang yang reput?\"",
    "quran.79_12_translation": "Mereka berkata lagi (secara mengejek: \"Kalaulah berlaku) yang demikian, sudah tentu kembalinya kita (hidup semula) itu satu perkara yang merugikan!\"",
    "quran.79_13_translation": "(Menghidupkan semula tidaklah sukar), kerana berlakunya perkara itu hanyalah dengan satu jeritan (yang terbit dari tiupan sangkakala yang kedua), -",
    "quran.79_14_translation": "Yang menyebabkan mereka dengan serta-merta berada di muka bumi yang putih rata.",
    "quran.79_15_translation": "Sudahkah sampai kepadamu (wahai Muhammad) perihal Nabi Musa?",
    "quran.79_16_translation": "Ketika ia diseru oleh Tuhannya di \"Wadi Tuwa\" yang suci; -",
    "quran.79_17_translation": "(Lalu diperintahkan kepadanya): \"Pergilah kepada Firaun, sesungguhnya ia telah melampaui batas (dalam kekufuran dan kezalimannya);",
    "quran.79_18_translation": "\"Serta katakanlah kepadanya: `Adakah engkau suka hendak mensucikan dirimu (dari kekufuran)?",
    "quran.79_19_translation": "`Dan mahukah, aku tunjuk kepadamu jalan mengenal Tuhanmu, supaya engkau merasa takut (melanggar perintahNya)? ' \"",
    "quran.79_20_translation": "(Setelah Nabi Musa menyempurnakan perintah Tuhannya, dan Firaun pun meminta bukti kebenarannya); maka Nabi Musa memperlihatkan kepada Firaun: mukjizat yang besar.",
    "quran.79_21_translation": "Lalu Firaun mendustakan (Nabi Musa) dan menderhaka (kepada Allah);",
    "quran.79_22_translation": "Kemudian ia berpaling ingkar sambil menjalankan usahanya (menentang Nabi Musa).",
    "quran.79_23_translation": "Lalu ia menghimpunkan orang-orangnya dan menyeru, -",
    "quran.79_24_translation": "Dengan berkata: \"Akulah tuhan kamu, yang tertinggi\".",
    "quran.79_25_translation": "Maka Allah menyeksa Firaun di akhirat dan di dunia ini, dengan azab yang menakutkan sesiapa yang mengetahuinya.",
    "quran.79_26_translation": "Sesungguhnya yang demikian itu mengandungi pelajaran yang mendatangkan iktibar bagi orang-orang yang takut (melanggar perintah Tuhannya).",
    "quran.79_27_translation": "(Wahai golongan yang ingkarkan kebangkitan hidup semula!) Kamukah yang sukar diciptakan atau langit? Tuhan telah membinanya (dengan Kukuh)!",
    "quran.79_28_translation": "Ia telah meninggikan bangunan langit itu lalu menyempurnaKannya,",
    "quran.79_29_translation": "Dan Ia menjadikan malamnya gelap-gelita, serta menjadikan siangnya terang-benderang.",
    "quran.79_30_translation": "Dan bumi sesudah itu dihamparkannya (untuk kemudahan penduduknya), -",
    "quran.79_31_translation": "Ia mengeluarkan dari bumi itu: airnya dan tumbuh-tumbuhannya;",
    "quran.79_32_translation": "Dan gunung-ganang pula dikukuhkan letaknya (di bumi, sebagai pancang pasak yang menetapnya);",
    "quran.79_33_translation": "(Semuanya itu) untuk kegunaan kamu dan binatang-binatang ternak kamu.",
    "quran.79_34_translation": "Maka apabila datang hari yang bencananya amat besar, -",
    "quran.79_35_translation": "Iaitu hari manusia akan mengingati apa yang telah diusahakannya, -",
    "quran.79_36_translation": "Dan neraka diperlihatkan kepada sesiapa sahaja yang dapat melihatnya, -",
    "quran.79_37_translation": "Maka (dapatlah masing-masing mengetahui kesudahannya); adapun orang yang melampau (perbuatan derhakanya), -",
    "quran.79_38_translation": "Serta ia mengutamakan kehidupan dunia semata-mata, -",
    "quran.79_39_translation": "Maka sesungguhnya neraka Jahanamlah tempat kediamannya.",
    "quran.79_40_translation": "Adapun orang yang takutkan keadaan semasa ia berdiri di mahkamah Tuhannya, (untuk dihitung amalnya), serta ia menahan dirinya dari menurut hawa nafsu, -",
    "quran.79_41_translation": "Maka sesungguhnya Syurgalah tempat kediamannya.",
    "quran.79_42_translation": "Mereka (yang ingkar) selalu bertanya kepadamu (wahai Muhammad) tentang hari kiamat: \"Bilakah masa datangnya?\"",
    "quran.79_43_translation": "Apa hubungannya tugasmu dengan (soal) menerangkan masa kedatangan hari kiamat itu?",
    "quran.79_44_translation": "Kepada Tuhanmu lah terserah kesudahan ilmu mengenainya.",
    "quran.79_45_translation": "Tugasmu hanyalah memberi amaran kepada orang yang takut akan huru-hara hari kiamat itu.",
    "quran.79_46_translation": "(Sangatlah dahsyatnya huru-hara hari itu, sehingga orang-orang yang bersalah merasa) pada masa melihatnya: seolah-olah mereka tidak tinggal di dunia melainkan sekadar satu petang atau paginya sahaja.",
    "quran.78_1_translation": "Tentang apakah mereka bertanya-tanya?",
    "quran.78_2_translation": "Tentang berita yang besar, (berita kebangkitan manusia hidup semula menerima balasannya).",
    "quran.78_3_translation": "Yang mereka (ragu-ragu dan) berselisihan mengenainya.",
    "quran.78_4_translation": "Jangan! (Janganlah mereka bersikap demikian!) Mereka akan mengetahui (dengan yakin tentang kebenaran hari balasan itu).",
    "quran.78_5_translation": "Sekali lagi jangan! (Janganlah mereka berselisihan!) Mereka akan mengetahui kelak (tentang apa yang akan menimpa mereka).",
    "quran.78_6_translation": "(Mengapa kamu ragu-ragukan kekuasaan Kami menghidupkan semula orang-orang yang telah mati?) Bukankah Kami telah menjadikan bumi (terbentang luas) sebagai hamparan?",
    "quran.78_7_translation": "Dan gunung-ganang sebagai pancang pasaknya?",
    "quran.78_8_translation": "Dan Kami telah menciptakan kamu berpasang-pasang?",
    "quran.78_9_translation": "Dan Kami telah menjadikan tidur kamu untuk berehat?",
    "quran.78_10_translation": "Dan Kami telah menjadikan malam (dengan gelapnya) sebagai pakaian (yang melindungi)?",
    "quran.78_11_translation": "Dan Kami telah menjadikan siang (dengan cahaya terangnya) - masa untuk mencari rezeki?",
    "quran.78_12_translation": "Dan Kami telah membina di atas kamu tujuh petala (langit) yang kuat kukuh?",
    "quran.78_13_translation": "Dan Kami telah mengadakan matahari menjadi lampu yang terang-benderang cahayanya?",
    "quran.78_14_translation": "Dan Kami telah menurunkan dari awan, air (hujan) yang mencurah-curah, -",
    "quran.78_15_translation": "Untuk Kami mengeluarkan dengan air itu, biji-bijian dan tumbuh-tumbuhan, -",
    "quran.78_16_translation": "Serta kebun-kebun yang subur bertaut-taut pokoknya?",
    "quran.78_17_translation": "Sesungguhnya hari pemutusan hukum itu, adalah satu masa yang ditentukan,",
    "quran.78_18_translation": "Iaitu masa ditiup sangkakala, lalu kamu (bangkit hidup) serta datang berpuak-puak (ke Padang Mahsyar);",
    "quran.78_19_translation": "Dan (pada masa itu) langit dipecah belahkan sehingga tiap-tiap belahannya menjadi ibarat pintu yang terbuka luas,",
    "quran.78_20_translation": "Dan gunung-ganang - setelah dihancurkan - diterbangkan ke angkasa, lalu menjadilah ia bayangan semata-mata seperti riak sinaran panas di padang pasir.",
    "quran.78_21_translation": "Sesungguhnya neraka Jahannam adalah disediakan -",
    "quran.78_22_translation": "Untuk orang-orang yang melampaui batas hukum Tuhan, sebagai tempat kembalinya.",
    "quran.78_23_translation": "Mereka tinggal di dalamnya berkurun-kurun lamanya.",
    "quran.78_24_translation": "Mereka tidak dapat merasai udara yang sejuk di dalamnya, dan tidak pula sebarang minuman -",
    "quran.78_25_translation": "Kecuali air panas yang menggelegak, dan air danur yang mengalir, -",
    "quran.78_26_translation": "Sebagai balasan yang sesuai (dengan amal mereka yang buruk).",
    "quran.78_27_translation": "Kerana sesungguhnya mereka dahulu tidak menaruh ingatan terhadap hari hitungan amal,",
    "quran.78_28_translation": "Dan mereka telah mendustakan dengan sesungguh-sungguhnya akan ayat-ayat keterangan Kami;",
    "quran.78_29_translation": "Dan tiap-tiap sesuatu dari bawaan hidupnya, telah Kami hitung secara bertulis.",
    "quran.78_30_translation": "(Setelah mereka masuk ke dalam neraka, dikatakan kepada mereka: \"Oleh sebab kamu telah mendustakan ayat-ayat Kami) maka rasalah kamu (azab yang disediakan), kerana Kami tidak akan melakukan selain dari menambah berbagai azab kepada kamu\".",
    "quran.78_31_translation": "Sesungguhnya orang-orang yang bertaqwa, disediakan Syurga tempat mereka beroleh apa yang mereka ingini.",
    "quran.78_32_translation": "(Mereka akan beroleh) taman-taman bunga dan kebun-kebun buah-buahan, terutama anggur;",
    "quran.78_33_translation": "Dan perawan-perawan yang sebaya umurnya;",
    "quran.78_34_translation": "Serta piala atau gelas yang penuh dengan minuman;",
    "quran.78_35_translation": "Mereka tidak mendengar di dalam Syurga itu perkataan yang sia-sia, dan tiada pula perkataan yang dusta;",
    "quran.78_36_translation": "Sebagai balasan dari Tuhanmu, iaitu satu limpah kurnia yang dikira cukup (menurut yang dijanjikanNya),",
    "quran.78_37_translation": "Tuhan yang mentadbirkan tujuh petala langit dan bumi serta apa yang ada di antara keduanya, Tuhan Yang Maha Pemurah, tidak ada sesiapapun diberi kuasa berkata-kata denganNya (untuk memohon pertimbangan tentang balasan atau pengurniaan itu);",
    "quran.78_38_translation": "(Tambahan pula) pada masa Jibril dan malaikat-malaikat yang lain berdiri bersaf-saf (menunggu perintah Tuhan), tidak ada yang berani berkata-kata (memohon pertimbangan) melainkan yang telah diizinkan baginya oleh Tuhan Yang Maha Pemurah, serta ia berkata benar.",
    "quran.78_39_translation": "Itulah keterangan-keterangan mengenai hari (kiamat) yang sungguh tetap berlakunya; maka sesiapa yang mahukan kebaikan dirinya, dapatlah ia mengambil jalan dan cara kembali kepada Tuhannya (dengan iman dan amal yang soleh)!",
    "quran.78_40_translation": "Sesungguhnya (dengan keterangan-keterangan yang tersebut), Kami memberi amaran kepada kamu mengenai azab yang dekat (masa datangnya), - iaitu hari seseorang melihat apa yang telah diusahakannya; dan orang yang kafir akan berkata (pada hari itu): \"Alangkah baiknya kalau aku menjadi tanah (supaya aku tidak dibangkitkan untuk dihitung amalku dan menerima balasan)\"."
  },
  "fr": {
    "quran.114_1_translation": "Dis: «Je cherche protection auprès du Seigneur des hommes.",
    "quran.114_2_translation": "Le Souverain des hommes,",
    "quran.114_3_translation": "Dieu des hommes,",
    "quran.114_4_translation": "contre le mal du mauvais conseiller, furtif,",
    "quran.114_5_translation": "qui souffle le mal dans les poitrines des hommes,",
    "quran.114_6_translation": "qu'il (le conseiller) soit un djinn, ou un être humain».",
    "quran.113_1_translation": "Dis: «Je cherche protection auprès du Seigneur de l'aube naissante,",
    "quran.113_2_translation": "contre le mal des êtres qu'Il a créés,",
    "quran.113_3_translation": "contre le mal de l'obscurité quand elle s'approfondit,",
    "quran.113_4_translation": "contre le mal de celles qui soufflent [les sorcières] sur les nœuds,",
    "quran.113_5_translation": "et contre le mal de l'envieux quand il envie».",
    "quran.112_1_translation": "Dis: «Il est Allah, Unique.",
    "quran.112_2_translation": "Allah, Le Seul à être imploré pour ce que nous désirons.",
    "quran.112_3_translation": "Il n'a jamais engendré, n'a pas été engendré non plus.",
    "quran.112_4_translation": "Et nul n'est égal à Lui».",
    "quran.111_1_translation": "Que périssent les deux mains d'Abû-Lahab et que lui-même périsse.",
    "quran.111_2_translation": "Sa fortune ne lui sert à rien, ni ce qu'il a acquis.",
    "quran.111_3_translation": "Il sera brûlé dans un Feu plein de flammes,",
    "quran.111_4_translation": "de même sa femme, la porteuse de bois,",
    "quran.111_5_translation": "à son cou, une corde de fibres.",
    "quran.110_1_translation": "Lorsque vient le secours d'Allah ainsi que la victoire,",
    "quran.110_2_translation": "et que tu vois les gens entrer en foule dans la religion d'Allah,",
    "quran.110_3_translation": "alors, par la louange, célèbre la gloire de ton Seigneur et implore Son pardon. Car c'est Lui le grand Accueillant au repentir.",
    "quran.109_1_translation": "Dis: «O vous les infidèles!",
    "quran.109_2_translation": "Je n'adore pas ce que vous adorez.",
    "quran.109_3_translation": "Et vous n'êtes pas adorateurs de ce que j'adore.",
    "quran.109_4_translation": "Je ne suis pas adorateur de ce que vous adorez.",
    "quran.109_5_translation": "Et vous n'êtes pas adorateurs de ce que j'adore.",
    "quran.109_6_translation": "A vous votre religion, et à moi ma religion».",
    "quran.108_1_translation": "Nous t'avons certes, accordé l'Abondance.",
    "quran.108_2_translation": "Accomplis la Salât pour ton Seigneur et sacrifie.",
    "quran.108_3_translation": "Celui qui te hait sera certes, sans postérité.",
    "quran.107_1_translation": "Vois-tu celui qui traite de mensonge la Rétribution?",
    "quran.107_2_translation": "C'est bien lui qui repousse l'orphelin,",
    "quran.107_3_translation": "et qui n'encourage point à nourrir le pauvre.",
    "quran.107_4_translation": "Malheur donc, à ceux qui prient",
    "quran.107_5_translation": "tout en négligeant (et retardant) leur Salât,",
    "quran.107_6_translation": "qui sont pleins d'ostentation,",
    "quran.107_7_translation": "et refusent l'ustensile (à celui qui en a besoin).",
    "quran.106_1_translation": "A cause du pacte des Coraïch,",
    "quran.106_2_translation": "De leur pacte [concernant] les voyages d'hiver et d'été.",
    "quran.106_3_translation": "Qu'ils adorent donc le Seigneur de cette Maison [la Ka'ba],",
    "quran.106_4_translation": "qui les a nourris contre la faim et rassurés de la crainte!",
    "quran.105_1_translation": "N'as-tu pas vu comment ton Seigneur a agi envers les gens de l'Eléphant?",
    "quran.105_2_translation": "N'a-t-Il pas rendu leur ruse complètement vaine?",
    "quran.105_3_translation": "et envoyé sur eux des oiseaux par volées",
    "quran.105_4_translation": "qui leur lançaient des pierres d'argile?",
    "quran.105_5_translation": "Et Il les a rendus semblables à une paille mâchée.",
    "quran.104_1_translation": "Malheur à tout calomniateur diffamateur,",
    "quran.104_2_translation": "qui amasse une fortune et la compte,",
    "quran.104_3_translation": "pensant que sa fortune l'immortalisera.",
    "quran.104_4_translation": "Mais non! Il sera certes, jeté dans la Hutamah.",
    "quran.104_5_translation": "Et qui te dira ce qu'est la Hutamah?",
    "quran.104_6_translation": "Le Feu attisé d'Allah",
    "quran.104_7_translation": "qui monte jusqu'aux cœurs.",
    "quran.104_8_translation": "Il se refermera sur eux,",
    "quran.104_9_translation": "en colonnes (de flammes) étendues.",
    "quran.103_1_translation": "Par le Temps!",
    "quran.103_2_translation": "L'homme est certes, en perdition,",
    "quran.103_3_translation": "sauf ceux qui croient et accomplissent les bonnes œuvres, s'enjoignent mutuellement la vérité et s'enjoignent mutuellement l'endurance.",
    "quran.102_1_translation": "La course aux richesses vous distrait,",
    "quran.102_2_translation": "jusqu'à ce que vous visitiez les tombes.",
    "quran.102_3_translation": "Mais non! Vous saurez bientôt!",
    "quran.102_4_translation": "(Encore une fois)! Vous saurez bientôt!",
    "quran.102_5_translation": "Sûrement! Si vous saviez de science certaine.",
    "quran.102_6_translation": "Vous verrez, certes, la Fournaise.",
    "quran.102_7_translation": "Puis, vous la verrez certes, avec l'œil de la certitude.",
    "quran.102_8_translation": "Puis, assurément, vous serez interrogés, ce jour-là, sur les délices.",
    "quran.101_1_translation": "Le fracas!",
    "quran.101_2_translation": "Qu'est-ce que le fracas?",
    "quran.101_3_translation": "Et qui te dira ce qu'est le fracas?",
    "quran.101_4_translation": "C'est le jour où les gens seront comme des papillons éparpillés,",
    "quran.101_5_translation": "et les montagnes comme de la laine cardée;",
    "quran.101_6_translation": "quant à celui dont la balance sera lourde",
    "quran.101_7_translation": "il sera dans une vie agréable;",
    "quran.101_8_translation": "et quant à celui dont la balance sera légère,",
    "quran.101_9_translation": "sa mère [destination] est un abîme très profond.",
    "quran.101_10_translation": "Et qui te dira ce que c'est?",
    "quran.101_11_translation": "C'est un Feu ardent.",
    "quran.100_1_translation": "Par les coursiers qui halètent,",
    "quran.100_2_translation": "qui font jaillir des étincelles,",
    "quran.100_3_translation": "qui attaquent au matin,",
    "quran.100_4_translation": "et font ainsi voler la poussière,",
    "quran.100_5_translation": "et pénètrent au centre de la troupe ennemie.",
    "quran.100_6_translation": "L'homme est, certes, ingrat envers son Seigneur;",
    "quran.100_7_translation": "et pourtant, il est certes, témoin de cela;",
    "quran.100_8_translation": "et pour l'amour des richesses il est certes ardent.",
    "quran.100_9_translation": "Ne sait-il donc pas que lorsque ce qui est dans les tombes sera bouleversé,",
    "quran.100_10_translation": "et que sera dévoilé ce qui est dans les poitrines,",
    "quran.100_11_translation": "ce jour-là, certes, leur Seigneur sera Parfaitement Connaisseur d'eux?",
    "quran.99_1_translation": "Quand la terre tremblera d'un violent tremblement,",
    "quran.99_2_translation": "et que la terre fera sortir ses fardeaux,",
    "quran.99_3_translation": "et que l'homme dira: «Qu'a-t-elle?»",
    "quran.99_4_translation": "ce jour-là, elle contera son histoire,",
    "quran.99_5_translation": "selon ce que ton Seigneur lui aura révélé [ordonné].",
    "quran.99_6_translation": "Ce jour-là, les gens sortiront séparément pour que leur soient montrées leurs œuvres.",
    "quran.99_7_translation": "Quiconque fait un bien fût-ce du poids d'un atome, le verra,",
    "quran.99_8_translation": "et quiconque fait un mal fût-ce du poids d'un atome, le verra.",
    "quran.98_1_translation": "Les infidèles parmi les gens du Livre, ainsi que les Associateurs, ne cesseront pas de mécroire jusqu'à ce que leur vienne la Preuve évidente:",
    "quran.98_2_translation": "un Messager, de la part d'Allah, qui leur récite des feuilles purifiées,",
    "quran.98_3_translation": "dans lesquelles se trouvent des prescriptions d'une rectitude parfaite.",
    "quran.98_4_translation": "Et ceux à qui le Livre a été donné ne se sont divisés qu'après que la preuve leur fut venue.",
    "quran.98_5_translation": "Il ne leur a été commandé, cependant, que d'adorer Allah, Lui vouant un culte exclusif, d'accomplir la Salât et d'acquitter la Zakât. Et voilà la religion de droiture.",
    "quran.98_6_translation": "Les infidèles parmi les gens du Livre, ainsi que les Associateurs iront au feu de l'Enfer, pour y demeurer éternellement. De toute la création, ce sont eux les pires.",
    "quran.98_7_translation": "Quant à ceux qui croient et accomplissent les bonnes œuvres, ce sont les meilleurs de toute la création.",
    "quran.98_8_translation": "Leur récompense auprès d'Allah sera les Jardins de séjour, sous lesquels coulent les ruisseaux, pour y demeurer éternellement. Allah les agrée et ils L'agréent. Telle sera [la récompense] de celui qui craint son Seigneur.",
    "quran.97_1_translation": "Nous l'avons certes, fait descendre (le Coran) pendant la nuit d'Al-Qadr.",
    "quran.97_2_translation": "Et qui te dira ce qu'est la nuit d'Al-Qadr?",
    "quran.97_3_translation": "La nuit d'Al-Qadr est meilleure que mille mois.",
    "quran.97_4_translation": "Durant celle-ci descendent les Anges ainsi que l'Esprit, par permission de leur Seigneur pour tout ordre.",
    "quran.97_5_translation": "Elle est paix et salut jusqu'à l'apparition de l'aube.",
    "quran.96_1_translation": "Lis, au nom de ton Seigneur qui a créé,",
    "quran.96_2_translation": "qui a créé l'homme d'une adhérence.",
    "quran.96_3_translation": "Lis! Ton Seigneur est le Très Noble,",
    "quran.96_4_translation": "qui a enseigné par la plume [le calame],",
    "quran.96_5_translation": "a enseigné à l'homme ce qu'il ne savait pas.",
    "quran.96_6_translation": "Prenez-garde! Vraiment l'homme devient rebelle,",
    "quran.96_7_translation": "dès qu'il estime qu'il peut se suffire à lui-même (à cause de sa richesse).",
    "quran.96_8_translation": "Mais, c'est vers ton Seigneur qu'est le retour.",
    "quran.96_9_translation": "As-tu vu celui qui interdit",
    "quran.96_10_translation": "à un serviteur d'Allah [Muhammad] de célébrer la Salât?",
    "quran.96_11_translation": "Vois-tu s'il est sur la bonne voie,",
    "quran.96_12_translation": "ou s'il ordonne la piété?",
    "quran.96_13_translation": "Vois-tu s'il dément et tourne le dos?",
    "quran.96_14_translation": "Ne sait-il pas que vraiment Allah voit?",
    "quran.96_15_translation": "Mais non! S'il ne cesse pas, Nous le saisirons certes, par le toupet,",
    "quran.96_16_translation": "le toupet d'un menteur, d'un pécheur.",
    "quran.96_17_translation": "Qu'il appelle donc son assemblée.",
    "quran.96_18_translation": "Nous appellerons les gardiens [de l'Enfer].",
    "quran.96_19_translation": "Non! Ne lui obéis pas; mais prosterne-toi et rapproche-toi.",
    "quran.95_1_translation": "Par le figuier et l'olivier!",
    "quran.95_2_translation": "Et par le Mont Sînîn!",
    "quran.95_3_translation": "Et par cette Cité sûre!",
    "quran.95_4_translation": "Nous avons certes créé l'homme dans la forme la plus parfaite.",
    "quran.95_5_translation": "Ensuite, Nous l'avons ramené au niveau le plus bas,",
    "quran.95_6_translation": "sauf ceux qui croient et accomplissent les bonnes œuvres: ceux-là auront une récompense jamais interrompue.",
    "quran.95_7_translation": "Après cela, qu'est-ce qui te fait traiter la rétribution de mensonge?",
    "quran.95_8_translation": "Allah n'est-Il pas le plus sage des Juges?",
    "quran.93_1_translation": "Par le Jour Montant!",
    "quran.93_2_translation": "Et par la nuit quand elle couvre tout!",
    "quran.93_3_translation": "Ton Seigneur ne t'a ni abandonné, ni détesté.",
    "quran.93_4_translation": "La vie dernière t'est, certes, meilleure que la vie présente.",
    "quran.93_5_translation": "Ton Seigneur t'accordera certes [Ses faveurs], et alors tu seras satisfait.",
    "quran.93_6_translation": "Ne t'a-t-Il pas trouvé orphelin? Alors Il t'a accueilli!",
    "quran.93_7_translation": "Ne t'a-t-Il pas trouvé égaré? Alors Il t'a guidé.",
    "quran.93_8_translation": "Ne t'a-t-Il pas trouvé pauvre? Alors Il t'a enrichi.",
    "quran.93_9_translation": "Quant à l'orphelin, donc, ne le maltraite pas.",
    "quran.93_10_translation": "Quant au demandeur, ne le repousse pas.",
    "quran.93_11_translation": "Et quant au bienfait de ton Seigneur, proclame-le.",
    "quran.92_1_translation": "Par la nuit quand elle enveloppe tout!",
    "quran.92_2_translation": "Par le jour quand il éclaire!",
    "quran.92_3_translation": "Et par ce qu'Il a créé, mâle et femelle!",
    "quran.92_4_translation": "Vos efforts sont divergents.",
    "quran.92_5_translation": "Celui qui donne et craint (Allah)",
    "quran.92_6_translation": "et déclare véridique la plus belle récompense",
    "quran.92_7_translation": "Nous lui faciliterons la voie au plus grand bonheur.",
    "quran.92_8_translation": "Et quant à celui qui est avare, se dispense (de l'adoration d'Allah),",
    "quran.92_9_translation": "et traite de mensonge la plus belle récompense,",
    "quran.92_10_translation": "Nous lui faciliterons la voie à la plus grande difficulté,",
    "quran.92_11_translation": "et à rien ne lui serviront ses richesses quand il sera jeté (au Feu).",
    "quran.92_12_translation": "C'est à Nous, certes, de guider;",
    "quran.92_13_translation": "à Nous appartient, certes, la vie dernière et la vie présente.",
    "quran.92_14_translation": "Je vous ai donc avertis d'un Feu qui flambe",
    "quran.92_15_translation": "où ne brûlera que le damné,",
    "quran.92_16_translation": "qui dément et tourne le dos;",
    "quran.92_17_translation": "alors qu'en sera écarté le pieux,",
    "quran.92_18_translation": "qui donne ses biens pour se purifier",
    "quran.92_19_translation": "et auprès de qui personne ne profite d'un bienfait intéressé,",
    "quran.92_20_translation": "mais seulement pour la recherche de La Face de son Seigneur le Très Haut.",
    "quran.92_21_translation": "Et certes, il sera bientôt satisfait!",
    "quran.91_1_translation": "Par le soleil et par sa clarté!",
    "quran.91_2_translation": "Et par la lune quand elle le suit!",
    "quran.91_3_translation": "Et par le jour quand il l'éclaire!",
    "quran.91_4_translation": "Et par la nuit quand elle l'enveloppe!",
    "quran.91_5_translation": "Et par le ciel et Celui qui l'a construit!",
    "quran.91_6_translation": "Et par la terre et Celui qui l'a étendue!",
    "quran.91_7_translation": "Et par l'âme et Celui qui l'a harmonieusement façonnée;",
    "quran.91_8_translation": "et lui a alors inspiré son immoralité, de même que sa piété!",
    "quran.91_9_translation": "A réussi, certes, celui qui la purifie.",
    "quran.91_10_translation": "Et est perdu, certes, celui qui la corrompt.",
    "quran.91_11_translation": "Les Thamûd, par leur transgression, ont crié au mensonge,",
    "quran.91_12_translation": "lorsque le plus misérable d'entre eux se leva (pour tuer la chamelle)",
    "quran.91_13_translation": "Le Messager d'Allah leur avait dit: «La chamelle d'Allah! Laissez-la boire.",
    "quran.91_14_translation": "Mais, ils le traitèrent de menteur, et la tuèrent. Leur Seigneur les détruisit donc, pour leur péché et étendit Son châtiment sur tous.",
    "quran.91_15_translation": "Et Allah n'a aucune crainte des conséquences.",
    "quran.90_1_translation": "Non!... Je jure par cette Cité!",
    "quran.90_2_translation": "et toi, tu es un résident dans cette cité -",
    "quran.90_3_translation": "Et par le père et ce qu'il engendre!",
    "quran.90_4_translation": "Nous avons, certes, créé l'homme pour une vie de lutte.",
    "quran.90_5_translation": "Pense-t-il que personne ne pourra rien contre lui?",
    "quran.90_6_translation": "Il dit: «J'ai gaspillé beaucoup de biens».",
    "quran.90_7_translation": "Pense-t-il que nul ne l'a vu?",
    "quran.90_8_translation": "Ne lui avons Nous pas assigné deux yeux,",
    "quran.90_9_translation": "et une langue et deux lèvres?",
    "quran.90_10_translation": "Ne l'avons-Nous pas guidé aux deux voies.",
    "quran.90_11_translation": "Or, il ne s'engage pas dans la voie difficile!",
    "quran.90_12_translation": "Et qui te dira ce qu'est la voie difficile?",
    "quran.90_13_translation": "C'est délier un joug [affranchir un esclave],",
    "quran.90_14_translation": "ou nourrir, en un jour de famine,",
    "quran.90_15_translation": "un orphelin proche parent",
    "quran.90_16_translation": "ou un pauvre dans le dénuement.",
    "quran.90_17_translation": "Et c'est être, en outre, de ceux qui croient et s'enjoignent mutuellement l'endurance, et s'enjoignent mutuellement la miséricorde.",
    "quran.90_18_translation": "Ceux-là sont les gens de la droite;",
    "quran.90_19_translation": "alors que ceux qui ne croient pas en Nos versets sont les gens de la gauche.",
    "quran.90_20_translation": "Le Feu se refermera sur eux.",
    "quran.89_1_translation": "Par l'Aube!",
    "quran.89_2_translation": "Et par les dix nuits!",
    "quran.89_3_translation": "Par le pair et l'impair!",
    "quran.89_4_translation": "Et par la nuit quand elle s'écoule!",
    "quran.89_5_translation": "N'est-ce pas là un serment, pour un doué d'intelligence?",
    "quran.89_6_translation": "N'as-tu pas vu comment ton Seigneur a agi avec les 'Aad",
    "quran.89_7_translation": "[avec] Iram, [la cité] à la colonne remarquable,",
    "quran.89_8_translation": "dont jamais pareille ne fut construite parmi les villes?",
    "quran.89_9_translation": "et avec les Thamûd qui taillaient le rocher dans la vallée?",
    "quran.89_10_translation": "ainsi qu'avec Pharaon, l'homme aux épieux?",
    "quran.89_11_translation": "Tous, étaient des gens qui transgressaient dans [leurs] pays,",
    "quran.89_12_translation": "et y avaient commis beaucoup de désordre.",
    "quran.89_13_translation": "Donc, ton Seigneur déversa sur eux un fouet du châtiment.",
    "quran.89_14_translation": "Car ton Seigneur demeure aux aguets.",
    "quran.89_15_translation": "Quant à l'homme, lorsque son Seigneur l'éprouve en l'honorant et en le comblant de bienfaits, il dit: «Mon Seigneur m'a honoré».",
    "quran.89_16_translation": "Mais par contre, quand Il l'éprouve en lui restreignant sa subsistance, il dit: «Mon Seigneur m'a avili».",
    "quran.89_17_translation": "Mais non! C'est vous plutôt, qui n'êtes pas généreux envers les orphelins;",
    "quran.89_18_translation": "qui ne vous incitez pas mutuellement à nourrir le pauvre,",
    "quran.89_19_translation": "qui dévorez l'héritage avec une avidité vorace,",
    "quran.89_20_translation": "et aimez les richesses d'un amour sans bornes.",
    "quran.89_21_translation": "Prenez garde! Quand la terre sera complètement pulvérisée,",
    "quran.89_22_translation": "et que ton Seigneur viendra ainsi que les Anges, rang par rang,",
    "quran.89_23_translation": "et que ce jour-là, on amènera l'Enfer; ce jour-là, l'homme se rappellera. Mais à quoi lui servira de se souvenir?",
    "quran.89_24_translation": "Il dira: «Hélas! Que n'ai-je fait du bien pour ma vie future!",
    "quran.89_25_translation": "Ce jour-là donc, nul ne saura châtier comme Lui châtie,",
    "quran.89_26_translation": "et nul ne saura garrotter comme Lui garrotte.",
    "quran.89_27_translation": "«O toi, âme apaisée,",
    "quran.89_28_translation": "retourne vers ton Seigneur, satisfaite et agréée;",
    "quran.89_29_translation": "entre donc parmi Mes serviteurs,",
    "quran.89_30_translation": "et entre dans Mon Paradis».",
    "quran.88_1_translation": "T'est-il parvenu le récit de l'enveloppante?",
    "quran.88_2_translation": "Ce jour-là, il y aura des visages humiliés,",
    "quran.88_3_translation": "préoccupés, harassés.",
    "quran.88_4_translation": "Ils brûleront dans un Feu ardent,",
    "quran.88_5_translation": "et seront abreuvés d'une source bouillante.",
    "quran.88_6_translation": "Il n'y aura pour eux d'autre nourriture que des plantes épineuses [darî'],",
    "quran.88_7_translation": "qui n'engraisse, ni n'apaise la faim.",
    "quran.88_8_translation": "Ce jour-là, il y aura des visages épanouis,",
    "quran.88_9_translation": "contents de leurs efforts,",
    "quran.88_10_translation": "dans un haut Jardin,",
    "quran.88_11_translation": "où ils n'entendent aucune futilité.",
    "quran.88_12_translation": "Là, il y aura une source coulante.",
    "quran.88_13_translation": "Là, des divans élevés",
    "quran.88_14_translation": "et des coupes posées",
    "quran.88_15_translation": "et des coussins rangés",
    "quran.88_16_translation": "et des tapis étalés.",
    "quran.88_17_translation": "Ne considèrent-ils donc pas les chameaux, comment ils ont été créés,",
    "quran.88_18_translation": "et le ciel comment il est élevé,",
    "quran.88_19_translation": "et les montagnes comment elles sont dressées",
    "quran.88_20_translation": "et la terre comment elle est nivelée?",
    "quran.88_21_translation": "Eh bien, rappelle! Tu n'es qu'un rappeleur,",
    "quran.88_22_translation": "et tu n'es pas un dominateur sur eux.",
    "quran.88_23_translation": "Sauf celui qui tourne le dos et ne croit pas,",
    "quran.88_24_translation": "alors Allah le châtiera du plus grand châtiment.",
    "quran.88_25_translation": "Vers Nous est leur retour.",
    "quran.88_26_translation": "Ensuite, c'est à Nous de leur demander compte.",
    "quran.87_1_translation": "Glorifie le nom de ton Seigneur, le Très Haut,",
    "quran.87_2_translation": "Celui Qui a créé et agencé harmonieusement,",
    "quran.87_3_translation": "qui a décrété et guidé,",
    "quran.87_4_translation": "et qui a fait pousser le pâturage,",
    "quran.87_5_translation": "et en a fait ensuite un foin sombre.",
    "quran.87_6_translation": "Nous te ferons réciter (le Coran), de sorte que tu n'oublieras",
    "quran.87_7_translation": "que ce qu'Allah veut. Car, Il connaît ce qui paraît au grand jour ainsi que ce qui est caché.",
    "quran.87_8_translation": "Nous te mettrons sur la voie la plus facile.",
    "quran.87_9_translation": "Rappelle, donc, où le Rappel doit être utile.",
    "quran.87_10_translation": "Quiconque craint (Allah) s'[en] rappellera,",
    "quran.87_11_translation": "et s'en écartera le grand malheureux,",
    "quran.87_12_translation": "qui brûlera dans le plus grand Feu,",
    "quran.87_13_translation": "où il ne mourra ni ne vivra.",
    "quran.87_14_translation": "Réussit, certes, celui qui se purifie,",
    "quran.87_15_translation": "et se rappelle le nom de son Seigneur, puis célèbre la Salât.",
    "quran.87_16_translation": "Mais, vous préférez plutôt la vie présente,",
    "quran.87_17_translation": "alors que l'au-delà est meilleur et plus durable.",
    "quran.87_18_translation": "Ceci se trouve, certes, dans les Feuilles anciennes,",
    "quran.87_19_translation": "les Feuilles d'Abraham et de Moïse.",
    "quran.86_1_translation": "Par le ciel et par l'astre nocturne",
    "quran.86_2_translation": "Et qui te dira ce qu'est l'astre nocturne?",
    "quran.86_3_translation": "C'est l'étoile vivement brillante.",
    "quran.86_4_translation": "Il n'est pas d'âme qui n'ait sur elle un gardien.",
    "quran.86_5_translation": "Que l'homme considère donc de quoi il a été créé.",
    "quran.86_6_translation": "Il a été créé d'une giclée d'eau",
    "quran.86_7_translation": "sortie d'entre les lombes et les côtes.",
    "quran.86_8_translation": "Allah est certes capable de le ressusciter.",
    "quran.86_9_translation": "Le jour où les cœurs dévoileront leurs secrets,",
    "quran.86_10_translation": "Il n'aura alors ni force ni secoureur.",
    "quran.86_11_translation": "Par le ciel qui fait revenir la pluie!",
    "quran.86_12_translation": "et par la terre qui se fend!",
    "quran.86_13_translation": "Ceci [le Coran] est certes, une parole décisive [qui tranche entre le vrai et le faux],",
    "quran.86_14_translation": "et non point une plaisanterie frivole!",
    "quran.86_15_translation": "Ils se servent d'une ruse,",
    "quran.86_16_translation": "et Moi aussi Je me sers de Mon plan.",
    "quran.86_17_translation": "Accorde (ô Prophète) donc un délai aux infidèles: accorde-leur un court délai.",
    "quran.85_1_translation": "Par le ciel aux constellations!",
    "quran.85_2_translation": "et par le jour promis!",
    "quran.85_3_translation": "et par le témoin et ce dont on témoigne!",
    "quran.85_4_translation": "Périssent les gens de l'Uhdûd,",
    "quran.85_5_translation": "par le feu plein de combustible,",
    "quran.85_6_translation": "cependant qu'ils étaient assis tout autour,",
    "quran.85_7_translation": "ils étaient ainsi témoins de ce qu'ils faisaient des croyants,",
    "quran.85_8_translation": "à qui ils ne leur reprochaient que d'avoir cru en Allah, le Puissant, le Digne de louange,",
    "quran.85_9_translation": "Auquel appartient la royauté des cieux et de la terre. Allah est témoin de toute chose.",
    "quran.85_10_translation": "Ceux qui font subir des épreuves aux croyants et aux croyantes, puis ne se repentent pas, auront le châtiment de l'Enfer et le supplice du feu.",
    "quran.85_11_translation": "Ceux qui croient et accomplissent les bonnes œuvres auront des Jardins sous lesquels coulent les ruisseaux. Cela est le grand succès.",
    "quran.85_12_translation": "La riposte de ton Seigneur est redoutable.",
    "quran.85_13_translation": "C'est Lui, certes, qui commence (la création) et la refait.",
    "quran.85_14_translation": "Et c'est Lui le Pardonneur, le Tout-Affectueux,",
    "quran.85_15_translation": "Le Maître du Trône, le Tout-Glorieux,",
    "quran.85_16_translation": "Il réalise parfaitement tout ce qu'Il veut.",
    "quran.85_17_translation": "T'est-il parvenu le récit des armées,",
    "quran.85_18_translation": "de Pharaon, et de Thamûd?",
    "quran.85_19_translation": "Mais ceux qui ne croient pas persistent à démentir,",
    "quran.85_20_translation": "alors qu'Allah, derrière eux, les cerne de toutes parts.",
    "quran.85_21_translation": "Mais c'est plutôt un Coran glorifié",
    "quran.85_22_translation": "préservé sur une Tablette (auprès d'Allah).",
    "quran.84_1_translation": "Quand le ciel se déchirera",
    "quran.84_2_translation": "et obéira à son Seigneur - et fera ce qu'il doit faire -",
    "quran.84_3_translation": "et que la terre sera nivelée,",
    "quran.84_4_translation": "et qu'elle rejettera ce qui est en son sein (les morts) et se videra,",
    "quran.84_5_translation": "et qu'elle obéira à son Seigneur - et fera ce qu'elle doit faire -",
    "quran.84_6_translation": "O homme! Toi qui t'efforces vers ton Seigneur sans relâche, tu Le rencontreras alors.",
    "quran.84_7_translation": "Celui qui recevra son livre en sa main droite,",
    "quran.84_8_translation": "sera soumis à un jugement facile,",
    "quran.84_9_translation": "et retournera réjoui auprès de sa famille",
    "quran.84_10_translation": "Quant à celui qui recevra son livre derrière son dos,",
    "quran.84_11_translation": "il invoquera la destruction sur lui-même,",
    "quran.84_12_translation": "et il brûlera dans un feu ardent.",
    "quran.84_13_translation": "Car il était tout joyeux parmi les siens,",
    "quran.84_14_translation": "et il pensait que jamais il ne ressusciterait",
    "quran.84_15_translation": "Mais si! Certes, son Seigneur l'observait parfaitement.",
    "quran.84_16_translation": "Non!... Je jure par le crépuscule,",
    "quran.84_17_translation": "et par la nuit et ce qu'elle enveloppe,",
    "quran.84_18_translation": "et par la lune quand elle devient pleine lune!",
    "quran.84_19_translation": "Vous passerez, certes, par des états successifs!",
    "quran.84_20_translation": "Qu'ont-ils à ne pas croire?",
    "quran.84_21_translation": "et à ne pas se prosterner quand le Coran leur est lu?",
    "quran.84_22_translation": "Mais ceux qui ne croient pas, le traitent plutôt de mensonge.",
    "quran.84_23_translation": "Or, Allah sait bien ce qu'ils dissimulent.",
    "quran.84_24_translation": "Annonce-leur donc un châtiment douloureux.",
    "quran.84_25_translation": "Sauf ceux qui croient et accomplissent les bonnes œuvres: à eux une récompense jamais interrompue.",
    "quran.83_1_translation": "Malheur aux fraudeurs",
    "quran.83_2_translation": "qui, lorsqu'ils font mesurer pour eux-mêmes exigent la pleine mesure,",
    "quran.83_3_translation": "et qui lorsqu'eux-mêmes mesurent ou pèsent pour les autres, [leur] causent perte.",
    "quran.83_4_translation": "Ceux-là ne pensent-ils pas qu'ils seront ressuscités,",
    "quran.83_5_translation": "en un jour terrible,",
    "quran.83_6_translation": "le jour où les gens se tiendront debout devant le Seigneur de l'Univers?",
    "quran.83_7_translation": "Non...! Mais en vérité le livre des libertins sera dans le Sijjîn -",
    "quran.83_8_translation": "et qui te dira ce qu'est le Sijjîn? -",
    "quran.83_9_translation": "Un livre déjà cacheté (achevé).",
    "quran.83_10_translation": "Malheur, ce jour-là, aux négateurs,",
    "quran.83_11_translation": "qui démentent le jour de la Rétribution.",
    "quran.83_12_translation": "Or, ne le dément que tout transgresseur, pécheur:",
    "quran.83_13_translation": "qui, lorsque Nos versets lui sont récités, dit: «[Ce sont] des contes d'anciens!»",
    "quran.83_14_translation": "Pas du tout, mais ce qu'ils ont accompli couvre leurs cœurs.",
    "quran.83_15_translation": "Qu'ils prennent garde! En vérité ce jour-là un voile les empêchera de voir leur Seigneur,",
    "quran.83_16_translation": "ensuite, ils brûleront certes, dans la Fournaise;",
    "quran.83_17_translation": "on [leur] dira alors: «Voilà ce que vous traitiez de mensonge!»",
    "quran.83_18_translation": "Qu'ils prennent garde! Le livre des bons sera dans l'Illiyûn -",
    "quran.83_19_translation": "et qui te dira ce qu'est l'Illiyûn? -",
    "quran.83_20_translation": "un livre cacheté!",
    "quran.83_21_translation": "Les rapprochés [d'Allah: les Anges] en témoignent.",
    "quran.83_22_translation": "Les bons seront dans [un Jardin] de délice,",
    "quran.83_23_translation": "sur les divans, ils regardent.",
    "quran.83_24_translation": "Tu reconnaîtras sur leurs visages, l'éclat de la félicité.",
    "quran.83_25_translation": "On leur sert à boire un nectar pur, cacheté,",
    "quran.83_26_translation": "laissant un arrière-goût de musc. Que ceux qui la convoitent entrent en compétition [pour l'acquérir]",
    "quran.83_27_translation": "Il est mélangé à la boisson de Tasnîm,",
    "quran.83_28_translation": "source dont les rapprochés boivent.",
    "quran.83_29_translation": "Les criminels riaient de ceux qui croyaient,",
    "quran.83_30_translation": "et, passant près d'eux, ils se faisaient des œillades,",
    "quran.83_31_translation": "et, retournant dans leurs familles, ils retournaient en plaisantant,",
    "quran.83_32_translation": "et les voyant, ils disaient: «Ce sont vraiment ceux-là les égarés».",
    "quran.83_33_translation": "Or, ils n'ont pas été envoyés pour être leurs gardiens.",
    "quran.83_34_translation": "Aujourd'hui, donc, ce sont ceux qui ont cru qui rient des infidèles",
    "quran.83_35_translation": "sur les divans, ils regardent.",
    "quran.83_36_translation": "Est-ce que les infidèles ont eu la récompense de ce qu'ils faisaient?",
    "quran.82_1_translation": "Quand le ciel se rompra,",
    "quran.82_2_translation": "et que les étoiles se disperseront,",
    "quran.82_3_translation": "et que les mers confondront leurs eaux,",
    "quran.82_4_translation": "et que les tombeaux seront bouleversés,",
    "quran.82_5_translation": "toute âme saura alors ce qu'elle a accompli et ce qu'elle a remis de faire à plus tard.",
    "quran.82_6_translation": "O homme! Qu'est-ce qui t'a trompé au sujet de ton Seigneur, le Noble,",
    "quran.82_7_translation": "qui t'a créé, puis modelé et constitué harmonieusement?",
    "quran.82_8_translation": "Il t'a façonné dans la forme qu'Il a voulue.",
    "quran.82_9_translation": "Non...! [malgré tout] vous traitez la Rétribution de mensonge;",
    "quran.82_10_translation": "alors que veillent sur vous des gardiens,",
    "quran.82_11_translation": "de nobles scribes,",
    "quran.82_12_translation": "qui savent ce que vous faites.",
    "quran.82_13_translation": "Les bons seront, certes, dans un [jardin] de délice,",
    "quran.82_14_translation": "et les libertins seront, certes, dans une fournaise",
    "quran.82_15_translation": "où ils brûleront, le jour de la Rétribution",
    "quran.82_16_translation": "incapables de s'en échapper.",
    "quran.82_17_translation": "Et qui te dira ce qu'est le jour de la Rétribution?",
    "quran.82_18_translation": "Encore une fois, qui te dira ce qu'est le jour de la Rétribution?",
    "quran.82_19_translation": "Le jour où aucune âme ne pourra rien en faveur d'une autre âme. Et ce jour-là, le commandement sera à Allah.",
    "quran.81_1_translation": "Quand le soleil sera obscurci,",
    "quran.81_2_translation": "et que les étoiles deviendront ternes,",
    "quran.81_3_translation": "et les montagnes mises en marche,",
    "quran.81_4_translation": "et les chamelles à terme, négligées,",
    "quran.81_5_translation": "et les bêtes farouches, rassemblées,",
    "quran.81_6_translation": "et les mers allumées,",
    "quran.81_7_translation": "et les âmes accouplées",
    "quran.81_8_translation": "et qu'on demandera à la fillette enterrée vivante",
    "quran.81_9_translation": "pour quel péché elle a été tuée.",
    "quran.81_10_translation": "Et quand les feuilles seront déployées,",
    "quran.81_11_translation": "et le ciel écorché",
    "quran.81_12_translation": "et la fournaise attisée,",
    "quran.81_13_translation": "et le Paradis rapproché,",
    "quran.81_14_translation": "chaque âme saura ce qu'elle a présenté.",
    "quran.81_15_translation": "Non!... Je jure par les planètes qui gravitent",
    "quran.81_16_translation": "qui courent et disparaissent",
    "quran.81_17_translation": "par la nuit quand elle survient!",
    "quran.81_18_translation": "et par l'aube quand elle exhale son souffle!",
    "quran.81_19_translation": "Ceci [le Coran] est la parole d'un noble Messager,",
    "quran.81_20_translation": "doué d'une grande force, et ayant un rang élevé auprès du Maître du Trône,",
    "quran.81_21_translation": "obéi, là-haut, et digne de confiance.",
    "quran.81_22_translation": "Votre compagnon (Muhammad) n'est nullement fou;",
    "quran.81_23_translation": "il l'a effectivement vu (Gabriel), au clair horizon",
    "quran.81_24_translation": "et il ne garde pas avarement pour lui-même ce qui lui a été révélé.",
    "quran.81_25_translation": "Et ceci [le Coran] n'est point la parole d'un diable banni.",
    "quran.81_26_translation": "Où allez-vous donc?",
    "quran.81_27_translation": "Ceci n'est qu'un rappel pour l'univers,",
    "quran.81_28_translation": "pour celui d'entre vous qui veut suivre le chemin droit.",
    "quran.81_29_translation": "Mais vous ne pouvez vouloir, que si Allah veut, [Lui], le Seigneur de l'Univers ;",
    "quran.79_1_translation": "Par ceux qui arrachent violemment!",
    "quran.79_2_translation": "Et par ceux qui recueillent avec douceur!",
    "quran.79_3_translation": "Et par ceux qui voguent librement,",
    "quran.79_4_translation": "puis s'élancent à toute vitesse,",
    "quran.79_5_translation": "et règlent les affaires!",
    "quran.79_6_translation": "Le jour où [la terre] tremblera [au premier son du clairon]",
    "quran.79_7_translation": "immédiatement suivi du deuxième.",
    "quran.79_8_translation": "Ce jour-là, il y aura des cœurs qui seront agités d'effroi,",
    "quran.79_9_translation": "et leurs regards se baisseront.",
    "quran.79_10_translation": "Ils disent: «Quoi! Serons-nous ramenés à notre vie première,",
    "quran.79_11_translation": "quand nous serons ossements pourris?»",
    "quran.79_12_translation": "Ils disent: «ce sera alors un retour ruineux!»",
    "quran.79_13_translation": "Il n'y aura qu'une sommation,",
    "quran.79_14_translation": "et voilà qu'ils seront sur la terre (ressuscités).",
    "quran.79_15_translation": "Le récit de Moïse t'est-il parvenu?",
    "quran.79_16_translation": "Quand son Seigneur l'appela, dans Towâ, la vallée sanctifiée:",
    "quran.79_17_translation": "«Va vers Pharaon. Vraiment, il s'est rebellé!»",
    "quran.79_18_translation": "Puis dis-lui: «Voudrais-tu te purifier?",
    "quran.79_19_translation": "et que je te guide vers ton Seigneur afin que tu Le craignes?»",
    "quran.79_20_translation": "Il lui fit voir le très grand miracle.",
    "quran.79_21_translation": "Mais il le qualifia de mensonge et désobéit;",
    "quran.79_22_translation": "Ensuite, il tourna le dos, s'en alla précipitamment,",
    "quran.79_23_translation": "rassembla [les gens] et leur fit une proclamation,",
    "quran.79_24_translation": "et dit: «C'est moi votre Seigneur, le très haut».",
    "quran.79_25_translation": "Alors Allah le saisit de la punition exemplaire de l'au-delà et de celle d'ici-bas.",
    "quran.79_26_translation": "Il y a certes là un sujet de réflexion pour celui qui craint.",
    "quran.79_27_translation": "Etes-vous plus durs à créer? ou le ciel, qu'Il a pourtant construit?",
    "quran.79_28_translation": "Il a élevé bien haut sa voûte, puis l'a parfaitement ordonné;",
    "quran.79_29_translation": "Il a assombri sa nuit et fait luire son jour.",
    "quran.79_30_translation": "Et quant à la terre, après cela, Il l'a étendue:",
    "quran.79_31_translation": "Il a fait sortir d'elle son eau et son pâturage,",
    "quran.79_32_translation": "et quant aux montagnes, Il les a ancrées,",
    "quran.79_33_translation": "pour votre jouissance, vous et vos bestiaux.",
    "quran.79_34_translation": "Puis quand viendra le grand cataclysme,",
    "quran.79_35_translation": "le jour où l'homme se rappellera à quoi il s'est efforcé,",
    "quran.79_36_translation": "l'Enfer sera pleinement visible à celui qui regardera...",
    "quran.79_37_translation": "Quant à celui qui aura dépassé les limites",
    "quran.79_38_translation": "et aura préféré la vie présente,",
    "quran.79_39_translation": "alors, l'Enfer sera son refuge...",
    "quran.79_40_translation": "Et pour celui qui aura redouté de comparaître devant son Seigneur, et préservé son âme de la passion,",
    "quran.79_41_translation": "le Paradis sera alors son refuge.",
    "quran.79_42_translation": "Ils t'interrogent au sujet de l'Heure: «Quand va-t-elle jeter l'ancre?»",
    "quran.79_43_translation": "Quelle [science] en as-tu pour le leur dire?",
    "quran.79_44_translation": "Son terme n'est connu que de ton Seigneur.",
    "quran.79_45_translation": "Tu n'es que l'avertisseur de celui qui la redoute.",
    "quran.79_46_translation": "Le jour où ils la verront, il leur semblera n'avoir demeuré qu'un soir ou un matin.",
    "quran.78_1_translation": "Sur quoi s'interrogent-ils mutuellement?",
    "quran.78_2_translation": "Sur la grande nouvelle,",
    "quran.78_3_translation": "à propos de laquelle ils divergent.",
    "quran.78_4_translation": "Eh bien non! Ils sauront bientôt.",
    "quran.78_5_translation": "Encore une fois, non! Ils sauront bientôt.",
    "quran.78_6_translation": "N'avons-Nous pas fait de la terre une couche?",
    "quran.78_7_translation": "et (placé) les montagnes comme des piquets?",
    "quran.78_8_translation": "Nous vous avons créés en couples,",
    "quran.78_9_translation": "et désigné votre sommeil pour votre repos,",
    "quran.78_10_translation": "et fait de la nuit un vêtement,",
    "quran.78_11_translation": "et assigné le jour pour les affaires de la vie,",
    "quran.78_12_translation": "et construit au-dessus de vous sept (cieux) renforcés,",
    "quran.78_13_translation": "et [y] avons placé une lampe (le soleil) très ardente,",
    "quran.78_14_translation": "et fait descendre des nuées une eau abondante",
    "quran.78_15_translation": "pour faire pousser par elle grains et plantes",
    "quran.78_16_translation": "et jardins luxuriants.",
    "quran.78_17_translation": "Le Jour de la Décision [du Jugement] a son terme fixé.",
    "quran.78_18_translation": "Le jour où l'on soufflera dans la Trompe, vous viendrez par troupes,",
    "quran.78_19_translation": "et le ciel sera ouvert et [présentera] des portes,",
    "quran.78_20_translation": "et les montagnes seront mises en marche et deviendront un mirage.",
    "quran.78_21_translation": "L'Enfer demeure aux aguets,",
    "quran.78_22_translation": "refuge pour les transgresseurs.",
    "quran.78_23_translation": "Ils y demeureront pendant des siècles successifs.",
    "quran.78_24_translation": "Ils n'y goûteront ni fraîcheur ni breuvage,",
    "quran.78_25_translation": "Hormis une eau bouillante et un pus",
    "quran.78_26_translation": "comme rétribution équitable.",
    "quran.78_27_translation": "Car ils ne s'attendaient pas à rendre compte,",
    "quran.78_28_translation": "et traitaient de mensonges, continuellement, Nos versets,",
    "quran.78_29_translation": "alors que Nous avons dénombré toutes choses en écrit.",
    "quran.78_30_translation": "Goûtez-donc. Nous n'augmenterons pour vous que le châtiment!",
    "quran.78_31_translation": "Pour les pieux ce sera une réussite:",
    "quran.78_32_translation": "jardins et vignes,",
    "quran.78_33_translation": "et des (belles) aux seins arrondis, d'une égale jeunesse,",
    "quran.78_34_translation": "et coupes débordantes.",
    "quran.78_35_translation": "Ils n'y entendront ni futilités ni mensonges.",
    "quran.78_36_translation": "A titre de récompense de ton Seigneur et à titre de don abondant",
    "quran.78_37_translation": "du Seigneur des cieux et de la terre et de ce qui existe entre eux, le Tout Miséricordieux; ils n'osent nullement Lui adresser la parole.",
    "quran.78_38_translation": "Le jour où l'Esprit et les Anges se dresseront en rangs, nul ne saura parler, sauf celui à qui le Tout Miséricordieux aura accordé la permission, et qui dira la vérité.",
    "quran.78_39_translation": "Ce jour-là est inéluctable. Que celui qui veut prenne donc refuge auprès de son Seigneur.",
    "quran.78_40_translation": "Nous vous avons avertis d'un châtiment bien proche, le jour où l'homme verra ce que ses deux mains ont préparé; et l'infidèle dira: «Hélas pour moi! Comme j'aurais aimé n'être que poussière»."
  },
  "ha": {
    "quran.114_1_translation": "Ka ce \"Ina nẽman tsari ga Ubangijin mutãne.\"",
    "quran.114_2_translation": "\"Mamallakin mutane.\"",
    "quran.114_3_translation": "\"Abin bautãwar mutãne.\"",
    "quran.114_4_translation": "\"Daga sharrin mai sanya wasuwãsi, mai ɓoyewa.\"",
    "quran.114_5_translation": "\"Wanda ke sanya wasuwãsi a cikin ƙirãzan mutane.\"",
    "quran.114_6_translation": "\"Daga aljannu da mutane.\"",
    "quran.113_1_translation": "Ka ce \"ina neman tsari ga Ubangijin safiya\"",
    "quran.113_2_translation": "\"Daga sharrin abin da Ya halitta.\"",
    "quran.113_3_translation": "\"Da sharrin dare, idan ya yi duhu.\"",
    "quran.113_4_translation": "\"Da sharrin mãtã mãsu tõfi a cikin ƙulle-ƙulle.\"",
    "quran.113_5_translation": "\"Da sharrin mai hãsada idan ya yi hasada.\"",
    "quran.112_1_translation": "Ka ce: \"Shi ne Allah Makaɗaĩci.\"",
    "quran.112_2_translation": "\"Allah wanda ake nufin Sa da buƙata.\"",
    "quran.112_3_translation": "\"Bai haifa ba, kuma ba a haife Shi ba.\"",
    "quran.112_4_translation": "\"Kuma babu ɗaya da ya kasance tamka a gare Shi.\"",
    "quran.111_1_translation": "Hannãye biyu na Abũlahabi sun halaka, kuma ya halaka.",
    "quran.111_2_translation": "Dũkiyarsa ba ta tsare masa kõme ba, da abin da ya tãra.",
    "quran.111_3_translation": "Zã ya shiga wuta mai hũruwa.",
    "quran.111_4_translation": "Tãre da matarsa mai ɗaukar itacen (wuta).",
    "quran.111_5_translation": "A cikin kyakkyãwan wuyanta akwai igiya ta kaba (Rãnar ¡iyãma).",
    "quran.110_1_translation": "Idan taimakon Allah ya zo da cin nasara.",
    "quran.110_2_translation": "Kuma ka ga mutane suna shiga addinin Allah, ƙungiya-ƙungiya.",
    "quran.110_3_translation": "To, ka yi tasbihi game da gõde wa Ubangijinka, kuma ka nẽme Shi gafara, lalle Shi (Ubangijinka) Ya kasance Mai karɓar tũba ne.",
    "quran.109_1_translation": "Ka ce: \"Ya kũ kãfirai!\"",
    "quran.109_2_translation": "\"Bã zan bautã wa abin da kuke bautã wa ba.\"",
    "quran.109_3_translation": "\"Kuma kũ, ba ku zama masu bauta wa abin da nake bautã wa ba.\"",
    "quran.109_4_translation": "\"Kuma nĩ ban zama mai bautã wa abin da kuka bautã wa ba.\"",
    "quran.109_5_translation": "\"Kuma kũ, ba ku zama mãsu bautã wa abin da nake bautã wa ba.\"",
    "quran.109_6_translation": "\"Addininku na garẽ ku, kuma addinina yanã gare ni.\"",
    "quran.108_1_translation": "Lalle ne Mu, Mun yi maka kyauta mai yawa.",
    "quran.108_2_translation": "Saboda haka, ka yi salla dõmin Ubangijinka, kuma ka sõke (baiko, wato sukar raƙumi).",
    "quran.108_3_translation": "Lalle mai aibanta ka shi ne mai yankakkiyar albarka.",
    "quran.107_1_translation": "Shin, ka ga wanda ke ƙaryatãwa game da sakamako?",
    "quran.107_2_translation": "To, wannan shi ne ke tunkue marãya (daga haƙƙinsa).",
    "quran.107_3_translation": "Kuma bã ya kwaaitarwa bisa bãyar da abinci ga matalauci.",
    "quran.107_4_translation": "To, bone yã tabbata ga masallata.",
    "quran.107_5_translation": "Waɗanda suke masu shagala daga sallarsu.",
    "quran.107_6_translation": "Waɗanda suke yin riya (ga ayyukansu)",
    "quran.107_7_translation": "Kuma suna hana taimako.",
    "quran.106_1_translation": "Sabõda sãbon ¡uraishawa.",
    "quran.106_2_translation": "Sãbonsu na tafiyar hunturu da ta bazara.",
    "quran.106_3_translation": "Sabõda haka sai su bauta wa Ubangijin wannan Gida (Ka'abah).",
    "quran.106_4_translation": "wanda Ya ciyar da su (Ya hana su) daga yunwa, kuma Ya amintar da su daga wani tsõro.",
    "quran.105_1_translation": "Ashe, ba ka ga yadda Ubangijinka Ya aikata ga mutanen giwa ba?",
    "quran.105_2_translation": "Ashe, bai sanya kaidinsu a cikin ɓata ba?",
    "quran.105_3_translation": "Kuma Ya sako, a kansu, wasu tsuntsãye, jama'a-jama'a.",
    "quran.105_4_translation": "Suna jifar su da wasu duwatsu na yumɓun wuta.",
    "quran.105_5_translation": "Sa'an nan Ya sanya su kamar karmami wanda aka cinye?",
    "quran.104_1_translation": "Bone ya tabbata ga duk mai nune, mai zunɗe (mai raɗa).",
    "quran.104_2_translation": "Wanda ya tara dũkiya, kuma ya mayar da ita abar tattalinsa.",
    "quran.104_3_translation": "Yana zaton cẽwa dũkiyarsa za ta dawwamar da shi.",
    "quran.104_4_translation": "A'aha! Lalle ne zã a jẽfa shi a cikin Huɗama.",
    "quran.104_5_translation": "Kuma me ya sanar da kai abin da ake ce wa Huɗama?",
    "quran.104_6_translation": "Wutar Allah ce wadda ake hurawa.",
    "quran.104_7_translation": "Wadda take lẽƙãwa a kan zukata.",
    "quran.104_8_translation": "Lalle ne ita abar kullẽwa cea kansu.",
    "quran.104_9_translation": "A cikin wasu ginshiƙai mĩƙaƙƙu.",
    "quran.103_1_translation": "Ina rantsuwa da zãmani.",
    "quran.103_2_translation": "Lalle ne mutum yana a cikin hasara.",
    "quran.103_3_translation": "Fãce waɗanda suka yi ĩmani, kuma suka aikata ayyukan ƙwarai, kuma suka yi wa juna wasiyya da bin gaskiya, kuma suka yi wa juna wasiyya da yin haƙuri (su kam, basu cikin hasara).",
    "quran.102_1_translation": "Alfahari da yawan dũkiya da dangi ya shagaltar da ku (dagaibada mai amfaninku).",
    "quran.102_2_translation": "Har kuka ziyarci kaburbura.",
    "quran.102_3_translation": "A'aha! (Nan gaba) zã ku sani.",
    "quran.102_4_translation": "Sa'an nan, tabbas, zã ku sani.",
    "quran.102_5_translation": "Haƙĩƙa, da kuna da sani sani na yaƙĩni.",
    "quran.102_6_translation": "Lalle ne da kuna ganin Jahĩm.",
    "quran.102_7_translation": "Sa'an nan lalle ne za ku gan ta, da idanu, bayyane.",
    "quran.102_8_translation": "Sa'an nan lalle ne za a tambaye ku, a rãnar nan lãbãrin ni'imar (da aka yi muku).",
    "quran.101_1_translation": "Mai ƙwanƙwasar (zukata da tsõro)!",
    "quran.101_2_translation": "Mẽnẽ ne mai ƙwanƙwasa?",
    "quran.101_3_translation": "Kuma me ya sanar da kai abin da ake ce wa mai ƙwanƙwasa?",
    "quran.101_4_translation": "Rãnar da mutãne za su kasance kamar 'ya'yan fari mãsu wãtsuwa.",
    "quran.101_5_translation": "Kuma duwãtsu su kasance kamar gãshin sũfin da aka saɓe.",
    "quran.101_6_translation": "To, amma wanda ma'aunansa suka yi nauyi.",
    "quran.101_7_translation": "To, shi yana a cikin wata rayuwa yardadda.",
    "quran.101_8_translation": "Kuma amma wanda ma'aunansa suka yi sauƙi (bãbu nauyi).",
    "quran.101_9_translation": "To, uwarsa Hãwiya ce.",
    "quran.101_10_translation": "Kuma me ya sanar da kai mece ce ita?",
    "quran.101_11_translation": "Wata wuta ce mai zafi.",
    "quran.100_1_translation": "Ina rantsuwa da dawãki mãsu gudu suna fitar da kũkan ciki.",
    "quran.100_2_translation": "Mãsu ƙyasta wuta (da kõfatansu a kan duwatsu) ƙyastawa.",
    "quran.100_3_translation": "Sa'an nan mãsu yin hari a lokacin asuba.",
    "quran.100_4_translation": "Sai su motsar da ƙũra game da shi.",
    "quran.100_5_translation": "Sai su shiga, game da ita (ƙũrar), a tsakãnin jama'ar maƙiya.",
    "quran.100_6_translation": "Lalle ne mutum mai tsananin butulci ne ga Ubangijinsa.",
    "quran.100_7_translation": "Lalle ne shi mai shaida ne a kan laifinsa dl haka.",
    "quran.100_8_translation": "Kuma 1alle ne ga dũkiya shi mai tsananin so ne.",
    "quran.100_9_translation": "Shin, bã ya da sanin lõkacin da aka tõne abin da yake cikin kaburbura.",
    "quran.100_10_translation": "Aka bayyana abin da ke cikin zukata.",
    "quran.100_11_translation": "Lalle ne Ubangijinsu, game da su a ranar nan Mai ƙididdigewa ne?",
    "quran.99_1_translation": "Idan aka girgiza ƙasa, girgizawarta.",
    "quran.99_2_translation": "Kuma ƙasa ta fitar da kayanta, masu nauyi.",
    "quran.99_3_translation": "Kuma mutum ya ce \"Mẽ neya same ta?\"",
    "quran.99_4_translation": "A rãnar nan, zã ta faɗi lãbãrinta.",
    "quran.99_5_translation": "cewa Ubangijinka Ya yi umurni zuwa gare ta.",
    "quran.99_6_translation": "A rãnar nan mutane za su fito dabam-dabam domin a nuna musu ayyukansu.",
    "quran.99_7_translation": "To, wanda ya aikata (wani aiki) gwargwadon nauyin zarra, na alheri, zai gan shi.",
    "quran.99_8_translation": "Kuma wanda ya aikata gwargwadon nauyin zarra na sharri, zai gan shi.",
    "quran.98_1_translation": "Waɗanda suka kãfirta daga mũtanen Littafi, da mushirikai, ba su kasance masu gushewa daga gaskiya ba har hujja ta je musu.",
    "quran.98_2_translation": "Wani Manzo daga Allah, yana karatun wasu takardu masu tsarki.",
    "quran.98_3_translation": "A cikinsu akwai wasu littafai mãsu ƙĩma da daraja.",
    "quran.98_4_translation": "Kuma waɗanda aka bai wa Littafi ba su sãɓa wa juna ba face bayan hujjar ta je musu.",
    "quran.98_5_translation": "Kuma ba a umarce su da kome ba fãce bauta wa Allah suna mãsu tsarkake addinin gare Shi, mãsu karkata zuwa ga addinin gaskiya, kuma su tsai da salla kuma su bãyar da zakka, kuma wannan shi ne addinin waɗanda suke a kan hanyar ƙwarai.",
    "quran.98_6_translation": "Lalle ne waɗanda suka kafirta daga mutanen Littafi da mushirikai sana cikin wutar Jahannama suna madawwama a cikinta. Waɗannan su ne mafi ashararancin tãlikai.",
    "quran.98_7_translation": "Lalle ne waɗanda suka yi ĩmani, kuma suka aikata ayyukan ƙwarai, waɗannan su ne mafifita alherin halitta.",
    "quran.98_8_translation": "Sakamakonsu, a wurin Ubangijinsu, shi ne gidajen Aljannar zama, ƙoramu na gudãna daga ƙarƙashinsu sunã madawwama a cikinta har abada. Allah Ya yarda da su, kuma su, sun yarda da Shi. wannan sakamako ne ga wanda ya ji tsõron Ubangijinsa.",
    "quran.97_1_translation": "Lalle ne Mũ, Mun saukar da shi (Alƙur'ãni) a cikin Lailatul ƙadari (daren daraja)",
    "quran.97_2_translation": "To, me ya sanar da kai abin da ake cewa Lailatul ¡adari?",
    "quran.97_3_translation": "Lailatul ¡adari mafi alheri ne daga wasu watanni dubu.",
    "quran.97_4_translation": "Mala'iku da Rũhi suna sauka a cikinsa da iznin Ubangijinsu sabõda kowane umurni.",
    "quran.97_5_translation": "Sallama ne shi daren, har fitar alfijiri.",
    "quran.96_1_translation": "Ka yi karatu da sunan Ubangijinka, wanda Ya yi halitta.",
    "quran.96_2_translation": "Ya hahitta mutum daga gudan jini.",
    "quran.96_3_translation": "Ka yi karatu, kuma UbangiJinka shi ne Mafi karimci.",
    "quran.96_4_translation": "Wanda Ya sanar (da mutum) game da alƙalami.",
    "quran.96_5_translation": "Ya sanar da mutum abin da bai sani ba.",
    "quran.96_6_translation": "A'aha! Lalle, ne mutum haƙĩƙa, yana girman kai (ya ƙi karatu).",
    "quran.96_7_translation": "Dõmin yã ga kansa, yã wadãta.",
    "quran.96_8_translation": "Lalle ne zuwa ga Ubangijinka makoma take.",
    "quran.96_9_translation": "Shin, kã ga wanda ke hana.",
    "quran.96_10_translation": "Bãwã idan yã yi salla?",
    "quran.96_11_translation": "Ashe, kã gani, idan (shi bãwan) ya kasance a kan shiriya?",
    "quran.96_12_translation": "Ko ya yi umurni da taƙawa?",
    "quran.96_13_translation": "Ashe, kã gani, idan (shi mai hanin) ya ƙaryata, kuma ya jũya bãya?",
    "quran.96_14_translation": "Ashe, bai sani ba cewa Allah Yanã gani?",
    "quran.96_15_translation": "A'aha! Lalle ne, idan bai hanu ba, lalle ne zã Mu ja gãshin makwarkwaɗa.",
    "quran.96_16_translation": "Makwarkwaɗa maƙaryaciya, mai laifi.",
    "quran.96_17_translation": "Sai ya kirayi ƙungiyarsa.",
    "quran.96_18_translation": "Zã Mu kirayi zabaniyãwa (mala'iku mãsu girma).",
    "quran.96_19_translation": "A'aha kada ka bĩ shi. Kuma ka yi tawali'u, kuma ka nemi kusanta (zuwa ga Ubangijinka).",
    "quran.95_1_translation": "Inã rantsuwa da Attinu da Azzaitũn.",
    "quran.95_2_translation": "Da Dũr Sĩnĩna.",
    "quran.95_3_translation": "Da wannan gari amintacce.",
    "quran.95_4_translation": "Lalle ne, Mun halitta mutum a cikin mafi kyawon tsayuwa.",
    "quran.95_5_translation": "Sa'an nan, Muka mayar da shi mafi ƙasƙantar masu rauni",
    "quran.95_6_translation": "Face waɗanda suka yi imani, kuma suka aikata ayyukan ƙwarai, saboda haka suna da sakamako wanda bã ya yankewa.",
    "quran.95_7_translation": "To, bãyan haka mẽ ya sanya ka ka ƙaryata sakamako (wanda za a yi a bãyan Tãshin ¡iyãma)?",
    "quran.95_8_translation": "Ashe Allah bã Shi ne Mafi mãsu hukunci kyãwon hukunci ba?",
    "quran.93_1_translation": "Inã rantsuwa da hantsi.",
    "quran.93_2_translation": "Da dare a lõkacin da ya rufe (da duhunsa).",
    "quran.93_3_translation": "Ubangijinka bai yi maka bankwana ba, kuma bai ƙĩ kaba.",
    "quran.93_4_translation": "Kuma lalle ta ƙarshe ce mafi alheri a gare ka daga ta farko.",
    "quran.93_5_translation": "Kuma lalle ne, Ubangijinka zai yi ta bã ka kyauta sai ka yarda.",
    "quran.93_6_translation": "Ashe, bai sãme ka marãya ba, sa'an nan Ya yi maka makõma?",
    "quran.93_7_translation": "Kuma Ya sãme ka bã ka da shari'ã, sai Ya shiryar da kai?",
    "quran.93_8_translation": "Kuma Ya sãme ka matalauci, sai Ya wadãtã ka?",
    "quran.93_9_translation": "Sabõda haka, amma marãya, to, kada ka rinjãye shi.",
    "quran.93_10_translation": "Kuma amma mai tambaya, kada ka yi masa tsãwa.",
    "quran.93_11_translation": "Kuma amma ni'imar Ubangijinka, sai ka faɗa (dõmin gõdiya).",
    "quran.92_1_translation": "Inã rantsuwa da dare a lõkacin da yake rufẽwa.",
    "quran.92_2_translation": "Da yini a lõkacin da yake kuranyẽwa.",
    "quran.92_3_translation": "Da abin da ya halitta namiji da mace.",
    "quran.92_4_translation": "Lãlle ne ayyukanku, dabam-dabam suke.",
    "quran.92_5_translation": "To, amma wanda ya yi kyauta, kuma ya yi taƙawa.",
    "quran.92_6_translation": "Kuma ya gaskata kalma mai kyãwo.",
    "quran.92_7_translation": "To, zã Mu sauƙaƙe masa har ya kai ga sauƙi.",
    "quran.92_8_translation": "Kuma amma wanda ya yi rõwa, kuma ya wadãtu da kansa.",
    "quran.92_9_translation": "Kuma ya ƙaryatar da kalma mai kyãwo.",
    "quran.92_10_translation": "To, zã Mu sauƙaƙke masa har ya kai ga tsanani.",
    "quran.92_11_translation": "Kuma dũkiyarsa ba ta wadãtar masa da kõme ba, a lõkacin da ya gangara (a wuta).",
    "quran.92_12_translation": "Lãlle aikinMu ne, Mu bayyana shiriya.",
    "quran.92_13_translation": "Kuma lalle ne Lãhira da duniya Namu ne.",
    "quran.92_14_translation": "Sabõda haka, Na yi maku gargaɗi da wuta mai babbaka.",
    "quran.92_15_translation": "Bãbu mai shigarta sai mafi shaƙãwa.",
    "quran.92_16_translation": "Wanda ya ƙaryata, kuma ya jũya bãya.",
    "quran.92_17_translation": "Kuma mafi taƙawa zai nisance ta.",
    "quran.92_18_translation": "Wanda yake bãyar da dũkiyarsa, alhãli yana tsarkaka.",
    "quran.92_19_translation": "Alhãli bãbu wani mai wata ni'ima wurinsa wadda ake nẽman sakamakonta.",
    "quran.92_20_translation": "Fãce dai nẽman yardar Ubangijinsa Mafi ɗaukaka.",
    "quran.92_21_translation": "To, lalle ne zai yarda (da sakamakon da zã a bã shi).",
    "quran.91_1_translation": "Ina rantsuwa da rãnã da hantsinta.",
    "quran.91_2_translation": "Kuma da wata idan ya bi ta.",
    "quran.91_3_translation": "Da yini a lõkacin da ya bayyana ta.",
    "quran.91_4_translation": "Da dare a lõkacin da ya ke rufe ta.",
    "quran.91_5_translation": "Da sama da abin da ya gina ta.",
    "quran.91_6_translation": "Da ƙasã da abin da ya shimfiɗa ta.",
    "quran.91_7_translation": "Da rai da abin da ya daidaita shi.",
    "quran.91_8_translation": "Sa'an nan ya sanar da shi fãjircinsa da shiryuwarsa.",
    "quran.91_9_translation": "Lalle ne wanda ya tsarkake shi (rai) ya sãmi babban rabo.",
    "quran.91_10_translation": "Kuma lalle ne wanda ya turbuɗe shi (da laifi) ya tãɓe.",
    "quran.91_11_translation": "Samũdãwa sun ƙaryata (Annabinsu), dõmin girman kansu.",
    "quran.91_12_translation": "A lõkacin da mafi shaƙãwarsu ya tafi (wurin sõke rãkumar sãlihu).",
    "quran.91_13_translation": "Sai Manzon Allah ya gaya musu cewa: \"Ina tsõratar da ku ga rãƙumar Allah da ruwan shanta!\"",
    "quran.91_14_translation": "Sai suka ƙaryata shi, sa'an nan suka sõke ta. Sabõda haka Ubangijinsu Ya darkãke su, sabõda zunubinsu. Sa'an nan Ya daidaita ta (azãbar ga mai laifi da maras laifi).",
    "quran.91_15_translation": "Kuma bã ya tsõron ãƙibarta (ita halakãwar).",
    "quran.90_1_translation": "Bã sai Na yi rantsuwa da wannan gari ba.",
    "quran.90_2_translation": "Alhãli kai kanã mai sauka a cikin wannan gari.",
    "quran.90_3_translation": "Da mahaifi da abin da ya haifa.",
    "quran.90_4_translation": "Lalle ne, Mun halitta mutum cikin wahala.",
    "quran.90_5_translation": "Kõ yanã zaton bãbu wani mai iya sãmun iko, a kansa?",
    "quran.90_6_translation": "Yana cẽwa \"Na halakarda dũkiya mai yawa,\"",
    "quran.90_7_translation": "Shin, yana zaton cewa wani bai gan shi ba?",
    "quran.90_8_translation": "Shin, ba Mu sanya masa idãnu biyu ba?",
    "quran.90_9_translation": "Da harshe, da leɓɓa biyu.",
    "quran.90_10_translation": "Kuma ba Mu shiryar da shi ga hanyõyi biyu ba?",
    "quran.90_11_translation": "To, don mene ne bai shiga Aƙabã ba?",
    "quran.90_12_translation": "Kuma mene ne ya sanar da kai abin da ake cẽ wa Aƙabã?",
    "quran.90_13_translation": "Ita ce fansar wuyan bãwa.",
    "quran.90_14_translation": "Ko kuwa ciyarwa, a cikin yini ma'abũcin yunwa.",
    "quran.90_15_translation": "Ga marãya ma'abũcin zumunta.",
    "quran.90_16_translation": "Ko kuwa wani matalauci ma'abũcin turɓãya.",
    "quran.90_17_translation": "Sa'an nan kuma ya kasance daga waɗanda suka yi ĩmãni, kuma suka yi wa jũna wasiyya da yin haƙuri, kuma suka yi wa jũna wasiyya da tausayi.",
    "quran.90_18_translation": "Waɗannan ne ma'abũta albarka",
    "quran.90_19_translation": "Kuma waɗanda suka kãfirta da ãyõyinMu, sũ ne ma'abũta shu'umci",
    "quran.90_20_translation": "A kansu akwai wata wuta abar kullewa.",
    "quran.89_1_translation": "Inã rantsuwa da alfijiri.",
    "quran.89_2_translation": "Da darũruwa gõma.",
    "quran.89_3_translation": "Da (adadi na) cikã da (na) mãrã.",
    "quran.89_4_translation": "Da dare idan yana shũɗewa.",
    "quran.89_5_translation": "Ko a cikin waɗannan akwai abin rantsuwa ga mai hankali (da yake kange shi daga zunubi)?",
    "quran.89_6_translation": "Ba ka ga yadda Ubangijinka Ya aikata da Ãdãwa ba?",
    "quran.89_7_translation": "Iramawa mãsu sakon ƙĩrar jiki.",
    "quran.89_8_translation": "Waɗanda ba a halitta kwatankwacinsu ba a cikin garũruwa (na dũniya).",
    "quran.89_9_translation": "Da samũdãwa waɗanda suka fasa duwãtsu a cikin Wadi suka yi gidãje)?",
    "quran.89_10_translation": "Da Fir'auna mai turãku.",
    "quran.89_11_translation": "Waɗanda suka ƙẽtare iyãkarsu, a cikin garũruwa?",
    "quran.89_12_translation": "Sabõda haka, suka yawaita yin ɓarna a cikinsu.",
    "quran.89_13_translation": "Sabõda haka Ubangijinka Ya zuba musu bũlãlar azãba.",
    "quran.89_14_translation": "Lalle ne, Ubangijinka Yana nan a mafaka.",
    "quran.89_15_translation": "To, amma fa mutum idan Ubangijibsa Ya jarraba shi, wãto Yã girmama shi kuma Ya yi masa ni'ima, sai ya ce: \"Ubangijina Ya girmama ni.\"",
    "quran.89_16_translation": "Kuma idan Ya jarraba shi, wãto Ya ƙuntata masa abincinsa, sai ya ce: \"Ubangijina Ya walãkanta ni.\"",
    "quran.89_17_translation": "A'aha! Bari wannan, ai bã ku girmama marãya!",
    "quran.89_18_translation": "Bã ku kwaɗaitã wa jũnanku ga (tattalin) abincin matalauci!",
    "quran.89_19_translation": "Kuma kuna cin dũkiyar gãdo, ci na tãrãwa.",
    "quran.89_20_translation": "Kuma kuna son dũkiya, so mai yawa.",
    "quran.89_21_translation": "A'aha! Idan aka niƙa ƙasa niƙewa sosai.",
    "quran.89_22_translation": "Kuma Ubangijinka Ya zo, alhãli malã'iku na jẽre, safũ- safu.",
    "quran.89_23_translation": "Kuma a ranar nan aka zo da Jahannama. A ranar nan mutum zai yi tunãni. To, inã fa tunãni yake a gare shi!",
    "quran.89_24_translation": "Yana dinga cẽwa, \"Kaitona, dã na gabatar (da aikin ƙwarai) domin rãyuwata!\"",
    "quran.89_25_translation": "To, a rãnar nan bãbu wani mai yin azãba irin azãbar Allah.",
    "quran.89_26_translation": "Kuma bãbu wani mai ɗauri irin ɗaurinSa.",
    "quran.89_27_translation": "Yã kai rai mai natsuwa!",
    "quran.89_28_translation": "Ka koma zuwa ga Ubangijinka, alhãli kana mai yarda (da abin da Ya ƙaddara maka a dũniya) abar yardarwa (da sakamakon da zã a ba ka a Lãhira).",
    "quran.89_29_translation": "Sabõbda haka, ka shiga cikin bãyiNa (mãsu bin umurui a dũniya).",
    "quran.89_30_translation": "Kuma ka shiga AljannaTa (a Lãhira).",
    "quran.88_1_translation": "Lalle ne labãrin (¡iyãma) mai rufe mutãne da tsoronta yã zo maka?",
    "quran.88_2_translation": "Wasu huskõki a rãnar nan ƙasƙantattu ne.",
    "quran.88_3_translation": "Mãsu aikin wahala ne, mãsu gajiya.",
    "quran.88_4_translation": "Zã su shiga wata wuta mai zãfi.",
    "quran.88_5_translation": "Ana shãyar da su daga wani marmaro mai zãfin ruwa.",
    "quran.88_6_translation": "Ba su da wani abinci fãce dai daga danyi.",
    "quran.88_7_translation": "Bã ya sanya ƙiba, kuma bã zai wadãtar daga yunwa ba.",
    "quran.88_8_translation": "Wasu huskõki a rãnar nan mãsu ni'ima ne.",
    "quran.88_9_translation": "Game da aikinsu, masu yarda ne.",
    "quran.88_10_translation": "(Suna) a cikin Aljanna maɗaukakiya.",
    "quran.88_11_translation": "Bã zã su ji yãsassar magana ba, a cikinta.",
    "quran.88_12_translation": "A cikinta akwai marmaro mai gudãna.",
    "quran.88_13_translation": "A cikinta akwai gadãje maɗaukaka.",
    "quran.88_14_translation": "Da kõfuna ar'aje.",
    "quran.88_15_translation": "Da filõli jẽre,",
    "quran.88_16_translation": "Da katifu shimfiɗe.",
    "quran.88_17_translation": "Ashe to bã zã su dũbãwa ba ga rãƙumã yadda aka halitta su?",
    "quran.88_18_translation": "Da zuwa ga sama yadda aka ɗaukaka ta?",
    "quran.88_19_translation": "Da zuwa ga duwãtsu yadda aka kafa su?",
    "quran.88_20_translation": "Da zuwa ga ƙasa yadda aka shimfiɗã ta?",
    "quran.88_21_translation": "sabõda haka, ka yi wa'azi, kai mai yin wa'azi ne kawai.",
    "quran.88_22_translation": "Ba ka zama mai ĩkon tanƙwasãwa a kansu ba.",
    "quran.88_23_translation": "Fãce dai duk wanda ya jũya bãya, kuma ya kãfirta.",
    "quran.88_24_translation": "To, Allah zai yi masa azãba, azãbar nan da take mafi girma.",
    "quran.88_25_translation": "Lalle ne, zuwa gare Mu kõmõwarsu take.",
    "quran.88_26_translation": "Sa'an nan lalle ne aikinMu ne Mu yi musu hisãbi.",
    "quran.87_1_translation": "Ka tsarkake sũnan Ubangijinka Mafi ɗaukaka.",
    "quran.87_2_translation": "Wanda Yã yi halitta sa'an nan Ya daidaita abin halittar.",
    "quran.87_3_translation": "Kuma Wanda Ya ƙaddara (abin da Ya so) sannan Ya shiryar, (da mutum ga hanyar alhẽri da ta sharri).",
    "quran.87_4_translation": "Kuma Wanda Ya fitar da makiyãyã.",
    "quran.87_5_translation": "Sa'an nan Ya mayar da ita ƙeƙasassa, baƙa.",
    "quran.87_6_translation": "Za mu karantar da kai (Alƙur'ãni) sabõda haka bã zã ka mantã (shi) ba.",
    "quran.87_7_translation": "Fãce abin da Allah Ya so, lalle ne Shi (Allah) Ya san bayyane da abin da yake bõye.",
    "quran.87_8_translation": "Kuma za Mu sauƙaƙe maka (al'amari) zuwa ga (Shari'a) mai sauƙi.",
    "quran.87_9_translation": "Sabõda baka, ka tunãtar, idan tunatarwa zã ta yi amfãni.",
    "quran.87_10_translation": "Wanda yake tsõron (Allah) Zai tuna.",
    "quran.87_11_translation": "Kuma shaƙiyyi, zai nisanceta,",
    "quran.87_12_translation": "Wanda zai shiga wutar da tã fi girma.",
    "quran.87_13_translation": "Sa'an nan bã zai mutu ba a cikinta, kuma bã zai rãyu ba.",
    "quran.87_14_translation": "Lalle ne wanda ya tsarkaka (da ĩmãni) yã sãmu babban rabo.",
    "quran.87_15_translation": "Kuma ya ambaci sũnan Ubangijinsa, sa'an nan yã yi salla.",
    "quran.87_16_translation": "Ba haka ba! Kunã zãɓin rãyuwa ta kusa dũniya.",
    "quran.87_17_translation": "Alhãli Lãhira ita ce mafi alheri kuma mafi wanzuwa.",
    "quran.87_18_translation": "Lalle ne, wannan yanã a cikin littafan farko.",
    "quran.87_19_translation": "Littaffan Ibrãhĩm da Mũsã.",
    "quran.86_1_translation": "Inã rantsuwa da sama da mai aukõwa da dare.",
    "quran.86_2_translation": "To, mẽ yã sanar da kai abin da ake cẽwa mai aukõwa da dare?",
    "quran.86_3_translation": "Shi ne taurãron nan mai tsananin haske.",
    "quran.86_4_translation": "Bãbu wani rai fãce a kansa akwai wani mai tsaro.",
    "quran.86_5_translation": "To, mutum ya dũba, daga mẽ aka halittã shi?",
    "quran.86_6_translation": "An halittã shi daga wani ruwa mai tunkuɗar jũna.",
    "quran.86_7_translation": "Yanã fita daga tsakanin tsatso da karankarman ƙirji.",
    "quran.86_8_translation": "Lalle ne Shi (Allah), ga mayar da shi (mutum), tabbas Mai iyãwa ne.",
    "quran.86_9_translation": "Rãnar da ake jarrabawar asirai.",
    "quran.86_10_translation": "Saboda haka, bã shi da wani ƙarfi, kuma bã shi da wani mai taimako (da zai iya kãre shi daga azãbar Allah).",
    "quran.86_11_translation": "Ina rantsuwa da sama ma'abũciyar ruwa mai kõmãwa yana yankẽwa.",
    "quran.86_12_translation": "Da ƙasa ma'abũciyar tsãgẽwa,",
    "quran.86_13_translation": "Lalle ne shĩ (Alƙur'ãni), haƙĩƙa magana ce daki-daki",
    "quran.86_14_translation": "Kuma shĩ bã bananci bane",
    "quran.86_15_translation": "Lalle ne sũ, suna ƙulla kaidi na sõsai.",
    "quran.86_16_translation": "Kuma Ni, Ina mayar da kaidi (gare su) kamar yadda suke ƙulla kaidi.",
    "quran.86_17_translation": "Saboda haka, ka yi wa kafirai jinkiri, ka dakata musu, sannu-sannu.",
    "quran.85_1_translation": "Inã rantsuwa da sama mai taurãrin lissafin shekara.",
    "quran.85_2_translation": "Da yinin da aka yi alkawarin zuwansa,",
    "quran.85_3_translation": "Da yini mai shaidu, da yini da ake halarta a cikinsa",
    "quran.85_4_translation": "An la'ani mutãnen rãmi.",
    "quran.85_5_translation": "Wato wuta wadda aka hura.",
    "quran.85_6_translation": "A lõkacin da suke a kan (gefen) ta a zazzaune.",
    "quran.85_7_translation": "Alhãli sũ, bisa ga abin da suke aikatãwa ga mũminai, sunã halarce.",
    "quran.85_8_translation": "Kuma ba su tuhumce su ba, fãce kawai domin sun yi ĩmãni da Allah Mabuwãyi, wanda ake gõdewa.",
    "quran.85_9_translation": "Wanda Yake shi ne da mulkin sammai da ƙasa, kuma Allah a kan kõme halarce Yake.",
    "quran.85_10_translation": "Lalle ne waɗanda suka fitini mũminai maza da mũminai mãta, sa'an nan ba su tũba ba to, sunã da azãbar Jahannama, kuma sunã da azãbar gõbara.",
    "quran.85_11_translation": "Lalle ne waɗanda suka yi ĩmãni, kuma suka aikata ayyukan ƙwarai, sunã da gidãjen Aljanna, ƙoramu na gudãna daga ƙarƙashin gidãjen. Wancan abu fa shi ne rabo babba.",
    "quran.85_12_translation": "Lalle ne damƙar Ubangijinka mai tsanani ce ƙwarai.",
    "quran.85_13_translation": "Lalle ne Shĩ, Shi ne Mai ƙãga halitta, kuma Ya mayar da ita (bãyan mutuwa).",
    "quran.85_14_translation": "Kuma Shi ne Mai gãfara, Mai bayyana sõyayya.",
    "quran.85_15_translation": "Mai Al'arshi mai girma",
    "quran.85_16_translation": "Mai aikatãwa ga abin da Yake nufi.",
    "quran.85_17_translation": "Ko lãbãrin rundanõni yã zo maka.",
    "quran.85_18_translation": "Fir'auna da samũdãwa?",
    "quran.85_19_translation": "Ã'aha! waɗanda suka kãfirta sunã cikin ƙaryatãwa.",
    "quran.85_20_translation": "Alhãli, Allah daga bãyansu, Mai kẽwaye su ne (da saninSa).",
    "quran.85_21_translation": "Ã'aha! Shi Alƙur'ãni ne mai girma.",
    "quran.85_22_translation": "A cikin Allo tsararre.",
    "quran.84_1_translation": "Idan sama ta kẽce,",
    "quran.84_2_translation": "Ta saurari Ubangijinta, kuma aka wajabta mata yin saurãron,",
    "quran.84_3_translation": "Kuma idan ƙasã aka mĩƙe ta,",
    "quran.84_4_translation": "Kuma ta jẽfar da abin da yake a cikinta, tã wõfinta daga kõme.",
    "quran.84_5_translation": "Kuma ta saurãri Ubangijinta, aka wajabta mata yin saurãren,",
    "quran.84_6_translation": "Ya kai mutum! Lalle ne kai mai aikin wahal da kai ne zuwa ga Ubangijinka, wahala mai tsanani, To, kai mai haɗuwa da Shi ne.",
    "quran.84_7_translation": "To, amma wanda aka bai wa littãfinsa da damansa.",
    "quran.84_8_translation": "To, za a yi masa hisãbi, hisãbi mai sauƙi.",
    "quran.84_9_translation": "Kuma ya jũya zuwa ga iyãlinsa (a cikin Aljanna), yanã mai raha.",
    "quran.84_10_translation": "Kuma amma wanda aka bai wa littãfinsa, daga wajen bãyansa.",
    "quran.84_11_translation": "To, zã shi dinga kiran halaka!",
    "quran.84_12_translation": "Kuma ya shiga sa'ĩr.",
    "quran.84_13_translation": "Lal1e ne shi, yã kasance (a dũniya) cikin iyãlinsa yanã mai raha.",
    "quran.84_14_translation": "Lalle ne yã yi zaton bã zai kõmo ba.",
    "quran.84_15_translation": "Na'am! Lalle ne, Ubangijinsa Ya kasance Mai gani gare shi.",
    "quran.84_16_translation": "To, ba sai Nã rantse da shafaƙi ba.",
    "quran.84_17_translation": "Da dare, da abin da ya ƙunsa.",
    "quran.84_18_translation": "Da watã idan (haskensa) ya cika.",
    "quran.84_19_translation": "Lalle ne kunã hawan wani hãli daga wani hãli.",
    "quran.84_20_translation": "To, mẽ ya sãme su, ba su yin ĩmãni?",
    "quran.84_21_translation": "Kuma idan an karanta Alkur'ãni a kansu, bã su yin tawãli'u?",
    "quran.84_22_translation": "Ba haka ba! waɗanda suka kãfirta, sai ƙaryatãwa suke yi.",
    "quran.84_23_translation": "Alhãli Allah Shĩ ne Mafi sani ga abin a suke tãrãwa.",
    "quran.84_24_translation": "Saboda haka, ka yi musu bushãra da azãba mai raɗaɗi.",
    "quran.84_25_translation": "Fãce waɗanda suka yi ĩmãni, suka aikata ayyukan ƙwarai, sunã da wani sakamako wanda bã ya yankẽwa.",
    "quran.83_1_translation": "Bone ya tabbata ga mãsu naƙƙasãwa.",
    "quran.83_2_translation": "Waɗanda suke idan suka auna daga mutãne suna cika mũdu.",
    "quran.83_3_translation": "Kuma idan sun auna musu da zakka ko da sikẽli, suna ragẽwa",
    "quran.83_4_translation": "Ashe! Waɗancan bã su tabbata cẽwa lalle sũ, ana tãyar da su ba?",
    "quran.83_5_translation": "Domin yini mai girma.",
    "quran.83_6_translation": "Yinin da mutãne ke tãshi zuwa ga Ubangijin halitta?",
    "quran.83_7_translation": "Haƙĩƙa lalle ne littãfin fãjirai dãhir, yana a cikin Sijjĩn.",
    "quran.83_8_translation": "Kuma, mẽ ya sanar da kai abin da akẽ cẽ wa Sijjĩn?",
    "quran.83_9_translation": "Wani 1ittãfi ne rubũtacce.",
    "quran.83_10_translation": "Bone yã tabbata a rãnar nan ga mãsu ƙaryatãwa.",
    "quran.83_11_translation": "Waɗanda suke ƙaryatãwa game da rãnar sakamako.",
    "quran.83_12_translation": "Babũ mai ƙaryatãwa gare shi fãce dukan mai ƙẽtare haddi mai yawan zunubi.",
    "quran.83_13_translation": "Idan ana karãtun ãyõyinmu, a kansa, sai ya ce: tãtsũniyõyin mutãnen farko ne.",
    "quran.83_14_translation": "A'aha! Bã haka ba, abin da suka kasance suna aikatãwa dai, yã yi tsãtsa a cikin zukãtãnsu.",
    "quran.83_15_translation": "A'aha! Haƙĩƙa, lalle ne sũ daga Ubangijinsu, rãnar nan, waɗanda ake shãmakancẽwa ne.",
    "quran.83_16_translation": "Sa'an nan, lalle ne, sũ mãsu shiga cikin Jahĩm ne.",
    "quran.83_17_translation": "Sa'an nan a ce: \"Wannan shi ne abin da kuka kasance kuna ƙaryatãwa game da shi.\"",
    "quran.83_18_translation": "A'aha! Haƙĩƙa lalle ne littãfin mãsu ɗã'ã yana a cikin Illiyyĩna?",
    "quran.83_19_translation": "Kuma mẽne ne yã sanar da kai abin da ake cẽwa Illiyyũna?",
    "quran.83_20_translation": "Wani littãfi ne rubũtacce.",
    "quran.83_21_translation": "Muƙarrabai suke halarta shi.",
    "quran.83_22_translation": "Lalle ne, mãsu ɗã'ã ga Allah tabbas suna cikin ni'ima.",
    "quran.83_23_translation": "A kan karagu, suna ta kallo.",
    "quran.83_24_translation": "Kana sani a cikin huskõkinsu, akwai kwarjinin ni'ima.",
    "quran.83_25_translation": "Ana shãyar da sũ daga wata giya wadda aka yunƙe a kan rufinta.",
    "quran.83_26_translation": "¡arshen kurɓinta miski ne. To, a cikin wannan, mãsu gwagwarmaya su yi ta gwagwarmayar nẽma.",
    "quran.83_27_translation": "Kuma abin da ake gauraya ta da shi, daga tasnĩm yake.",
    "quran.83_28_translation": "(Wato) wani marmaro ne wanda muƙarrabai ke sha daga gare shi.",
    "quran.83_29_translation": "Lalle ne, waɗanda suka kãfirta sun kasance (a dũniya) suna yi wa waɗanda suka yi ĩmãni dãriya.",
    "quran.83_30_translation": "Kuma idan sun shuɗe su sai su dinga yin zunɗe.",
    "quran.83_31_translation": "Kuma idan suka jũya zuwa ga iyãlansu, sai su tafi suna kãkãci.",
    "quran.83_32_translation": "Kuma idan sun gan su sai su ce: \"Lalle waɗannan ɓatattu ne.\"",
    "quran.83_33_translation": "Alhãli kuwa, ba a aike su ba dõmin su zama mãsu tsaro a kansu.",
    "quran.83_34_translation": "To, yau fa (a Lãhira] waɗanda suka yi ĩmãni, sũ ke yi wa kãfirai dãriya.",
    "quran.83_35_translation": "A kan karagu, suna ta kallo.",
    "quran.83_36_translation": "Shin an sãka ma kãfirai abin da suka kasance suna aikatawa?",
    "quran.82_1_translation": "Idan sama ta tsãge.",
    "quran.82_2_translation": "Kuma idan taurãri suka wãtse.",
    "quran.82_3_translation": "Kuma idan tẽkuna aka facce su.",
    "quran.82_4_translation": "Kuma idan kaburbura aka tõne su.",
    "quran.82_5_translation": "Rai yã san abin da ya gabatar, da abin da yã jinkirtar.",
    "quran.82_6_translation": "Yã kai mutum! Mẽ ya rũɗe ka game da Ubangijinka, Mai karimci.",
    "quran.82_7_translation": "Wanda Ya halitta ka sa'an nan ya daidaitã ka, Ya kuma tsakaitã ka.",
    "quran.82_8_translation": "A cikin kõwace irin sũra Ya so Ya ginã ka a kanta.",
    "quran.82_9_translation": "A'aha, bã haka ba, kuna ƙaryatãwa game da sakamako!",
    "quran.82_10_translation": "Lalle ne, a kanku, haƙiƙa akwai matsara.",
    "quran.82_11_translation": "Mãsu daraja, marubũta.",
    "quran.82_12_translation": "Sunã sanin abin da kuke aikatãwa.",
    "quran.82_13_translation": "Lalle ne, mãsu ɗã'ã ga Allah, dãhir, suna cikin ni'ima.",
    "quran.82_14_translation": "Kuma lalle ne, fãjirai, dãhir, sunã cikin Jahĩm.",
    "quran.82_15_translation": "Zã su shigẽ ta a rãnar sakamako.",
    "quran.82_16_translation": "Bã zã su faku daga gare ta ba.",
    "quran.82_17_translation": "Kuma mẽ ya sanar da kai abin da ake cẽ wa rẽnar sakamako?",
    "quran.82_18_translation": "Sa'an nan, mẽ ya sanar da kai abin da ake cẽ wa rãnar sakamako?",
    "quran.82_19_translation": "Rãnã ce da wani rai ba ya iya mallakar kõme dõmin wani rai al'amari, a rãnar nan, ga Allah (ɗai) yake.",
    "quran.81_1_translation": "Idan rãna aka shafe haskenta",
    "quran.81_2_translation": "Kuma idan taurãri suka gurɓãce (wani ya shiga a cikin wani).",
    "quran.81_3_translation": "Kuma idan duwãtsu aka tafiyar da su.",
    "quran.81_4_translation": "Kuma idan rãƙuma mãsu cikunna aka sakẽ su wãwai, bã ga kõwa ba.",
    "quran.81_5_translation": "Kuma idan dabbõbin dãji aka tattara su.",
    "quran.81_6_translation": "Kuma idan tẽkuna aka mayar da su wuta.",
    "quran.81_7_translation": "Kuma idan rãyuka aka haɗa su da jikunkunansu.",
    "quran.81_8_translation": "Kuma idan wadda aka turbuɗe ta da rai aka tambaye ta.",
    "quran.81_9_translation": "\"Sabõda wane laifi ne aka kashe ta?\"",
    "quran.81_10_translation": "Idan takardun ayyuka aka wãtsa su (ga mãsu su).",
    "quran.81_11_translation": "Kuma idan sama aka fẽɗe ta.",
    "quran.81_12_translation": "Kuma idan Jahĩm aka hũra ta",
    "quran.81_13_translation": "Kuma idan Aljanna aka kusantar da ita.",
    "quran.81_14_translation": "Rai ya san abin da ya halartar (a rãnar nan).",
    "quran.81_15_translation": "To, ba sai Na yi rantsuwa da taurãri matafã ba.",
    "quran.81_16_translation": "Mãsu gudu suna ɓũya.",
    "quran.81_17_translation": "Da dare idan ya bãyar da bãya.",
    "quran.81_18_translation": "Da sãfiya idan ta yi lumfashi.",
    "quran.81_19_translation": "Lalle ne shi (Alƙur'ãni) haƙƙan, maganar wani manzon (Allah) ne mai girma ga Allah.",
    "quran.81_20_translation": "Mai ƙarfi, mai daraja a wurin Mai Al'arshi.",
    "quran.81_21_translation": "Wanda ake yi wa ɗã'a (wato shugaban malã'iku) ne a can, amintacce.",
    "quran.81_22_translation": "Kuma abokinku ba mahaukaci ba ne.",
    "quran.81_23_translation": "Kuma lalle ne, yã gan shi a cikin sararin sama mabayyani.",
    "quran.81_24_translation": "Kuma shi, ga gaibi bã mai rowa ba ne.",
    "quran.81_25_translation": "Kuma shi (Alƙur'ani) bã maganar shaiɗani, wanda aka la'ana, ba ce.",
    "quran.81_26_translation": "Shin, a inã zã ku tafi?",
    "quran.81_27_translation": "Lalle ne shi (Alƙur'ãni), bã kõme ba ne fãce gargaɗi ga talikai.",
    "quran.81_28_translation": "Ga wanda ya so, daga cikinku, ya shiryu.",
    "quran.81_29_translation": "Kuma bã zã ku so ba sai idan Allah Ubangijin halitta Yã yarda.",
    "quran.79_1_translation": "Ina rantsuwa da mala'iku mãsu fisgar rãyuka (na kafirai) da ƙarfi.",
    "quran.79_2_translation": "Da mãsu ɗibar rãyuka (na mũminai) da sauƙi a cikin nishãɗi.",
    "quran.79_3_translation": "Da mãsu sauka daga sama da umurnin Allah kamar suna iyo.",
    "quran.79_4_translation": "Sa'an nan, su zama mãsu gaugãwa (da umurnin Allah) kamar suna tsẽre.",
    "quran.79_5_translation": "Sa, an nan, su kasance masu shirya gudanar da umurni.",
    "quran.79_6_translation": "Rãnar da mai girgiza abũbuwa (bũsar farko) zã ta kaɗa.",
    "quran.79_7_translation": "Mai biyar ta (bũsa ta biyu) nã biye.",
    "quran.79_8_translation": "Wasu zukãta, a rãnar nan, mãsu jin tsõro ne.",
    "quran.79_9_translation": "Alhãli idãnunsu na ƙasƙantattu.",
    "quran.79_10_translation": "Sunã cẽwa \"Ashe lalle zã a iya mayar da mu a kan sãwunmu?",
    "quran.79_11_translation": "\"Ashe, idan muka zama ƙasusuwa rududdugaggu?\"",
    "quran.79_12_translation": "Suka ce: \"Waccan kam kõmãwa ce, tãɓaɓɓiya!\"",
    "quran.79_13_translation": "To, ita kam, tsãwa guda kawai ce.",
    "quran.79_14_translation": "Sai kawai gã su a bãyan ƙasa.",
    "quran.79_15_translation": "Shin, lãbãrin Mũsã ya zo maka?",
    "quran.79_16_translation": "A lõkacin da Ubangijinsa Ya kirãye shi, a cikin kwari mai tsarki, wato Duwã?",
    "quran.79_17_translation": "Ka tafi zuwa ga Fir'auna, lalle ne shi, ya ƙẽtare haddi.",
    "quran.79_18_translation": "\"Sai ka ce masa, Kõ zã ka so ka tsarkaka.",
    "quran.79_19_translation": "\"Kuma in shiryar da kai zuwa ga Ubangijinka domin ka ji tsoronSa?\"",
    "quran.79_20_translation": "Sai ya nũna masa ãyar nan mafi girma.",
    "quran.79_21_translation": "Sai ya ƙaryata, kuma ya sãɓa (umurni),",
    "quran.79_22_translation": "Sa'an nan ya jũya bãya, yanã tafiya da sauri.",
    "quran.79_23_translation": "Sai ya yi gayya, sa'an nan ya yi kira.",
    "quran.79_24_translation": "Sai ya ce: \"Nĩ ne Ubangijinku mafi ɗaudaka.\"",
    "quran.79_25_translation": "Sabõda haka Allah Ya kama shi, dõmin azãbar maganar ƙarshe da ta farko.",
    "quran.79_26_translation": "Lalle ne, a cikin wannan haƙiƙa akwai abin kula ga wanda yake tsõron Allah.",
    "quran.79_27_translation": "Shin, kũ ne mafi wuyar halitta ko sama? Allah Ya gina ta.",
    "quran.79_28_translation": "Ya ɗaukaka rufinta, sa'an nan Ya daidaita ta.",
    "quran.79_29_translation": "Kuma Ya duhuntar da darenta, kuma Ya fitar da hantsinta.",
    "quran.79_30_translation": "Kuma, ƙasa a bayan haka Ya mulmula ta.",
    "quran.79_31_translation": "Ya fitar da ruwanta daga gare ta da makiyãyarta.",
    "quran.79_32_translation": "Da duwatsu, Yã kafe ta.",
    "quran.79_33_translation": "Domin jiyarwa dãɗi a gare ku, kuma ga dabbõbinku.",
    "quran.79_34_translation": "To, idan uwar masĩfu, mafi girma, ta zo.",
    "quran.79_35_translation": "Rãnar da mutum zai yi tunãnin abin da ya aikata.",
    "quran.79_36_translation": "Kuma, a bayyana Jahĩm ga mai gani.",
    "quran.79_37_translation": "To, amma wanda ya yi girman kai.",
    "quran.79_38_translation": "Kuma, ya zãɓi rãyuwa ta kusa, (wato dũniya).",
    "quran.79_39_translation": "To, lalle ne Jahĩm, ita ce makõma.",
    "quran.79_40_translation": "Kuma, amma wanda ya ji tsõron tsayi a gaba ga Ubangijinsa, kuma ya kange kansa daga son rai.",
    "quran.79_41_translation": "To, lalle ne Aljanna ita ce makõma.",
    "quran.79_42_translation": "Sunã tambayar ka game da sa'a, wai yaushe ne matabbatarta?",
    "quran.79_43_translation": "Me ya haɗã ka da ambatonta?",
    "quran.79_44_translation": "Zuwa ga Ubangijinka ƙarshen al'amarinta yake.",
    "quran.79_45_translation": "Kai mai gargaɗi kawai ne ga mai tsõron ta.",
    "quran.79_46_translation": "Kamar sũ a rãnar da zã su gan ta, ba su zauna ba fãce a lõkacin marẽce ko hantsinsa.",
    "quran.78_1_translation": "A kan mẽ suke tambayar jũna?",
    "quran.78_2_translation": "A kan muhimmin lãbãri mai girma (Alƙur'ãni)?",
    "quran.78_3_translation": "Wanda suke sãɓa wa jũna a cikinsa?",
    "quran.78_4_translation": "A'aha! Zã su sani.",
    "quran.78_5_translation": "Kuma, a'aha! Zã su sani.",
    "quran.78_6_translation": "Ashe, ba Mu sanya ƙasa shimfiɗa ba?",
    "quran.78_7_translation": "Da duwãtsu turaku (ga riƙe ƙasa)?",
    "quran.78_8_translation": "Kuma, Mun halitta ku mazã da mãtã?",
    "quran.78_9_translation": "Kuma, Muka sanya barcinku hũtãwa?",
    "quran.78_10_translation": "Kuma, Muka sanya dare (ya zama) sutura?",
    "quran.78_11_translation": "Kuma, Muka sanya yini (yazama) lõkacin nẽman abinci?",
    "quran.78_12_translation": "Kuma, Muka gina, a samanku, sammai bakwai mãsu ƙarfi?",
    "quran.78_13_translation": "Kuma, Muka sanya fitila mai tsanin haske (rãnã)?",
    "quran.78_14_translation": "Kuma, Muka saukar daga cikakkun girãgizai, ruwa mai yawan zuba?",
    "quran.78_15_translation": "Dõmin, Mu fitar da ƙwaya da tsiri game da shi?",
    "quran.78_16_translation": "Da itãcen lambuna mãsu lillibniya?",
    "quran.78_17_translation": "Lalle ne, rãnar rarrabẽwa tã kasance abin ƙayyadẽ wa lõkaci.",
    "quran.78_18_translation": "Rãnar da zã a yi bũsa a cikin ƙaho, sai ku zo, jama'a jama'a.",
    "quran.78_19_translation": "Kuma, aka buɗe sama, sai ta kasance ƙõfõfi.",
    "quran.78_20_translation": "Kuma, aka tafiyar da duwãtsu, sai suka kasance ƙũra.",
    "quran.78_21_translation": "Lalle ne, Jahannama tã kasance madãkata.",
    "quran.78_22_translation": "Ga mãsu ƙẽtare iyãkõki, tã zama makõma.",
    "quran.78_23_translation": "Sunã, mãsu zama a cikinta, zãmunna.",
    "quran.78_24_translation": "Bã su ɗanɗanãwar wani sanyi a cikinta, kuma bã su ɗanɗana abin sha.",
    "quran.78_25_translation": "Fãce tafasasshen ruwa da ruɓaɓɓen jini.",
    "quran.78_26_translation": "Sakamako mai dãcẽwa.",
    "quran.78_27_translation": "Lalle ne, sũ, sun kasance bã su fãtar sauƙin wani hisãbi.",
    "quran.78_28_translation": "Kuma, suka ƙaryata game da ãyõyinMu, ƙaryatãwa!",
    "quran.78_29_translation": "Alhãli, kõwane abu Mun ƙididdigẽ shi, a rubũce.",
    "quran.78_30_translation": "Sabõda haka, ku ɗanɗana domin haka, bã zã Mu ƙara muku kõme ba fãce azãba.",
    "quran.78_31_translation": "Lalle ne, mãsu taƙawã nã da wani wurin sãmun babban rabo.",
    "quran.78_32_translation": "Lambuna da inabõbi.",
    "quran.78_33_translation": "Da cikakkun 'yammata, tsãrar jũna.",
    "quran.78_34_translation": "Da hinjãlan giya cikakku.",
    "quran.78_35_translation": "Bã su jin yãsassar magana, a cikinta, kuma bã su jin ƙaryatãwa.",
    "quran.78_36_translation": "Dõmin sakamako daga Ubangijinka, kyautã mai yawa.",
    "quran.78_37_translation": "Ubangijin sammai da ƙasa da abin da yake a tsakãninsu, Mai rahama, bã su da ikon yin wata magana daga gare Shi.",
    "quran.78_38_translation": "Rãnar da Rũhi da malã'iku zã su tsaya a cikin safu, bã su magana, sai wanda Allah Ya yi masa izni, kuma ya faɗi abin da ke daidai.",
    "quran.78_39_translation": "Wancan, shi ne yini na gaskiya; to wanda ya so, ya riƙa makõma zuwa ga Ubangijinsa.",
    "quran.78_40_translation": "Lalle ne, Mũ, Mun yi muku gargaɗin azãba makusanciya, rãnar da mutum ke dũbi zuwa ga abin da hannãyensa suka aikata, kuma kafiri ya ce: \"Kaitona, dã dai nã zama turɓãya!\""
  },
  "ar": {
    "quran.114_1_translation": "قُلْ أَعُوذُ بِرَبِّ النَّاسِ",
    "quran.114_2_translation": "مَلِكِ النَّاسِ",
    "quran.114_3_translation": "إِلَٰهِ النَّاسِ",
    "quran.114_4_translation": "مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ",
    "quran.114_5_translation": "الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ",
    "quran.114_6_translation": "مِنَ الْجِنَّةِ وَالنَّاسِ",
    "quran.113_1_translation": "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ",
    "quran.113_2_translation": "مِنْ شَرِّ مَا خَلَقَ",
    "quran.113_3_translation": "وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ",
    "quran.113_4_translation": "وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ",
    "quran.113_5_translation": "وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ",
    "quran.112_1_translation": "قُلْ هُوَ اللَّهُ أَحَدٌ",
    "quran.112_2_translation": "اللَّهُ الصَّمَدُ",
    "quran.112_3_translation": "لَمْ يَلِدْ وَلَمْ يُولَدْ",
    "quran.112_4_translation": "وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ",
    "quran.111_1_translation": "تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ",
    "quran.111_2_translation": "مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ",
    "quran.111_3_translation": "سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ",
    "quran.111_4_translation": "وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ",
    "quran.111_5_translation": "فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ",
    "quran.110_1_translation": "إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ",
    "quran.110_2_translation": "وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا",
    "quran.110_3_translation": "فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ ۚ إِنَّهُ كَانَ تَوَّابًا",
    "quran.109_1_translation": "قُلْ يَا أَيُّهَا الْكَافِرُونَ",
    "quran.109_2_translation": "لَا أَعْبُدُ مَا تَعْبُدُونَ",
    "quran.109_3_translation": "وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ",
    "quran.109_4_translation": "وَلَا أَنَا عَابِدٌ مَا عَبَدْتُمْ",
    "quran.109_5_translation": "وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ",
    "quran.109_6_translation": "لَكُمْ دِينُكُمْ وَلِيَ دِينِ",
    "quran.108_1_translation": "إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ",
    "quran.108_2_translation": "فَصَلِّ لِرَبِّكَ وَانْحَرْ",
    "quran.108_3_translation": "إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ",
    "quran.107_1_translation": "أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ",
    "quran.107_2_translation": "فَذَٰلِكَ الَّذِي يَدُعُّ الْيَتِيمَ",
    "quran.107_3_translation": "وَلَا يَحُضُّ عَلَىٰ طَعَامِ الْمِسْكِينِ",
    "quran.107_4_translation": "فَوَيْلٌ لِلْمُصَلِّينَ",
    "quran.107_5_translation": "الَّذِينَ هُمْ عَنْ صَلَاتِهِمْ سَاهُونَ",
    "quran.107_6_translation": "الَّذِينَ هُمْ يُرَاءُونَ",
    "quran.107_7_translation": "وَيَمْنَعُونَ الْمَاعُونَ",
    "quran.106_1_translation": "لِإِيلَافِ قُرَيْشٍ",
    "quran.106_2_translation": "إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ",
    "quran.106_3_translation": "فَلْيَعْبُدُوا رَبَّ هَٰذَا الْبَيْتِ",
    "quran.106_4_translation": "الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ وَآمَنَهُمْ مِنْ خَوْفٍ",
    "quran.105_1_translation": "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ",
    "quran.105_2_translation": "أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ",
    "quran.105_3_translation": "وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ",
    "quran.105_4_translation": "تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ",
    "quran.105_5_translation": "فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ",
    "quran.104_1_translation": "وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ",
    "quran.104_2_translation": "الَّذِي جَمَعَ مَالًا وَعَدَّدَهُ",
    "quran.104_3_translation": "يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ",
    "quran.104_4_translation": "كَلَّا ۖ لَيُنْبَذَنَّ فِي الْحُطَمَةِ",
    "quran.104_5_translation": "وَمَا أَدْرَاكَ مَا الْحُطَمَةُ",
    "quran.104_6_translation": "نَارُ اللَّهِ الْمُوقَدَةُ",
    "quran.104_7_translation": "الَّتِي تَطَّلِعُ عَلَى الْأَفْئِدَةِ",
    "quran.104_8_translation": "إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ",
    "quran.104_9_translation": "فِي عَمَدٍ مُمَدَّدَةٍ",
    "quran.103_1_translation": "وَالْعَصْرِ",
    "quran.103_2_translation": "إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ",
    "quran.103_3_translation": "إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ",
    "quran.102_1_translation": "أَلْهَاكُمُ التَّكَاثُرُ",
    "quran.102_2_translation": "حَتَّىٰ زُرْتُمُ الْمَقَابِرَ",
    "quran.102_3_translation": "كَلَّا سَوْفَ تَعْلَمُونَ",
    "quran.102_4_translation": "ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ",
    "quran.102_5_translation": "كَلَّا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ",
    "quran.102_6_translation": "لَتَرَوُنَّ الْجَحِيمَ",
    "quran.102_7_translation": "ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ",
    "quran.102_8_translation": "ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ",
    "quran.101_1_translation": "الْقَارِعَةُ",
    "quran.101_2_translation": "مَا الْقَارِعَةُ",
    "quran.101_3_translation": "وَمَا أَدْرَاكَ مَا الْقَارِعَةُ",
    "quran.101_4_translation": "يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ",
    "quran.101_5_translation": "وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنْفُوشِ",
    "quran.101_6_translation": "فَأَمَّا مَنْ ثَقُلَتْ مَوَازِينُهُ",
    "quran.101_7_translation": "فَهُوَ فِي عِيشَةٍ رَاضِيَةٍ",
    "quran.101_8_translation": "وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ",
    "quran.101_9_translation": "فَأُمُّهُ هَاوِيَةٌ",
    "quran.101_10_translation": "وَمَا أَدْرَاكَ مَا هِيَهْ",
    "quran.101_11_translation": "نَارٌ حَامِيَةٌ",
    "quran.100_1_translation": "وَالْعَادِيَاتِ ضَبْحًا",
    "quran.100_2_translation": "فَالْمُورِيَاتِ قَدْحًا",
    "quran.100_3_translation": "فَالْمُغِيرَاتِ صُبْحًا",
    "quran.100_4_translation": "فَأَثَرْنَ بِهِ نَقْعًا",
    "quran.100_5_translation": "فَوَسَطْنَ بِهِ جَمْعًا",
    "quran.100_6_translation": "إِنَّ الْإِنْسَانَ لِرَبِّهِ لَكَنُودٌ",
    "quran.100_7_translation": "وَإِنَّهُ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ",
    "quran.100_8_translation": "وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ",
    "quran.100_9_translation": "۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِي الْقُبُورِ",
    "quran.100_10_translation": "وَحُصِّلَ مَا فِي الصُّدُورِ",
    "quran.100_11_translation": "إِنَّ رَبَّهُمْ بِهِمْ يَوْمَئِذٍ لَخَبِيرٌ",
    "quran.99_1_translation": "إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا",
    "quran.99_2_translation": "وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا",
    "quran.99_3_translation": "وَقَالَ الْإِنْسَانُ مَا لَهَا",
    "quran.99_4_translation": "يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا",
    "quran.99_5_translation": "بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا",
    "quran.99_6_translation": "يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا لِيُرَوْا أَعْمَالَهُمْ",
    "quran.99_7_translation": "فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ",
    "quran.99_8_translation": "وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ",
    "quran.98_1_translation": "لَمْ يَكُنِ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ مُنْفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ الْبَيِّنَةُ",
    "quran.98_2_translation": "رَسُولٌ مِنَ اللَّهِ يَتْلُو صُحُفًا مُطَهَّرَةً",
    "quran.98_3_translation": "فِيهَا كُتُبٌ قَيِّمَةٌ",
    "quran.98_4_translation": "وَمَا تَفَرَّقَ الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِنْ بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَةُ",
    "quran.98_5_translation": "وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ ۚ وَذَٰلِكَ دِينُ الْقَيِّمَةِ",
    "quran.98_6_translation": "إِنَّ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ فِي نَارِ جَهَنَّمَ خَالِدِينَ فِيهَا ۚ أُولَٰئِكَ هُمْ شَرُّ الْبَرِيَّةِ",
    "quran.98_7_translation": "إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَٰئِكَ هُمْ خَيْرُ الْبَرِيَّةِ",
    "quran.98_8_translation": "جَزَاؤُهُمْ عِنْدَ رَبِّهِمْ جَنَّاتُ عَدْنٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ۖ رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِيَ رَبَّهُ",
    "quran.97_1_translation": "إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ",
    "quran.97_2_translation": "وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ",
    "quran.97_3_translation": "لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ",
    "quran.97_4_translation": "تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِمْ مِنْ كُلِّ أَمْرٍ",
    "quran.97_5_translation": "سَلَامٌ هِيَ حَتَّىٰ مَطْلَعِ الْفَجْرِ",
    "quran.96_1_translation": "اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ",
    "quran.96_2_translation": "خَلَقَ الْإِنْسَانَ مِنْ عَلَقٍ",
    "quran.96_3_translation": "اقْرَأْ وَرَبُّكَ الْأَكْرَمُ",
    "quran.96_4_translation": "الَّذِي عَلَّمَ بِالْقَلَمِ",
    "quran.96_5_translation": "عَلَّمَ الْإِنْسَانَ مَا لَمْ يَعْلَمْ",
    "quran.96_6_translation": "كَلَّا إِنَّ الْإِنْسَانَ لَيَطْغَىٰ",
    "quran.96_7_translation": "أَنْ رَآهُ اسْتَغْنَىٰ",
    "quran.96_8_translation": "إِنَّ إِلَىٰ رَبِّكَ الرُّجْعَىٰ",
    "quran.96_9_translation": "أَرَأَيْتَ الَّذِي يَنْهَىٰ",
    "quran.96_10_translation": "عَبْدًا إِذَا صَلَّىٰ",
    "quran.96_11_translation": "أَرَأَيْتَ إِنْ كَانَ عَلَى الْهُدَىٰ",
    "quran.96_12_translation": "أَوْ أَمَرَ بِالتَّقْوَىٰ",
    "quran.96_13_translation": "أَرَأَيْتَ إِنْ كَذَّبَ وَتَوَلَّىٰ",
    "quran.96_14_translation": "أَلَمْ يَعْلَمْ بِأَنَّ اللَّهَ يَرَىٰ",
    "quran.96_15_translation": "كَلَّا لَئِنْ لَمْ يَنْتَهِ لَنَسْفَعًا بِالنَّاصِيَةِ",
    "quran.96_16_translation": "نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ",
    "quran.96_17_translation": "فَلْيَدْعُ نَادِيَهُ",
    "quran.96_18_translation": "سَنَدْعُ الزَّبَانِيَةَ",
    "quran.96_19_translation": "كَلَّا لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبْ ۩",
    "quran.95_1_translation": "وَالتِّينِ وَالزَّيْتُونِ",
    "quran.95_2_translation": "وَطُورِ سِينِينَ",
    "quran.95_3_translation": "وَهَٰذَا الْبَلَدِ الْأَمِينِ",
    "quran.95_4_translation": "لَقَدْ خَلَقْنَا الْإِنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ",
    "quran.95_5_translation": "ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ",
    "quran.95_6_translation": "إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ",
    "quran.95_7_translation": "فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ",
    "quran.95_8_translation": "أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ",
    "quran.93_1_translation": "وَالضُّحَىٰ",
    "quran.93_2_translation": "وَاللَّيْلِ إِذَا سَجَىٰ",
    "quran.93_3_translation": "مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ",
    "quran.93_4_translation": "وَلَلْآخِرَةُ خَيْرٌ لَكَ مِنَ الْأُولَىٰ",
    "quran.93_5_translation": "وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰ",
    "quran.93_6_translation": "أَلَمْ يَجِدْكَ يَتِيمًا فَآوَىٰ",
    "quran.93_7_translation": "وَوَجَدَكَ ضَالًّا فَهَدَىٰ",
    "quran.93_8_translation": "وَوَجَدَكَ عَائِلًا فَأَغْنَىٰ",
    "quran.93_9_translation": "فَأَمَّا الْيَتِيمَ فَلَا تَقْهَرْ",
    "quran.93_10_translation": "وَأَمَّا السَّائِلَ فَلَا تَنْهَرْ",
    "quran.93_11_translation": "وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ",
    "quran.92_1_translation": "وَاللَّيْلِ إِذَا يَغْشَىٰ",
    "quran.92_2_translation": "وَالنَّهَارِ إِذَا تَجَلَّىٰ",
    "quran.92_3_translation": "وَمَا خَلَقَ الذَّكَرَ وَالْأُنْثَىٰ",
    "quran.92_4_translation": "إِنَّ سَعْيَكُمْ لَشَتَّىٰ",
    "quran.92_5_translation": "فَأَمَّا مَنْ أَعْطَىٰ وَاتَّقَىٰ",
    "quran.92_6_translation": "وَصَدَّقَ بِالْحُسْنَىٰ",
    "quran.92_7_translation": "فَسَنُيَسِّرُهُ لِلْيُسْرَىٰ",
    "quran.92_8_translation": "وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَىٰ",
    "quran.92_9_translation": "وَكَذَّبَ بِالْحُسْنَىٰ",
    "quran.92_10_translation": "فَسَنُيَسِّرُهُ لِلْعُسْرَىٰ",
    "quran.92_11_translation": "وَمَا يُغْنِي عَنْهُ مَالُهُ إِذَا تَرَدَّىٰ",
    "quran.92_12_translation": "إِنَّ عَلَيْنَا لَلْهُدَىٰ",
    "quran.92_13_translation": "وَإِنَّ لَنَا لَلْآخِرَةَ وَالْأُولَىٰ",
    "quran.92_14_translation": "فَأَنْذَرْتُكُمْ نَارًا تَلَظَّىٰ",
    "quran.92_15_translation": "لَا يَصْلَاهَا إِلَّا الْأَشْقَى",
    "quran.92_16_translation": "الَّذِي كَذَّبَ وَتَوَلَّىٰ",
    "quran.92_17_translation": "وَسَيُجَنَّبُهَا الْأَتْقَى",
    "quran.92_18_translation": "الَّذِي يُؤْتِي مَالَهُ يَتَزَكَّىٰ",
    "quran.92_19_translation": "وَمَا لِأَحَدٍ عِنْدَهُ مِنْ نِعْمَةٍ تُجْزَىٰ",
    "quran.92_20_translation": "إِلَّا ابْتِغَاءَ وَجْهِ رَبِّهِ الْأَعْلَىٰ",
    "quran.92_21_translation": "وَلَسَوْفَ يَرْضَىٰ",
    "quran.91_1_translation": "وَالشَّمْسِ وَضُحَاهَا",
    "quran.91_2_translation": "وَالْقَمَرِ إِذَا تَلَاهَا",
    "quran.91_3_translation": "وَالنَّهَارِ إِذَا جَلَّاهَا",
    "quran.91_4_translation": "وَاللَّيْلِ إِذَا يَغْشَاهَا",
    "quran.91_5_translation": "وَالسَّمَاءِ وَمَا بَنَاهَا",
    "quran.91_6_translation": "وَالْأَرْضِ وَمَا طَحَاهَا",
    "quran.91_7_translation": "وَنَفْسٍ وَمَا سَوَّاهَا",
    "quran.91_8_translation": "فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا",
    "quran.91_9_translation": "قَدْ أَفْلَحَ مَنْ زَكَّاهَا",
    "quran.91_10_translation": "وَقَدْ خَابَ مَنْ دَسَّاهَا",
    "quran.91_11_translation": "كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا",
    "quran.91_12_translation": "إِذِ انْبَعَثَ أَشْقَاهَا",
    "quran.91_13_translation": "فَقَالَ لَهُمْ رَسُولُ اللَّهِ نَاقَةَ اللَّهِ وَسُقْيَاهَا",
    "quran.91_14_translation": "فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ بِذَنْبِهِمْ فَسَوَّاهَا",
    "quran.91_15_translation": "وَلَا يَخَافُ عُقْبَاهَا",
    "quran.90_1_translation": "لَا أُقْسِمُ بِهَٰذَا الْبَلَدِ",
    "quran.90_2_translation": "وَأَنْتَ حِلٌّ بِهَٰذَا الْبَلَدِ",
    "quran.90_3_translation": "وَوَالِدٍ وَمَا وَلَدَ",
    "quran.90_4_translation": "لَقَدْ خَلَقْنَا الْإِنْسَانَ فِي كَبَدٍ",
    "quran.90_5_translation": "أَيَحْسَبُ أَنْ لَنْ يَقْدِرَ عَلَيْهِ أَحَدٌ",
    "quran.90_6_translation": "يَقُولُ أَهْلَكْتُ مَالًا لُبَدًا",
    "quran.90_7_translation": "أَيَحْسَبُ أَنْ لَمْ يَرَهُ أَحَدٌ",
    "quran.90_8_translation": "أَلَمْ نَجْعَلْ لَهُ عَيْنَيْنِ",
    "quran.90_9_translation": "وَلِسَانًا وَشَفَتَيْنِ",
    "quran.90_10_translation": "وَهَدَيْنَاهُ النَّجْدَيْنِ",
    "quran.90_11_translation": "فَلَا اقْتَحَمَ الْعَقَبَةَ",
    "quran.90_12_translation": "وَمَا أَدْرَاكَ مَا الْعَقَبَةُ",
    "quran.90_13_translation": "فَكُّ رَقَبَةٍ",
    "quran.90_14_translation": "أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ",
    "quran.90_15_translation": "يَتِيمًا ذَا مَقْرَبَةٍ",
    "quran.90_16_translation": "أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ",
    "quran.90_17_translation": "ثُمَّ كَانَ مِنَ الَّذِينَ آمَنُوا وَتَوَاصَوْا بِالصَّبْرِ وَتَوَاصَوْا بِالْمَرْحَمَةِ",
    "quran.90_18_translation": "أُولَٰئِكَ أَصْحَابُ الْمَيْمَنَةِ",
    "quran.90_19_translation": "وَالَّذِينَ كَفَرُوا بِآيَاتِنَا هُمْ أَصْحَابُ الْمَشْأَمَةِ",
    "quran.90_20_translation": "عَلَيْهِمْ نَارٌ مُؤْصَدَةٌ",
    "quran.89_1_translation": "وَالْفَجْرِ",
    "quran.89_2_translation": "وَلَيَالٍ عَشْرٍ",
    "quran.89_3_translation": "وَالشَّفْعِ وَالْوَتْرِ",
    "quran.89_4_translation": "وَاللَّيْلِ إِذَا يَسْرِ",
    "quran.89_5_translation": "هَلْ فِي ذَٰلِكَ قَسَمٌ لِذِي حِجْرٍ",
    "quran.89_6_translation": "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ",
    "quran.89_7_translation": "إِرَمَ ذَاتِ الْعِمَادِ",
    "quran.89_8_translation": "الَّتِي لَمْ يُخْلَقْ مِثْلُهَا فِي الْبِلَادِ",
    "quran.89_9_translation": "وَثَمُودَ الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِ",
    "quran.89_10_translation": "وَفِرْعَوْنَ ذِي الْأَوْتَادِ",
    "quran.89_11_translation": "الَّذِينَ طَغَوْا فِي الْبِلَادِ",
    "quran.89_12_translation": "فَأَكْثَرُوا فِيهَا الْفَسَادَ",
    "quran.89_13_translation": "فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ",
    "quran.89_14_translation": "إِنَّ رَبَّكَ لَبِالْمِرْصَادِ",
    "quran.89_15_translation": "فَأَمَّا الْإِنْسَانُ إِذَا مَا ابْتَلَاهُ رَبُّهُ فَأَكْرَمَهُ وَنَعَّمَهُ فَيَقُولُ رَبِّي أَكْرَمَنِ",
    "quran.89_16_translation": "وَأَمَّا إِذَا مَا ابْتَلَاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أَهَانَنِ",
    "quran.89_17_translation": "كَلَّا ۖ بَلْ لَا تُكْرِمُونَ الْيَتِيمَ",
    "quran.89_18_translation": "وَلَا تَحَاضُّونَ عَلَىٰ طَعَامِ الْمِسْكِينِ",
    "quran.89_19_translation": "وَتَأْكُلُونَ التُّرَاثَ أَكْلًا لَمًّا",
    "quran.89_20_translation": "وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا",
    "quran.89_21_translation": "كَلَّا إِذَا دُكَّتِ الْأَرْضُ دَكًّا دَكًّا",
    "quran.89_22_translation": "وَجَاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا",
    "quran.89_23_translation": "وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ ۚ يَوْمَئِذٍ يَتَذَكَّرُ الْإِنْسَانُ وَأَنَّىٰ لَهُ الذِّكْرَىٰ",
    "quran.89_24_translation": "يَقُولُ يَا لَيْتَنِي قَدَّمْتُ لِحَيَاتِي",
    "quran.89_25_translation": "فَيَوْمَئِذٍ لَا يُعَذِّبُ عَذَابَهُ أَحَدٌ",
    "quran.89_26_translation": "وَلَا يُوثِقُ وَثَاقَهُ أَحَدٌ",
    "quran.89_27_translation": "يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ",
    "quran.89_28_translation": "ارْجِعِي إِلَىٰ رَبِّكِ رَاضِيَةً مَرْضِيَّةً",
    "quran.89_29_translation": "فَادْخُلِي فِي عِبَادِي",
    "quran.89_30_translation": "وَادْخُلِي جَنَّتِي",
    "quran.88_1_translation": "هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ",
    "quran.88_2_translation": "وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ",
    "quran.88_3_translation": "عَامِلَةٌ نَاصِبَةٌ",
    "quran.88_4_translation": "تَصْلَىٰ نَارًا حَامِيَةً",
    "quran.88_5_translation": "تُسْقَىٰ مِنْ عَيْنٍ آنِيَةٍ",
    "quran.88_6_translation": "لَيْسَ لَهُمْ طَعَامٌ إِلَّا مِنْ ضَرِيعٍ",
    "quran.88_7_translation": "لَا يُسْمِنُ وَلَا يُغْنِي مِنْ جُوعٍ",
    "quran.88_8_translation": "وُجُوهٌ يَوْمَئِذٍ نَاعِمَةٌ",
    "quran.88_9_translation": "لِسَعْيِهَا رَاضِيَةٌ",
    "quran.88_10_translation": "فِي جَنَّةٍ عَالِيَةٍ",
    "quran.88_11_translation": "لَا تَسْمَعُ فِيهَا لَاغِيَةً",
    "quran.88_12_translation": "فِيهَا عَيْنٌ جَارِيَةٌ",
    "quran.88_13_translation": "فِيهَا سُرُرٌ مَرْفُوعَةٌ",
    "quran.88_14_translation": "وَأَكْوَابٌ مَوْضُوعَةٌ",
    "quran.88_15_translation": "وَنَمَارِقُ مَصْفُوفَةٌ",
    "quran.88_16_translation": "وَزَرَابِيُّ مَبْثُوثَةٌ",
    "quran.88_17_translation": "أَفَلَا يَنْظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ",
    "quran.88_18_translation": "وَإِلَى السَّمَاءِ كَيْفَ رُفِعَتْ",
    "quran.88_19_translation": "وَإِلَى الْجِبَالِ كَيْفَ نُصِبَتْ",
    "quran.88_20_translation": "وَإِلَى الْأَرْضِ كَيْفَ سُطِحَتْ",
    "quran.88_21_translation": "فَذَكِّرْ إِنَّمَا أَنْتَ مُذَكِّرٌ",
    "quran.88_22_translation": "لَسْتَ عَلَيْهِمْ بِمُصَيْطِرٍ",
    "quran.88_23_translation": "إِلَّا مَنْ تَوَلَّىٰ وَكَفَرَ",
    "quran.88_24_translation": "فَيُعَذِّبُهُ اللَّهُ الْعَذَابَ الْأَكْبَرَ",
    "quran.88_25_translation": "إِنَّ إِلَيْنَا إِيَابَهُمْ",
    "quran.88_26_translation": "ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُمْ",
    "quran.87_1_translation": "سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى",
    "quran.87_2_translation": "الَّذِي خَلَقَ فَسَوَّىٰ",
    "quran.87_3_translation": "وَالَّذِي قَدَّرَ فَهَدَىٰ",
    "quran.87_4_translation": "وَالَّذِي أَخْرَجَ الْمَرْعَىٰ",
    "quran.87_5_translation": "فَجَعَلَهُ غُثَاءً أَحْوَىٰ",
    "quran.87_6_translation": "سَنُقْرِئُكَ فَلَا تَنْسَىٰ",
    "quran.87_7_translation": "إِلَّا مَا شَاءَ اللَّهُ ۚ إِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفَىٰ",
    "quran.87_8_translation": "وَنُيَسِّرُكَ لِلْيُسْرَىٰ",
    "quran.87_9_translation": "فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرَىٰ",
    "quran.87_10_translation": "سَيَذَّكَّرُ مَنْ يَخْشَىٰ",
    "quran.87_11_translation": "وَيَتَجَنَّبُهَا الْأَشْقَى",
    "quran.87_12_translation": "الَّذِي يَصْلَى النَّارَ الْكُبْرَىٰ",
    "quran.87_13_translation": "ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ",
    "quran.87_14_translation": "قَدْ أَفْلَحَ مَنْ تَزَكَّىٰ",
    "quran.87_15_translation": "وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّىٰ",
    "quran.87_16_translation": "بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا",
    "quran.87_17_translation": "وَالْآخِرَةُ خَيْرٌ وَأَبْقَىٰ",
    "quran.87_18_translation": "إِنَّ هَٰذَا لَفِي الصُّحُفِ الْأُولَىٰ",
    "quran.87_19_translation": "صُحُفِ إِبْرَاهِيمَ وَمُوسَىٰ",
    "quran.86_1_translation": "وَالسَّمَاءِ وَالطَّارِقِ",
    "quran.86_2_translation": "وَمَا أَدْرَاكَ مَا الطَّارِقُ",
    "quran.86_3_translation": "النَّجْمُ الثَّاقِبُ",
    "quran.86_4_translation": "إِنْ كُلُّ نَفْسٍ لَمَّا عَلَيْهَا حَافِظٌ",
    "quran.86_5_translation": "فَلْيَنْظُرِ الْإِنْسَانُ مِمَّ خُلِقَ",
    "quran.86_6_translation": "خُلِقَ مِنْ مَاءٍ دَافِقٍ",
    "quran.86_7_translation": "يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ",
    "quran.86_8_translation": "إِنَّهُ عَلَىٰ رَجْعِهِ لَقَادِرٌ",
    "quran.86_9_translation": "يَوْمَ تُبْلَى السَّرَائِرُ",
    "quran.86_10_translation": "فَمَا لَهُ مِنْ قُوَّةٍ وَلَا نَاصِرٍ",
    "quran.86_11_translation": "وَالسَّمَاءِ ذَاتِ الرَّجْعِ",
    "quran.86_12_translation": "وَالْأَرْضِ ذَاتِ الصَّدْعِ",
    "quran.86_13_translation": "إِنَّهُ لَقَوْلٌ فَصْلٌ",
    "quran.86_14_translation": "وَمَا هُوَ بِالْهَزْلِ",
    "quran.86_15_translation": "إِنَّهُمْ يَكِيدُونَ كَيْدًا",
    "quran.86_16_translation": "وَأَكِيدُ كَيْدًا",
    "quran.86_17_translation": "فَمَهِّلِ الْكَافِرِينَ أَمْهِلْهُمْ رُوَيْدًا",
    "quran.85_1_translation": "وَالسَّمَاءِ ذَاتِ الْبُرُوجِ",
    "quran.85_2_translation": "وَالْيَوْمِ الْمَوْعُودِ",
    "quran.85_3_translation": "وَشَاهِدٍ وَمَشْهُودٍ",
    "quran.85_4_translation": "قُتِلَ أَصْحَابُ الْأُخْدُودِ",
    "quran.85_5_translation": "النَّارِ ذَاتِ الْوَقُودِ",
    "quran.85_6_translation": "إِذْ هُمْ عَلَيْهَا قُعُودٌ",
    "quran.85_7_translation": "وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٌ",
    "quran.85_8_translation": "وَمَا نَقَمُوا مِنْهُمْ إِلَّا أَنْ يُؤْمِنُوا بِاللَّهِ الْعَزِيزِ الْحَمِيدِ",
    "quran.85_9_translation": "الَّذِي لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ ۚ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ",
    "quran.85_10_translation": "إِنَّ الَّذِينَ فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ ثُمَّ لَمْ يَتُوبُوا فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ الْحَرِيقِ",
    "quran.85_11_translation": "إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ ۚ ذَٰلِكَ الْفَوْزُ الْكَبِيرُ",
    "quran.85_12_translation": "إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ",
    "quran.85_13_translation": "إِنَّهُ هُوَ يُبْدِئُ وَيُعِيدُ",
    "quran.85_14_translation": "وَهُوَ الْغَفُورُ الْوَدُودُ",
    "quran.85_15_translation": "ذُو الْعَرْشِ الْمَجِيدُ",
    "quran.85_16_translation": "فَعَّالٌ لِمَا يُرِيدُ",
    "quran.85_17_translation": "هَلْ أَتَاكَ حَدِيثُ الْجُنُودِ",
    "quran.85_18_translation": "فِرْعَوْنَ وَثَمُودَ",
    "quran.85_19_translation": "بَلِ الَّذِينَ كَفَرُوا فِي تَكْذِيبٍ",
    "quran.85_20_translation": "وَاللَّهُ مِنْ وَرَائِهِمْ مُحِيطٌ",
    "quran.85_21_translation": "بَلْ هُوَ قُرْآنٌ مَجِيدٌ",
    "quran.85_22_translation": "فِي لَوْحٍ مَحْفُوظٍ",
    "quran.84_1_translation": "إِذَا السَّمَاءُ انْشَقَّتْ",
    "quran.84_2_translation": "وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ",
    "quran.84_3_translation": "وَإِذَا الْأَرْضُ مُدَّتْ",
    "quran.84_4_translation": "وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ",
    "quran.84_5_translation": "وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ",
    "quran.84_6_translation": "يَا أَيُّهَا الْإِنْسَانُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًا فَمُلَاقِيهِ",
    "quran.84_7_translation": "فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ",
    "quran.84_8_translation": "فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا",
    "quran.84_9_translation": "وَيَنْقَلِبُ إِلَىٰ أَهْلِهِ مَسْرُورًا",
    "quran.84_10_translation": "وَأَمَّا مَنْ أُوتِيَ كِتَابَهُ وَرَاءَ ظَهْرِهِ",
    "quran.84_11_translation": "فَسَوْفَ يَدْعُو ثُبُورًا",
    "quran.84_12_translation": "وَيَصْلَىٰ سَعِيرًا",
    "quran.84_13_translation": "إِنَّهُ كَانَ فِي أَهْلِهِ مَسْرُورًا",
    "quran.84_14_translation": "إِنَّهُ ظَنَّ أَنْ لَنْ يَحُورَ",
    "quran.84_15_translation": "بَلَىٰ إِنَّ رَبَّهُ كَانَ بِهِ بَصِيرًا",
    "quran.84_16_translation": "فَلَا أُقْسِمُ بِالشَّفَقِ",
    "quran.84_17_translation": "وَاللَّيْلِ وَمَا وَسَقَ",
    "quran.84_18_translation": "وَالْقَمَرِ إِذَا اتَّسَقَ",
    "quran.84_19_translation": "لَتَرْكَبُنَّ طَبَقًا عَنْ طَبَقٍ",
    "quran.84_20_translation": "فَمَا لَهُمْ لَا يُؤْمِنُونَ",
    "quran.84_21_translation": "وَإِذَا قُرِئَ عَلَيْهِمُ الْقُرْآنُ لَا يَسْجُدُونَ ۩",
    "quran.84_22_translation": "بَلِ الَّذِينَ كَفَرُوا يُكَذِّبُونَ",
    "quran.84_23_translation": "وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ",
    "quran.84_24_translation": "فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ",
    "quran.84_25_translation": "إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ",
    "quran.83_1_translation": "وَيْلٌ لِلْمُطَفِّفِينَ",
    "quran.83_2_translation": "الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ",
    "quran.83_3_translation": "وَإِذَا كَالُوهُمْ أَوْ وَزَنُوهُمْ يُخْسِرُونَ",
    "quran.83_4_translation": "أَلَا يَظُنُّ أُولَٰئِكَ أَنَّهُمْ مَبْعُوثُونَ",
    "quran.83_5_translation": "لِيَوْمٍ عَظِيمٍ",
    "quran.83_6_translation": "يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ",
    "quran.83_7_translation": "كَلَّا إِنَّ كِتَابَ الْفُجَّارِ لَفِي سِجِّينٍ",
    "quran.83_8_translation": "وَمَا أَدْرَاكَ مَا سِجِّينٌ",
    "quran.83_9_translation": "كِتَابٌ مَرْقُومٌ",
    "quran.83_10_translation": "وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ",
    "quran.83_11_translation": "الَّذِينَ يُكَذِّبُونَ بِيَوْمِ الدِّينِ",
    "quran.83_12_translation": "وَمَا يُكَذِّبُ بِهِ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ",
    "quran.83_13_translation": "إِذَا تُتْلَىٰ عَلَيْهِ آيَاتُنَا قَالَ أَسَاطِيرُ الْأَوَّلِينَ",
    "quran.83_14_translation": "كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ",
    "quran.83_15_translation": "كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ",
    "quran.83_16_translation": "ثُمَّ إِنَّهُمْ لَصَالُو الْجَحِيمِ",
    "quran.83_17_translation": "ثُمَّ يُقَالُ هَٰذَا الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ",
    "quran.83_18_translation": "كَلَّا إِنَّ كِتَابَ الْأَبْرَارِ لَفِي عِلِّيِّينَ",
    "quran.83_19_translation": "وَمَا أَدْرَاكَ مَا عِلِّيُّونَ",
    "quran.83_20_translation": "كِتَابٌ مَرْقُومٌ",
    "quran.83_21_translation": "يَشْهَدُهُ الْمُقَرَّبُونَ",
    "quran.83_22_translation": "إِنَّ الْأَبْرَارَ لَفِي نَعِيمٍ",
    "quran.83_23_translation": "عَلَى الْأَرَائِكِ يَنْظُرُونَ",
    "quran.83_24_translation": "تَعْرِفُ فِي وُجُوهِهِمْ نَضْرَةَ النَّعِيمِ",
    "quran.83_25_translation": "يُسْقَوْنَ مِنْ رَحِيقٍ مَخْتُومٍ",
    "quran.83_26_translation": "خِتَامُهُ مِسْكٌ ۚ وَفِي ذَٰلِكَ فَلْيَتَنَافَسِ الْمُتَنَافِسُونَ",
    "quran.83_27_translation": "وَمِزَاجُهُ مِنْ تَسْنِيمٍ",
    "quran.83_28_translation": "عَيْنًا يَشْرَبُ بِهَا الْمُقَرَّبُونَ",
    "quran.83_29_translation": "إِنَّ الَّذِينَ أَجْرَمُوا كَانُوا مِنَ الَّذِينَ آمَنُوا يَضْحَكُونَ",
    "quran.83_30_translation": "وَإِذَا مَرُّوا بِهِمْ يَتَغَامَزُونَ",
    "quran.83_31_translation": "وَإِذَا انْقَلَبُوا إِلَىٰ أَهْلِهِمُ انْقَلَبُوا فَكِهِينَ",
    "quran.83_32_translation": "وَإِذَا رَأَوْهُمْ قَالُوا إِنَّ هَٰؤُلَاءِ لَضَالُّونَ",
    "quran.83_33_translation": "وَمَا أُرْسِلُوا عَلَيْهِمْ حَافِظِينَ",
    "quran.83_34_translation": "فَالْيَوْمَ الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ",
    "quran.83_35_translation": "عَلَى الْأَرَائِكِ يَنْظُرُونَ",
    "quran.83_36_translation": "هَلْ ثُوِّبَ الْكُفَّارُ مَا كَانُوا يَفْعَلُونَ",
    "quran.82_1_translation": "إِذَا السَّمَاءُ انْفَطَرَتْ",
    "quran.82_2_translation": "وَإِذَا الْكَوَاكِبُ انْتَثَرَتْ",
    "quran.82_3_translation": "وَإِذَا الْبِحَارُ فُجِّرَتْ",
    "quran.82_4_translation": "وَإِذَا الْقُبُورُ بُعْثِرَتْ",
    "quran.82_5_translation": "عَلِمَتْ نَفْسٌ مَا قَدَّمَتْ وَأَخَّرَتْ",
    "quran.82_6_translation": "يَا أَيُّهَا الْإِنْسَانُ مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ",
    "quran.82_7_translation": "الَّذِي خَلَقَكَ فَسَوَّاكَ فَعَدَلَكَ",
    "quran.82_8_translation": "فِي أَيِّ صُورَةٍ مَا شَاءَ رَكَّبَكَ",
    "quran.82_9_translation": "كَلَّا بَلْ تُكَذِّبُونَ بِالدِّينِ",
    "quran.82_10_translation": "وَإِنَّ عَلَيْكُمْ لَحَافِظِينَ",
    "quran.82_11_translation": "كِرَامًا كَاتِبِينَ",
    "quran.82_12_translation": "يَعْلَمُونَ مَا تَفْعَلُونَ",
    "quran.82_13_translation": "إِنَّ الْأَبْرَارَ لَفِي نَعِيمٍ",
    "quran.82_14_translation": "وَإِنَّ الْفُجَّارَ لَفِي جَحِيمٍ",
    "quran.82_15_translation": "يَصْلَوْنَهَا يَوْمَ الدِّينِ",
    "quran.82_16_translation": "وَمَا هُمْ عَنْهَا بِغَائِبِينَ",
    "quran.82_17_translation": "وَمَا أَدْرَاكَ مَا يَوْمُ الدِّينِ",
    "quran.82_18_translation": "ثُمَّ مَا أَدْرَاكَ مَا يَوْمُ الدِّينِ",
    "quran.82_19_translation": "يَوْمَ لَا تَمْلِكُ نَفْسٌ لِنَفْسٍ شَيْئًا ۖ وَالْأَمْرُ يَوْمَئِذٍ لِلَّهِ",
    "quran.81_1_translation": "إِذَا الشَّمْسُ كُوِّرَتْ",
    "quran.81_2_translation": "وَإِذَا النُّجُومُ انْكَدَرَتْ",
    "quran.81_3_translation": "وَإِذَا الْجِبَالُ سُيِّرَتْ",
    "quran.81_4_translation": "وَإِذَا الْعِشَارُ عُطِّلَتْ",
    "quran.81_5_translation": "وَإِذَا الْوُحُوشُ حُشِرَتْ",
    "quran.81_6_translation": "وَإِذَا الْبِحَارُ سُجِّرَتْ",
    "quran.81_7_translation": "وَإِذَا النُّفُوسُ زُوِّجَتْ",
    "quran.81_8_translation": "وَإِذَا الْمَوْءُودَةُ سُئِلَتْ",
    "quran.81_9_translation": "بِأَيِّ ذَنْبٍ قُتِلَتْ",
    "quran.81_10_translation": "وَإِذَا الصُّحُفُ نُشِرَتْ",
    "quran.81_11_translation": "وَإِذَا السَّمَاءُ كُشِطَتْ",
    "quran.81_12_translation": "وَإِذَا الْجَحِيمُ سُعِّرَتْ",
    "quran.81_13_translation": "وَإِذَا الْجَنَّةُ أُزْلِفَتْ",
    "quran.81_14_translation": "عَلِمَتْ نَفْسٌ مَا أَحْضَرَتْ",
    "quran.81_15_translation": "فَلَا أُقْسِمُ بِالْخُنَّسِ",
    "quran.81_16_translation": "الْجَوَارِ الْكُنَّسِ",
    "quran.81_17_translation": "وَاللَّيْلِ إِذَا عَسْعَسَ",
    "quran.81_18_translation": "وَالصُّبْحِ إِذَا تَنَفَّسَ",
    "quran.81_19_translation": "إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ",
    "quran.81_20_translation": "ذِي قُوَّةٍ عِنْدَ ذِي الْعَرْشِ مَكِينٍ",
    "quran.81_21_translation": "مُطَاعٍ ثَمَّ أَمِينٍ",
    "quran.81_22_translation": "وَمَا صَاحِبُكُمْ بِمَجْنُونٍ",
    "quran.81_23_translation": "وَلَقَدْ رَآهُ بِالْأُفُقِ الْمُبِينِ",
    "quran.81_24_translation": "وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ",
    "quran.81_25_translation": "وَمَا هُوَ بِقَوْلِ شَيْطَانٍ رَجِيمٍ",
    "quran.81_26_translation": "فَأَيْنَ تَذْهَبُونَ",
    "quran.81_27_translation": "إِنْ هُوَ إِلَّا ذِكْرٌ لِلْعَالَمِينَ",
    "quran.81_28_translation": "لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ",
    "quran.81_29_translation": "وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ",
    "quran.79_1_translation": "وَالنَّازِعَاتِ غَرْقًا",
    "quran.79_2_translation": "وَالنَّاشِطَاتِ نَشْطًا",
    "quran.79_3_translation": "وَالسَّابِحَاتِ سَبْحًا",
    "quran.79_4_translation": "فَالسَّابِقَاتِ سَبْقًا",
    "quran.79_5_translation": "فَالْمُدَبِّرَاتِ أَمْرًا",
    "quran.79_6_translation": "يَوْمَ تَرْجُفُ الرَّاجِفَةُ",
    "quran.79_7_translation": "تَتْبَعُهَا الرَّادِفَةُ",
    "quran.79_8_translation": "قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ",
    "quran.79_9_translation": "أَبْصَارُهَا خَاشِعَةٌ",
    "quran.79_10_translation": "يَقُولُونَ أَإِنَّا لَمَرْدُودُونَ فِي الْحَافِرَةِ",
    "quran.79_11_translation": "أَإِذَا كُنَّا عِظَامًا نَخِرَةً",
    "quran.79_12_translation": "قَالُوا تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ",
    "quran.79_13_translation": "فَإِنَّمَا هِيَ زَجْرَةٌ وَاحِدَةٌ",
    "quran.79_14_translation": "فَإِذَا هُمْ بِالسَّاهِرَةِ",
    "quran.79_15_translation": "هَلْ أَتَاكَ حَدِيثُ مُوسَىٰ",
    "quran.79_16_translation": "إِذْ نَادَاهُ رَبُّهُ بِالْوَادِ الْمُقَدَّسِ طُوًى",
    "quran.79_17_translation": "اذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُ طَغَىٰ",
    "quran.79_18_translation": "فَقُلْ هَلْ لَكَ إِلَىٰ أَنْ تَزَكَّىٰ",
    "quran.79_19_translation": "وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ",
    "quran.79_20_translation": "فَأَرَاهُ الْآيَةَ الْكُبْرَىٰ",
    "quran.79_21_translation": "فَكَذَّبَ وَعَصَىٰ",
    "quran.79_22_translation": "ثُمَّ أَدْبَرَ يَسْعَىٰ",
    "quran.79_23_translation": "فَحَشَرَ فَنَادَىٰ",
    "quran.79_24_translation": "فَقَالَ أَنَا رَبُّكُمُ الْأَعْلَىٰ",
    "quran.79_25_translation": "فَأَخَذَهُ اللَّهُ نَكَالَ الْآخِرَةِ وَالْأُولَىٰ",
    "quran.79_26_translation": "إِنَّ فِي ذَٰلِكَ لَعِبْرَةً لِمَنْ يَخْشَىٰ",
    "quran.79_27_translation": "أَأَنْتُمْ أَشَدُّ خَلْقًا أَمِ السَّمَاءُ ۚ بَنَاهَا",
    "quran.79_28_translation": "رَفَعَ سَمْكَهَا فَسَوَّاهَا",
    "quran.79_29_translation": "وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَاهَا",
    "quran.79_30_translation": "وَالْأَرْضَ بَعْدَ ذَٰلِكَ دَحَاهَا",
    "quran.79_31_translation": "أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا",
    "quran.79_32_translation": "وَالْجِبَالَ أَرْسَاهَا",
    "quran.79_33_translation": "مَتَاعًا لَكُمْ وَلِأَنْعَامِكُمْ",
    "quran.79_34_translation": "فَإِذَا جَاءَتِ الطَّامَّةُ الْكُبْرَىٰ",
    "quran.79_35_translation": "يَوْمَ يَتَذَكَّرُ الْإِنْسَانُ مَا سَعَىٰ",
    "quran.79_36_translation": "وَبُرِّزَتِ الْجَحِيمُ لِمَنْ يَرَىٰ",
    "quran.79_37_translation": "فَأَمَّا مَنْ طَغَىٰ",
    "quran.79_38_translation": "وَآثَرَ الْحَيَاةَ الدُّنْيَا",
    "quran.79_39_translation": "فَإِنَّ الْجَحِيمَ هِيَ الْمَأْوَىٰ",
    "quran.79_40_translation": "وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَىٰ",
    "quran.79_41_translation": "فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَىٰ",
    "quran.79_42_translation": "يَسْأَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْسَاهَا",
    "quran.79_43_translation": "فِيمَ أَنْتَ مِنْ ذِكْرَاهَا",
    "quran.79_44_translation": "إِلَىٰ رَبِّكَ مُنْتَهَاهَا",
    "quran.79_45_translation": "إِنَّمَا أَنْتَ مُنْذِرُ مَنْ يَخْشَاهَا",
    "quran.79_46_translation": "كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوا إِلَّا عَشِيَّةً أَوْ ضُحَاهَا",
    "quran.78_1_translation": "عَمَّ يَتَسَاءَلُونَ",
    "quran.78_2_translation": "عَنِ النَّبَإِ الْعَظِيمِ",
    "quran.78_3_translation": "الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ",
    "quran.78_4_translation": "كَلَّا سَيَعْلَمُونَ",
    "quran.78_5_translation": "ثُمَّ كَلَّا سَيَعْلَمُونَ",
    "quran.78_6_translation": "أَلَمْ نَجْعَلِ الْأَرْضَ مِهَادًا",
    "quran.78_7_translation": "وَالْجِبَالَ أَوْتَادًا",
    "quran.78_8_translation": "وَخَلَقْنَاكُمْ أَزْوَاجًا",
    "quran.78_9_translation": "وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا",
    "quran.78_10_translation": "وَجَعَلْنَا اللَّيْلَ لِبَاسًا",
    "quran.78_11_translation": "وَجَعَلْنَا النَّهَارَ مَعَاشًا",
    "quran.78_12_translation": "وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا",
    "quran.78_13_translation": "وَجَعَلْنَا سِرَاجًا وَهَّاجًا",
    "quran.78_14_translation": "وَأَنْزَلْنَا مِنَ الْمُعْصِرَاتِ مَاءً ثَجَّاجًا",
    "quran.78_15_translation": "لِنُخْرِجَ بِهِ حَبًّا وَنَبَاتًا",
    "quran.78_16_translation": "وَجَنَّاتٍ أَلْفَافًا",
    "quran.78_17_translation": "إِنَّ يَوْمَ الْفَصْلِ كَانَ مِيقَاتًا",
    "quran.78_18_translation": "يَوْمَ يُنْفَخُ فِي الصُّورِ فَتَأْتُونَ أَفْوَاجًا",
    "quran.78_19_translation": "وَفُتِحَتِ السَّمَاءُ فَكَانَتْ أَبْوَابًا",
    "quran.78_20_translation": "وَسُيِّرَتِ الْجِبَالُ فَكَانَتْ سَرَابًا",
    "quran.78_21_translation": "إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا",
    "quran.78_22_translation": "لِلطَّاغِينَ مَآبًا",
    "quran.78_23_translation": "لَابِثِينَ فِيهَا أَحْقَابًا",
    "quran.78_24_translation": "لَا يَذُوقُونَ فِيهَا بَرْدًا وَلَا شَرَابًا",
    "quran.78_25_translation": "إِلَّا حَمِيمًا وَغَسَّاقًا",
    "quran.78_26_translation": "جَزَاءً وِفَاقًا",
    "quran.78_27_translation": "إِنَّهُمْ كَانُوا لَا يَرْجُونَ حِسَابًا",
    "quran.78_28_translation": "وَكَذَّبُوا بِآيَاتِنَا كِذَّابًا",
    "quran.78_29_translation": "وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ كِتَابًا",
    "quran.78_30_translation": "فَذُوقُوا فَلَنْ نَزِيدَكُمْ إِلَّا عَذَابًا",
    "quran.78_31_translation": "إِنَّ لِلْمُتَّقِينَ مَفَازًا",
    "quran.78_32_translation": "حَدَائِقَ وَأَعْنَابًا",
    "quran.78_33_translation": "وَكَوَاعِبَ أَتْرَابًا",
    "quran.78_34_translation": "وَكَأْسًا دِهَاقًا",
    "quran.78_35_translation": "لَا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا كِذَّابًا",
    "quran.78_36_translation": "جَزَاءً مِنْ رَبِّكَ عَطَاءً حِسَابًا",
    "quran.78_37_translation": "رَبِّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الرَّحْمَٰنِ ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًا",
    "quran.78_38_translation": "يَوْمَ يَقُومُ الرُّوحُ وَالْمَلَائِكَةُ صَفًّا ۖ لَا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ الرَّحْمَٰنُ وَقَالَ صَوَابًا",
    "quran.78_39_translation": "ذَٰلِكَ الْيَوْمُ الْحَقُّ ۖ فَمَنْ شَاءَ اتَّخَذَ إِلَىٰ رَبِّهِ مَآبًا",
    "quran.78_40_translation": "إِنَّا أَنْذَرْنَاكُمْ عَذَابًا قَرِيبًا يَوْمَ يَنْظُرُ الْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ الْكَافِرُ يَا لَيْتَنِي كُنْتُ تُرَابًا"
  }
};
